/* WP-PROF-T4: byte-authoritative immutable rehearsal material. */ BEGIN; DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='ple_rehearsal_source') THEN CREATE ROLE ple_rehearsal_source NOLOGIN NOINHERIT NOBYPASSRLS NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE roleid='ple_rehearsal_source'::regrole OR member='ple_rehearsal_source'::regrole) THEN RAISE EXCEPTION 'ple_rehearsal_source must have no memberships' USING ERRCODE='55000'; END IF;
END $$; ALTER ROLE ple_rehearsal_source SET search_path TO pg_catalog,public,pg_temp; GRANT USAGE ON SCHEMA public TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_current_tenant() TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_prepare_rehearsal_operation(
    uuid, uuid, uuid, integer, bigint, bigint
) TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_now(),public.ple_rehearsal_now_millis(),public.ple_rehearsal_timestamp_from_millis(bigint) TO ple_rehearsal_source; ALTER TABLE public.rehearsal_start_operation_root ADD CONSTRAINT rehearsal_start_root_operation_run_unique UNIQUE(tenant_id,operation_id,resulting_run_id); CREATE TABLE public.rehearsal_frozen_material_set(
 tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,start_operation_id uuid NOT NULL,assignment_revision bigint NOT NULL,expected_item_count integer NOT NULL,frozen_item_count integer NOT NULL,source_set_digest bytea NOT NULL,frozen_inventory_digest bytea NOT NULL,subject_time_limit_seconds integer,schema_version smallint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),
 PRIMARY KEY(tenant_id,rehearsal_run_id),FOREIGN KEY(tenant_id,rehearsal_run_id) REFERENCES public.rehearsal_run(tenant_id,rehearsal_run_id) ON DELETE RESTRICT,FOREIGN KEY(tenant_id,start_operation_id,rehearsal_run_id) REFERENCES public.rehearsal_start_operation_root(tenant_id,operation_id,resulting_run_id) ON DELETE RESTRICT,
 CHECK(assignment_revision>0 AND expected_item_count>0 AND frozen_item_count=expected_item_count AND schema_version=1 AND (subject_time_limit_seconds IS NULL OR subject_time_limit_seconds>0)),CHECK(octet_length(source_set_digest)=32 AND octet_length(frozen_inventory_digest)=32)); CREATE TABLE public.rehearsal_frozen_source_snapshot(
 tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,attempt_id uuid NOT NULL,ordinal integer NOT NULL,assignment_item_id uuid NOT NULL,problem_id uuid NOT NULL,version_id uuid NOT NULL,response_definition jsonb NOT NULL,response_schema_digest bytea NOT NULL,canonical_content_digest bytea NOT NULL,deterministic_seed bigint NOT NULL,selection_algorithm_version integer NOT NULL,issued_snapshot_bytes bytea NOT NULL,issued_snapshot_sha256 bytea NOT NULL,timing_kind text NOT NULL,timing_seconds integer,timing_grace_seconds integer,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),
 PRIMARY KEY(tenant_id,rehearsal_run_id,attempt_id),UNIQUE(tenant_id,rehearsal_run_id,ordinal),FOREIGN KEY(tenant_id,rehearsal_run_id) REFERENCES public.rehearsal_frozen_material_set(tenant_id,rehearsal_run_id) ON DELETE RESTRICT,FOREIGN KEY(tenant_id,rehearsal_run_id,attempt_id) REFERENCES public.rehearsal_frozen_item(tenant_id,rehearsal_run_id,attempt_id) ON DELETE RESTRICT,
 CHECK(ordinal>=0 AND selection_algorithm_version>0 AND timing_kind IN('untimed','perQuestion','perAttempt') AND ((timing_kind='untimed' AND timing_seconds IS NULL AND timing_grace_seconds IS NULL) OR (timing_kind<>'untimed' AND timing_seconds IS NOT NULL AND timing_grace_seconds IS NOT NULL AND timing_seconds>=0 AND timing_grace_seconds>=0))),CHECK(jsonb_typeof(response_definition)='object' AND public.ple_rehearsal_jsonb_bytes(response_definition)<=262144),CHECK(octet_length(response_schema_digest)=32 AND octet_length(canonical_content_digest)=32),CHECK(octet_length(issued_snapshot_bytes) BETWEEN 2 AND 524288 AND octet_length(issued_snapshot_sha256)=32 AND digest(issued_snapshot_bytes,'sha256')=issued_snapshot_sha256)); CREATE TABLE public.rehearsal_frozen_private_execution(
 tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,attempt_id uuid NOT NULL,private_execution_bytes bytea NOT NULL,private_execution_sha256 bytea NOT NULL,issued_snapshot_sha256 bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),PRIMARY KEY(tenant_id,rehearsal_run_id,attempt_id),FOREIGN KEY(tenant_id,rehearsal_run_id,attempt_id) REFERENCES public.rehearsal_frozen_source_snapshot(tenant_id,rehearsal_run_id,attempt_id) ON DELETE RESTRICT,CHECK(octet_length(private_execution_bytes) BETWEEN 2 AND 524288 AND octet_length(private_execution_sha256)=32 AND octet_length(issued_snapshot_sha256)=32 AND digest(private_execution_bytes,'sha256')=private_execution_sha256)); CREATE TABLE public.rehearsal_delivery_generation_material_binding(
 tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,root_id uuid NOT NULL,generation integer NOT NULL,operation_id uuid NOT NULL,attempt_id uuid NOT NULL,material_set_digest bytea NOT NULL,issued_snapshot_sha256 bytea NOT NULL,private_execution_sha256 bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),PRIMARY KEY(tenant_id,rehearsal_run_id,root_id,generation),UNIQUE(tenant_id,rehearsal_run_id,operation_id),FOREIGN KEY(tenant_id,rehearsal_run_id,root_id,generation) REFERENCES public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,root_id,generation) ON DELETE RESTRICT,FOREIGN KEY(tenant_id,rehearsal_run_id,operation_id) REFERENCES public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,operation_id) ON DELETE RESTRICT,FOREIGN KEY(tenant_id,rehearsal_run_id,attempt_id) REFERENCES public.rehearsal_frozen_source_snapshot(tenant_id,rehearsal_run_id,attempt_id) ON DELETE RESTRICT,CHECK(octet_length(material_set_digest)=32 AND octet_length(issued_snapshot_sha256)=32 AND octet_length(private_execution_sha256)=32)); ALTER TABLE public.rehearsal_delivery_operation_root
    ADD COLUMN selected_attempt_id uuid,
    ADD COLUMN issue_cycle integer; ALTER TABLE public.rehearsal_delivery_operation_root
    ADD CONSTRAINT rehearsal_delivery_root_selected_attempt_check
        CHECK (selected_attempt_id IS NOT NULL AND issue_cycle >= 1),
    ADD CONSTRAINT rehearsal_delivery_root_selected_attempt_fk
        FOREIGN KEY (tenant_id, rehearsal_run_id, selected_attempt_id)
        REFERENCES public.rehearsal_frozen_item(tenant_id, rehearsal_run_id, attempt_id)
        ON DELETE RESTRICT,
    ADD CONSTRAINT rehearsal_delivery_root_issue_cycle_unique
        UNIQUE (tenant_id, rehearsal_run_id, selected_attempt_id, issue_cycle); CREATE TABLE public.rehearsal_accepted_attempt_integrity (
    tenant_id uuid NOT NULL,
    rehearsal_run_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    claim_id uuid NOT NULL,
    evidence_sequence bigint NOT NULL,
    evidence_digest bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),
    PRIMARY KEY (tenant_id, rehearsal_run_id, attempt_id),
    UNIQUE (tenant_id, rehearsal_run_id, claim_id),
    FOREIGN KEY (tenant_id, rehearsal_run_id, attempt_id)
        REFERENCES public.rehearsal_frozen_source_snapshot(tenant_id, rehearsal_run_id, attempt_id)
        ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id, rehearsal_run_id, claim_id)
        REFERENCES public.rehearsal_submission_claim_root(tenant_id, rehearsal_run_id, claim_id)
