    CHECK (octet_length(evidence_digest) = 32)
);
-- Issued artifacts must exist before their binding verifier is compiled.
CREATE TABLE public.rehearsal_delivery_issued_execution_artifact(
 tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,root_id uuid NOT NULL,
 generation integer NOT NULL,operation_id uuid NOT NULL,attempt_id uuid NOT NULL,
 material_set_digest bytea NOT NULL,issued_snapshot_sha256 bytea NOT NULL,
 private_execution_sha256 bytea NOT NULL,artifact_bytes bytea NOT NULL,
 artifact_sha256 bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),
 PRIMARY KEY(tenant_id,rehearsal_run_id,root_id,generation),UNIQUE(tenant_id,rehearsal_run_id,operation_id),
 FOREIGN KEY(tenant_id,rehearsal_run_id,root_id,generation) REFERENCES public.rehearsal_delivery_generation_material_binding(tenant_id,rehearsal_run_id,root_id,generation) ON DELETE RESTRICT,
 FOREIGN KEY(tenant_id,rehearsal_run_id,operation_id) REFERENCES public.rehearsal_delivery_generation_material_binding(tenant_id,rehearsal_run_id,operation_id) ON DELETE RESTRICT,
 CHECK(octet_length(material_set_digest)=32 AND octet_length(issued_snapshot_sha256)=32 AND octet_length(private_execution_sha256)=32 AND octet_length(artifact_bytes) BETWEEN 2 AND 524288 AND octet_length(artifact_sha256)=32 AND digest(artifact_bytes,'sha256')=artifact_sha256)
);
-- The live start broker captures ordinary assignment inventory; every provenance row names one active ordinary item.
CREATE TABLE public.rehearsal_start_freeze_source_binding(
 tenant_id uuid NOT NULL,operation_id uuid NOT NULL,ordinal integer NOT NULL,
 assignment_item_id uuid NOT NULL,problem_id uuid NOT NULL,version_id uuid NOT NULL,
 family_capability text NOT NULL,
 PRIMARY KEY(tenant_id,operation_id,ordinal),
 UNIQUE(tenant_id,operation_id,assignment_item_id),
 FOREIGN KEY(tenant_id,operation_id) REFERENCES public.rehearsal_start_operation_root(tenant_id,operation_id) ON DELETE RESTRICT,
    CHECK(ordinal>=0 AND char_length(family_capability) BETWEEN 1 AND 256)
); CREATE FUNCTION public.ple_rehearsal_material_append_only() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF TG_OP IN('UPDATE','DELETE') THEN RAISE EXCEPTION 'rehearsal material is immutable' USING ERRCODE='55000'; END IF; RETURN NEW; END $$; CREATE TRIGGER rehearsal_material_set_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_frozen_material_set FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE TRIGGER rehearsal_source_snapshot_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_frozen_source_snapshot FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE TRIGGER rehearsal_private_execution_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_frozen_private_execution FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE TRIGGER rehearsal_material_binding_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_delivery_generation_material_binding FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE TRIGGER rehearsal_start_freeze_source_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_start_freeze_source_binding FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE TRIGGER rehearsal_accepted_attempt_integrity_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_accepted_attempt_integrity FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); CREATE FUNCTION public.ple_copy_rehearsal_generation_material_binding()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog,public,pg_temp AS $$
BEGIN
    IF NEW.generation > 1 THEN
        INSERT INTO public.rehearsal_delivery_generation_material_binding (
            tenant_id, rehearsal_run_id, root_id, generation, operation_id,
            attempt_id, material_set_digest, issued_snapshot_sha256,
            private_execution_sha256
        )
        SELECT tenant_id, rehearsal_run_id, root_id, NEW.generation,
               NEW.operation_id, attempt_id, material_set_digest,
               issued_snapshot_sha256, private_execution_sha256
          FROM public.rehearsal_delivery_generation_material_binding
         WHERE tenant_id = NEW.tenant_id
           AND rehearsal_run_id = NEW.rehearsal_run_id
           AND root_id = NEW.root_id
           AND generation = NEW.generation - 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'rehearsal reclaim lacks a prior material binding'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END $$; CREATE TRIGGER rehearsal_generation_copies_material_binding
    AFTER INSERT ON public.rehearsal_delivery_operation_generation
    FOR EACH ROW EXECUTE FUNCTION public.ple_copy_rehearsal_generation_material_binding(); ALTER TABLE public.rehearsal_frozen_material_set ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_frozen_material_set FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_frozen_source_snapshot ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_frozen_source_snapshot FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_frozen_private_execution ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_frozen_private_execution FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_generation_material_binding ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_generation_material_binding FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_start_freeze_source_binding ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_start_freeze_source_binding FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_accepted_attempt_integrity ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_accepted_attempt_integrity FORCE ROW LEVEL SECURITY; CREATE POLICY rehearsal_material_source ON public.rehearsal_frozen_material_set TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_snapshot_source ON public.rehearsal_frozen_source_snapshot TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_private_source ON public.rehearsal_frozen_private_execution TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_binding_source ON public.rehearsal_delivery_generation_material_binding TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_start_freeze_source ON public.rehearsal_start_freeze_source_binding TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_accepted_attempt_source ON public.rehearsal_accepted_attempt_integrity TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_material_broker ON public.rehearsal_frozen_material_set FOR SELECT TO ple_rehearsal_broker USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_snapshot_broker ON public.rehearsal_frozen_source_snapshot FOR SELECT TO ple_rehearsal_broker USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_accepted_attempt_broker ON public.rehearsal_accepted_attempt_integrity FOR SELECT TO ple_rehearsal_broker USING(tenant_id=public.ple_current_tenant()); GRANT SELECT, INSERT ON
    public.rehearsal_frozen_material_set,
    public.rehearsal_frozen_source_snapshot,
    public.rehearsal_frozen_private_execution,
    public.rehearsal_delivery_generation_material_binding,
    public.rehearsal_start_freeze_source_binding,
    public.rehearsal_accepted_attempt_integrity
    TO ple_rehearsal_source; GRANT SELECT ON public.rehearsal_frozen_material_set,public.rehearsal_frozen_source_snapshot,public.rehearsal_accepted_attempt_integrity TO ple_rehearsal_broker; REVOKE ALL ON
    public.rehearsal_frozen_material_set,
    public.rehearsal_frozen_source_snapshot,
    public.rehearsal_frozen_private_execution,
    public.rehearsal_delivery_generation_material_binding,
    public.rehearsal_start_freeze_source_binding,
    public.rehearsal_accepted_attempt_integrity
    FROM PUBLIC, ple_app, ple_student, ple_grader, ple_grading_reader; GRANT SELECT ON public.rehearsal_start_operation_root,public.rehearsal_run,public.rehearsal_frozen_item TO ple_rehearsal_source; GRANT INSERT ON public.rehearsal_start_receipt TO ple_rehearsal_source; GRANT SELECT,INSERT ON public.rehearsal_start_operation_root,public.rehearsal_start_receipt TO ple_rehearsal_broker; GRANT SELECT,INSERT ON public.rehearsal_delivery_admission,public.rehearsal_delivery_operation_root,public.rehearsal_delivery_operation_generation,public.rehearsal_delivery_operation_event,public.rehearsal_delivery_receipt TO ple_rehearsal_source; GRANT SELECT ON public.rehearsal_submission_claim_root,public.rehearsal_submission_claim_event TO ple_rehearsal_source; CREATE POLICY rehearsal_start_root_source ON public.rehearsal_start_operation_root TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_run_source ON public.rehearsal_run TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_frozen_source ON public.rehearsal_frozen_item TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_start_receipt_source ON public.rehearsal_start_receipt TO ple_rehearsal_source WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_admission_source ON public.rehearsal_delivery_admission TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_delivery_root_source ON public.rehearsal_delivery_operation_root TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_generation_source ON public.rehearsal_delivery_operation_generation TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_event_source ON public.rehearsal_delivery_operation_event TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_delivery_receipt_source ON public.rehearsal_delivery_receipt TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_root_source ON public.rehearsal_submission_claim_root TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_event_source ON public.rehearsal_submission_claim_event TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); CREATE FUNCTION public.ple_prepare_rehearsal_start_sources(
    p_tenant uuid, p_actor uuid, p_course uuid, p_assignment_reference integer,
    p_revision bigint, p_operation uuid, p_nonce uuid
) RETURNS TABLE(
    assignment_id uuid, assignment_item_id uuid, problem_id uuid, version_id uuid,
    family_capability text, payload jsonb
) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE root public.rehearsal_start_operation_root%ROWTYPE;
BEGIN
    SELECT * INTO root FROM public.rehearsal_start_operation_root
     WHERE tenant_id=p_tenant AND operation_id=p_operation;
    IF NOT FOUND OR root.prepare_nonce<>p_nonce OR root.prepared_txid<>txid_current()
       OR root.actor_id<>p_actor OR root.course_id<>p_course
       OR NOT EXISTS (SELECT 1 FROM public.rehearsal_run run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=root.resulting_run_id AND run_row.assignment_revision=p_revision AND run_row.assignment_reference=p_assignment_reference) THEN
        RETURN;
    END IF;
    WITH locked_source AS (
      SELECT item.position,item.assignment_item_id,item.problem_id,item.version_id,version_payload.payload
        FROM public.assignment_item item
        JOIN public.problem_version version_row ON version_row.problem_id=item.problem_id AND version_row.version_id=item.version_id
        JOIN public.problem_version_payload version_payload ON version_payload.problem_id=item.problem_id AND version_payload.version_id=item.version_id
       WHERE item.tenant_id=p_tenant AND item.assignment_id=root.assignment_id AND item.delivery_state='active'
       -- 1815 already holds the assignment revision lock; assignment-item
       -- mutators serialize through that authority, and published version
       -- records are immutable.  A SELECT-only source broker therefore does
       -- not need PostgreSQL row-lock privileges on catalog rows here.
       ORDER BY item.position,item.assignment_item_id
    )
    INSERT INTO public.rehearsal_start_freeze_source_binding(
        tenant_id,operation_id,ordinal,assignment_item_id,problem_id,version_id,family_capability
    )
    SELECT p_tenant,p_operation,row_number() OVER(ORDER BY source_row.position,source_row.assignment_item_id)-1,
           source_row.assignment_item_id,source_row.problem_id,source_row.version_id,
           CASE source_row.payload #>> '{question,source,backend}'
             WHEN 'native' THEN 'native:' || COALESCE(source_row.payload #>> '{question,source,family}','')
             ELSE 'unsupported:' || COALESCE(source_row.payload #>> '{question,source,backend}','')
           END
      FROM locked_source source_row
     ORDER BY source_row.position,source_row.assignment_item_id;
    IF NOT FOUND THEN RETURN; END IF;
    RETURN QUERY
    SELECT item.assignment_id, item.assignment_item_id, item.problem_id,
           item.version_id, binding.family_capability, version_payload.payload
      FROM public.assignment_item item
      JOIN public.problem_version version_row
        ON version_row.problem_id = item.problem_id
       AND version_row.version_id = item.version_id
      JOIN public.problem_version_payload version_payload
        ON version_payload.problem_id = item.problem_id
       AND version_payload.version_id = item.version_id
      JOIN public.rehearsal_start_freeze_source_binding binding
        ON binding.tenant_id=p_tenant AND binding.operation_id=p_operation
       AND binding.assignment_item_id=item.assignment_item_id
     WHERE item.tenant_id = p_tenant
       AND item.assignment_id = root.assignment_id
       AND item.delivery_state = 'active'
     ORDER BY binding.ordinal;
END $$; CREATE FUNCTION public.ple_prepare_rehearsal_flat_grading_material(
    p_tenant uuid, p_actor uuid, p_course uuid, p_assignment_reference integer,
    p_revision bigint, p_problem uuid, p_version uuid, p_operation uuid, p_nonce uuid
) RETURNS TABLE(key_payload jsonb, key_sha256 character(64))
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE root public.rehearsal_start_operation_root%ROWTYPE;
BEGIN
    SELECT * INTO root FROM public.rehearsal_start_operation_root
     WHERE tenant_id=p_tenant AND operation_id=p_operation;
    IF NOT FOUND OR root.prepare_nonce<>p_nonce OR root.prepared_txid<>txid_current()
       OR root.actor_id<>p_actor OR root.course_id<>p_course
       OR NOT EXISTS (SELECT 1 FROM public.rehearsal_run run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=root.resulting_run_id AND run_row.assignment_revision=p_revision AND run_row.assignment_reference=p_assignment_reference)
       OR NOT EXISTS (
        SELECT 1 FROM public.rehearsal_start_freeze_source_binding binding
         WHERE binding.tenant_id=p_tenant AND binding.operation_id=p_operation
           AND binding.problem_id=p_problem AND binding.version_id=p_version
    ) THEN RETURN; END IF;
    RETURN QUERY SELECT * FROM public.ple_flat_question_grading_material(
        p_tenant, p_problem, p_version
    );
END $$; GRANT SELECT ON public.assignment, public.assignment_item, public.problem_version,
    public.problem_version_payload, public.answer_key, public.catalog_tenant_grant
    TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_flat_question_grading_material(uuid, uuid, uuid)
    TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_start(
    uuid, uuid, uuid, uuid, integer, bigint, jsonb, bytea, bytea, uuid,
    boolean, uuid
) TO ple_rehearsal_broker; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_terminalize(
    uuid, uuid, uuid, uuid, bigint, uuid, text
) TO ple_rehearsal_source; CREATE POLICY rehearsal_source_assignment_item ON public.assignment_item
    FOR SELECT TO ple_rehearsal_source
    USING (tenant_id = public.ple_current_tenant()); CREATE POLICY rehearsal_source_assignment ON public.assignment FOR SELECT TO ple_rehearsal_source USING (tenant_id = public.ple_current_tenant()); CREATE POLICY rehearsal_source_problem_version ON public.problem_version
    FOR SELECT TO ple_rehearsal_source
    USING (
        publication_scope = 'public'
        OR EXISTS (
            SELECT 1 FROM public.catalog_tenant_grant grant_row
             WHERE grant_row.tenant_id = public.ple_current_tenant()
               AND grant_row.problem_id = problem_version.problem_id
               AND grant_row.version_id = problem_version.version_id
        )
    ); CREATE POLICY rehearsal_source_problem_payload ON public.problem_version_payload
    FOR SELECT TO ple_rehearsal_source
    USING (EXISTS (
        SELECT 1 FROM public.problem_version version_row
         WHERE version_row.problem_id = problem_version_payload.problem_id
           AND version_row.version_id = problem_version_payload.version_id
    )); CREATE POLICY rehearsal_source_catalog_grant ON public.catalog_tenant_grant
    FOR SELECT TO ple_rehearsal_source
    USING (tenant_id = public.ple_current_tenant()); CREATE POLICY rehearsal_source_answer_key ON public.answer_key
    FOR SELECT TO ple_rehearsal_source
    USING (EXISTS (
        SELECT 1 FROM public.problem_version version_row
         WHERE version_row.problem_id = answer_key.problem_id
           AND version_row.version_id = answer_key.version_id
    )); CREATE FUNCTION public.ple_finalize_rehearsal_start_freeze(p_tenant uuid,p_operation uuid,p_nonce uuid,p_witness bytea,p_source_digest bytea,p_count integer,p_assignment_items uuid[],p_attempts uuid[],p_problems uuid[],p_versions uuid[],p_responses jsonb[],p_response_digests bytea[],p_content_digests bytea[],p_seeds bigint[],p_algorithms integer[],p_snapshots bytea[],p_snapshot_digests bytea[],p_private bytea[],p_private_digests bytea[],p_timing_kinds text[],p_timing_seconds integer[],p_timing_grace_seconds integer[],p_subject_time_limit_seconds integer,p_response_bytes bytea,p_response_digest bytea) RETURNS TABLE(response_projection jsonb,response_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE root public.rehearsal_start_operation_root%ROWTYPE;run_row public.rehearsal_run%ROWTYPE;i integer;inventory bytea:=decode(repeat('00',64),'hex');expected_source bytea:='';
BEGIN SELECT * INTO root FROM public.rehearsal_start_operation_root WHERE tenant_id=p_tenant AND operation_id=p_operation;
 IF NOT FOUND OR root.prepare_nonce<>p_nonce OR root.prepared_txid<>txid_current() OR root.structural_witness_digest<>p_witness OR p_count<=0 OR octet_length(p_source_digest)<>32 OR octet_length(p_response_digest)<>32 OR (p_subject_time_limit_seconds IS NOT NULL AND p_subject_time_limit_seconds<=0) OR digest(p_response_bytes,'sha256')<>p_response_digest THEN RETURN; END IF;
 IF array_ndims(p_assignment_items)<>1 OR array_ndims(p_attempts)<>1 OR array_ndims(p_problems)<>1 OR array_ndims(p_versions)<>1 OR array_ndims(p_responses)<>1 OR array_ndims(p_response_digests)<>1 OR array_ndims(p_content_digests)<>1 OR array_ndims(p_seeds)<>1 OR array_ndims(p_algorithms)<>1 OR array_ndims(p_snapshots)<>1 OR array_ndims(p_snapshot_digests)<>1 OR array_ndims(p_private)<>1 OR array_ndims(p_private_digests)<>1 OR array_ndims(p_timing_kinds)<>1 OR array_ndims(p_timing_seconds)<>1 OR array_ndims(p_timing_grace_seconds)<>1 OR array_lower(p_assignment_items,1)<>1 OR array_lower(p_attempts,1)<>1 OR array_lower(p_problems,1)<>1 OR array_lower(p_versions,1)<>1 OR array_lower(p_responses,1)<>1 OR array_lower(p_response_digests,1)<>1 OR array_lower(p_content_digests,1)<>1 OR array_lower(p_seeds,1)<>1 OR array_lower(p_algorithms,1)<>1 OR array_lower(p_snapshots,1)<>1 OR array_lower(p_snapshot_digests,1)<>1 OR array_lower(p_private,1)<>1 OR array_lower(p_private_digests,1)<>1 OR array_lower(p_timing_kinds,1)<>1 OR array_lower(p_timing_seconds,1)<>1 OR array_lower(p_timing_grace_seconds,1)<>1 OR cardinality(p_assignment_items)<>p_count OR cardinality(p_attempts)<>p_count OR cardinality(p_problems)<>p_count OR cardinality(p_versions)<>p_count OR cardinality(p_responses)<>p_count OR cardinality(p_response_digests)<>p_count OR cardinality(p_content_digests)<>p_count OR cardinality(p_seeds)<>p_count OR cardinality(p_algorithms)<>p_count OR cardinality(p_snapshots)<>p_count OR cardinality(p_snapshot_digests)<>p_count OR cardinality(p_private)<>p_count OR cardinality(p_private_digests)<>p_count OR cardinality(p_timing_kinds)<>p_count OR cardinality(p_timing_seconds)<>p_count OR cardinality(p_timing_grace_seconds)<>p_count OR array_position(p_assignment_items,NULL) IS NOT NULL OR array_position(p_attempts,NULL) IS NOT NULL OR array_position(p_problems,NULL) IS NOT NULL OR array_position(p_versions,NULL) IS NOT NULL OR array_position(p_responses,NULL) IS NOT NULL OR array_position(p_response_digests,NULL) IS NOT NULL OR array_position(p_content_digests,NULL) IS NOT NULL OR array_position(p_seeds,NULL) IS NOT NULL OR array_position(p_algorithms,NULL) IS NOT NULL OR array_position(p_snapshots,NULL) IS NOT NULL OR array_position(p_snapshot_digests,NULL) IS NOT NULL OR array_position(p_private,NULL) IS NOT NULL OR array_position(p_private_digests,NULL) IS NOT NULL OR array_position(p_timing_kinds,NULL) IS NOT NULL THEN RETURN; END IF;
 -- `ple_prepare_rehearsal_start_idempotent` already acquired the mutable run
 -- lock in this transaction.  The source broker verifies that same run here
 -- without gaining UPDATE on an append-only aggregate table.
 SELECT * INTO run_row FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=root.resulting_run_id;
 IF NOT FOUND OR (SELECT count(*) FROM public.rehearsal_frozen_item WHERE tenant_id=p_tenant AND rehearsal_run_id=root.resulting_run_id)<>p_count OR (SELECT count(*) FROM public.rehearsal_start_freeze_source_binding WHERE tenant_id=p_tenant AND operation_id=p_operation)<>p_count THEN RETURN; END IF;
 expected_source:=int2send(2::smallint)||int8send(run_row.assignment_revision);
 FOR i IN 1..p_count LOOP IF octet_length(p_response_digests[i])<>32 OR octet_length(p_content_digests[i])<>32 OR octet_length(p_snapshot_digests[i])<>32 OR octet_length(p_private_digests[i])<>32 OR digest(p_snapshots[i],'sha256')<>p_snapshot_digests[i] OR digest(p_private[i],'sha256')<>p_private_digests[i] OR p_algorithms[i]<=0 OR p_timing_kinds[i] NOT IN('untimed','perQuestion','perAttempt') OR (p_timing_kinds[i]='untimed' AND (p_timing_seconds[i] IS NOT NULL OR p_timing_grace_seconds[i] IS NOT NULL)) OR (p_timing_kinds[i]<>'untimed' AND (p_timing_seconds[i] IS NULL OR p_timing_grace_seconds[i] IS NULL OR p_timing_seconds[i]<0 OR p_timing_grace_seconds[i]<0)) OR NOT EXISTS(SELECT 1 FROM public.rehearsal_start_freeze_source_binding binding WHERE binding.tenant_id=p_tenant AND binding.operation_id=p_operation AND binding.ordinal=i-1 AND binding.assignment_item_id=p_assignment_items[i] AND binding.problem_id=p_problems[i] AND binding.version_id=p_versions[i]) OR NOT EXISTS(SELECT 1 FROM public.rehearsal_frozen_item f WHERE f.tenant_id=p_tenant AND f.rehearsal_run_id=root.resulting_run_id AND f.attempt_id=p_attempts[i] AND f.problem_id=p_problems[i] AND f.version_id=p_versions[i] AND f.response_definition=p_responses[i] AND f.response_schema_digest=p_response_digests[i] AND f.canonical_content_digest=p_content_digests[i]) THEN RETURN; END IF;expected_source:=expected_source||int4send(i-1)||uuid_send(p_assignment_items[i])||uuid_send(p_problems[i])||uuid_send(p_versions[i])||p_response_digests[i]||p_content_digests[i]||(SELECT int4send(octet_length(convert_to(binding.family_capability,'UTF8'))) || convert_to(binding.family_capability,'UTF8') FROM public.rehearsal_start_freeze_source_binding binding WHERE binding.tenant_id=p_tenant AND binding.operation_id=p_operation AND binding.ordinal=i-1)||int8send(p_seeds[i])||int4send(p_algorithms[i])||int4send(octet_length(convert_to(p_timing_kinds[i],'UTF8')))||convert_to(p_timing_kinds[i],'UTF8')||CASE WHEN p_timing_seconds[i] IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(p_timing_seconds[i]) END||CASE WHEN p_timing_grace_seconds[i] IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(p_timing_grace_seconds[i]) END;inventory:=digest(inventory||uuid_send(p_attempts[i])||p_snapshot_digests[i]||p_private_digests[i],'sha256');END LOOP;expected_source:=expected_source||CASE WHEN p_subject_time_limit_seconds IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(p_subject_time_limit_seconds) END;IF digest(expected_source,'sha256')<>p_source_digest THEN RETURN;END IF;
 INSERT INTO public.rehearsal_frozen_material_set(tenant_id,rehearsal_run_id,start_operation_id,assignment_revision,expected_item_count,frozen_item_count,source_set_digest,frozen_inventory_digest,subject_time_limit_seconds,schema_version) VALUES(p_tenant,root.resulting_run_id,p_operation,run_row.assignment_revision,p_count,p_count,p_source_digest,inventory,p_subject_time_limit_seconds,1);
 FOR i IN 1..p_count LOOP INSERT INTO public.rehearsal_frozen_source_snapshot(tenant_id,rehearsal_run_id,attempt_id,ordinal,assignment_item_id,problem_id,version_id,response_definition,response_schema_digest,canonical_content_digest,deterministic_seed,selection_algorithm_version,issued_snapshot_bytes,issued_snapshot_sha256,timing_kind,timing_seconds,timing_grace_seconds) VALUES(p_tenant,root.resulting_run_id,p_attempts[i],i-1,p_assignment_items[i],p_problems[i],p_versions[i],p_responses[i],p_response_digests[i],p_content_digests[i],p_seeds[i],p_algorithms[i],p_snapshots[i],p_snapshot_digests[i],p_timing_kinds[i],p_timing_seconds[i],p_timing_grace_seconds[i]);INSERT INTO public.rehearsal_frozen_private_execution(tenant_id,rehearsal_run_id,attempt_id,private_execution_bytes,private_execution_sha256,issued_snapshot_sha256) VALUES(p_tenant,root.resulting_run_id,p_attempts[i],p_private[i],p_private_digests[i],p_snapshot_digests[i]);END LOOP;
 IF NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,root.resulting_run_id) THEN RAISE EXCEPTION 'rehearsal frozen material verification failed' USING ERRCODE='23514'; END IF; INSERT INTO public.rehearsal_start_receipt(tenant_id,operation_id,response_projection,response_digest) VALUES(p_tenant,p_operation,convert_from(p_response_bytes,'UTF8')::jsonb,p_response_digest);RETURN QUERY SELECT convert_from(p_response_bytes,'UTF8')::jsonb,p_response_digest;END $$; CREATE FUNCTION public.ple_verify_rehearsal_frozen_material_set(p_tenant uuid,p_run uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE h public.rehearsal_frozen_material_set%ROWTYPE;r record;source_bytes bytea:='';inventory bytea:=decode(repeat('00',64),'hex');seen integer:=0;
BEGIN
 SELECT * INTO h FROM public.rehearsal_frozen_material_set WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;
 IF NOT FOUND OR h.expected_item_count<=0 OR h.expected_item_count<>h.frozen_item_count OR NOT EXISTS(SELECT 1 FROM public.rehearsal_start_operation_root o JOIN public.rehearsal_run run_row ON(run_row.tenant_id=o.tenant_id AND run_row.rehearsal_run_id=o.resulting_run_id) WHERE o.tenant_id=h.tenant_id AND o.operation_id=h.start_operation_id AND o.resulting_run_id=h.rehearsal_run_id AND run_row.assignment_revision=h.assignment_revision) OR (SELECT count(*) FROM public.rehearsal_start_freeze_source_binding b WHERE b.tenant_id=h.tenant_id AND b.operation_id=h.start_operation_id)<>h.expected_item_count OR (SELECT count(*) FROM public.rehearsal_frozen_item f WHERE f.tenant_id=h.tenant_id AND f.rehearsal_run_id=h.rehearsal_run_id)<>h.expected_item_count OR (SELECT count(*) FROM public.rehearsal_frozen_source_snapshot s WHERE s.tenant_id=h.tenant_id AND s.rehearsal_run_id=h.rehearsal_run_id)<>h.expected_item_count OR (SELECT count(*) FROM public.rehearsal_frozen_private_execution x WHERE x.tenant_id=h.tenant_id AND x.rehearsal_run_id=h.rehearsal_run_id)<>h.expected_item_count THEN RETURN false; END IF;
 source_bytes:=int2send(2::smallint)||int8send(h.assignment_revision);
 FOR r IN SELECT s.*,f.problem_id frozen_problem_id,f.version_id frozen_version_id,f.response_definition frozen_response,f.response_schema_digest frozen_response_digest,f.canonical_content_digest frozen_content_digest,x.private_execution_bytes,x.private_execution_sha256,x.issued_snapshot_sha256 private_snapshot_sha256,b.family_capability,b.assignment_item_id bound_assignment_item,b.problem_id bound_problem,b.version_id bound_version FROM public.rehearsal_frozen_source_snapshot s JOIN public.rehearsal_frozen_item f ON(f.tenant_id=s.tenant_id AND f.rehearsal_run_id=s.rehearsal_run_id AND f.attempt_id=s.attempt_id) JOIN public.rehearsal_frozen_private_execution x ON(x.tenant_id=s.tenant_id AND x.rehearsal_run_id=s.rehearsal_run_id AND x.attempt_id=s.attempt_id) JOIN public.rehearsal_start_freeze_source_binding b ON(b.tenant_id=s.tenant_id AND b.operation_id=h.start_operation_id AND b.ordinal=s.ordinal) WHERE s.tenant_id=h.tenant_id AND s.rehearsal_run_id=h.rehearsal_run_id ORDER BY s.ordinal LOOP
  IF r.ordinal<>seen OR r.assignment_item_id<>r.bound_assignment_item OR r.problem_id<>r.bound_problem OR r.version_id<>r.bound_version OR r.problem_id<>r.frozen_problem_id OR r.version_id<>r.frozen_version_id OR r.response_definition<>r.frozen_response OR r.response_schema_digest<>r.frozen_response_digest OR r.canonical_content_digest<>r.frozen_content_digest OR r.issued_snapshot_sha256<>r.private_snapshot_sha256 OR digest(r.issued_snapshot_bytes,'sha256')<>r.issued_snapshot_sha256 OR digest(r.private_execution_bytes,'sha256')<>r.private_execution_sha256 THEN RETURN false; END IF;
  IF r.timing_kind NOT IN('untimed','perQuestion','perAttempt') OR (r.timing_kind='untimed' AND (r.timing_seconds IS NOT NULL OR r.timing_grace_seconds IS NOT NULL)) OR (r.timing_kind<>'untimed' AND (r.timing_seconds IS NULL OR r.timing_grace_seconds IS NULL OR r.timing_seconds<0 OR r.timing_grace_seconds<0)) THEN RETURN false; END IF; source_bytes:=source_bytes||int4send(r.ordinal)||uuid_send(r.assignment_item_id)||uuid_send(r.problem_id)||uuid_send(r.version_id)||r.response_schema_digest||r.canonical_content_digest||int4send(octet_length(convert_to(r.family_capability,'UTF8')))||convert_to(r.family_capability,'UTF8')||int8send(r.deterministic_seed)||int4send(r.selection_algorithm_version)||int4send(octet_length(convert_to(r.timing_kind,'UTF8')))||convert_to(r.timing_kind,'UTF8')||CASE WHEN r.timing_seconds IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(r.timing_seconds) END||CASE WHEN r.timing_grace_seconds IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(r.timing_grace_seconds) END;inventory:=digest(inventory||uuid_send(r.attempt_id)||r.issued_snapshot_sha256||r.private_execution_sha256,'sha256');seen:=seen+1;
 END LOOP;
 source_bytes:=source_bytes||CASE WHEN h.subject_time_limit_seconds IS NULL THEN decode('00','hex')||int4send(0) ELSE decode('01','hex')||int4send(h.subject_time_limit_seconds) END; RETURN seen=h.expected_item_count AND digest(source_bytes,'sha256')=h.source_set_digest AND inventory=h.frozen_inventory_digest;
END $$; CREATE FUNCTION public.ple_verify_rehearsal_delivery_material_from_route(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint) RETURNS TABLE(material_valid boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE w record; BEGIN SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.rehearsal_run run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=w.rehearsal_run_id AND run_row.lifecycle='active') THEN RETURN;END IF;RETURN QUERY SELECT public.ple_verify_rehearsal_frozen_material_set(p_tenant,w.rehearsal_run_id);END $$; CREATE FUNCTION public.ple_claim_prepared_rehearsal_delivery(
    p_tenant uuid, p_actor uuid, p_course uuid, p_assignment_reference integer,
    p_revision bigint, p_rehearsal_reference bigint, p_key text,
    p_fingerprint bytea, p_nonce uuid, p_admission_digest bytea
) RETURNS TABLE(
    result_kind text, operation_id uuid, execution_descriptor jsonb,
    screen_projection jsonb, screen_digest bytea
) LANGUAGE plpgsql
SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE
    w record;
    admission public.rehearsal_delivery_admission%ROWTYPE;
    source_row public.rehearsal_frozen_source_snapshot%ROWTYPE;
    header public.rehearsal_frozen_material_set%ROWTYPE;
    open_row record;
    root_id uuid := gen_random_uuid();
    operation uuid := gen_random_uuid();
    cycle integer;
    descriptor jsonb;
BEGIN
    IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant()
       OR octet_length(p_fingerprint) <> 32 OR octet_length(p_admission_digest) <> 32 THEN
        RETURN;
    END IF;
    SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(
        p_tenant, p_actor, p_course, p_assignment_reference, p_revision,
        p_rehearsal_reference
    );
    IF NOT FOUND THEN RETURN; END IF;
    SELECT * INTO admission FROM public.rehearsal_delivery_admission
     WHERE tenant_id = p_tenant AND rehearsal_run_id = w.rehearsal_run_id
       AND idempotency_key = p_key;
    IF NOT FOUND OR admission.request_fingerprint <> p_fingerprint
       OR admission.prepare_nonce <> p_nonce OR admission.prepared_txid <> txid_current()
       OR admission.admission_digest <> p_admission_digest THEN
        RETURN;
    END IF;
    -- Verify every frozen sibling and both recomputed commitments before an
    -- ordinal can be selected (ASVS 2.3.1, 11.4.1, 15.4.2).
    IF NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,w.rehearsal_run_id) THEN RETURN; END IF;
    -- An issued or in-flight lowest unresolved item wins over any later
    -- frozen ordinal.  This check happens before source material is read.
    SELECT generation_row.operation_id, receipt.screen_projection, receipt.screen_digest, latest.phase,
           generation_row.selected_attempt_id, generation_row.execution_descriptor
      INTO open_row
      FROM public.rehearsal_delivery_operation_root root
      JOIN LATERAL (
          SELECT * FROM public.rehearsal_delivery_operation_generation generation_row
           WHERE generation_row.tenant_id=root.tenant_id
             AND generation_row.rehearsal_run_id=root.rehearsal_run_id
             AND generation_row.root_id=root.root_id
           ORDER BY generation DESC LIMIT 1
      ) generation_row ON true
      JOIN LATERAL (
          SELECT * FROM public.rehearsal_delivery_operation_event event_row
           WHERE event_row.tenant_id=generation_row.tenant_id
             AND event_row.rehearsal_run_id=generation_row.rehearsal_run_id
             AND event_row.root_id=generation_row.root_id
             AND event_row.generation=generation_row.generation
           ORDER BY sequence DESC LIMIT 1
      ) latest ON true
      LEFT JOIN public.rehearsal_delivery_receipt receipt
        ON receipt.tenant_id=generation_row.tenant_id
       AND receipt.rehearsal_run_id=generation_row.rehearsal_run_id
       AND receipt.root_id=generation_row.root_id
       AND receipt.generation=generation_row.generation
     WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=w.rehearsal_run_id
       AND NOT EXISTS (
           SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted
            WHERE accepted.tenant_id=root.tenant_id
              AND accepted.rehearsal_run_id=root.rehearsal_run_id
              AND accepted.attempt_id=root.selected_attempt_id
       )
       AND latest.phase IN ('prepared','issueDispatched','completed')
     ORDER BY root.issue_cycle, root.created_at
     LIMIT 2;
    IF FOUND THEN
        IF (SELECT count(*) FROM (
            SELECT root.root_id
              FROM public.rehearsal_delivery_operation_root root
             WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=w.rehearsal_run_id
               AND NOT EXISTS (
                   SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted
                    WHERE accepted.tenant_id=root.tenant_id
                      AND accepted.rehearsal_run_id=root.rehearsal_run_id
                      AND accepted.attempt_id=root.selected_attempt_id
               )
               AND EXISTS (
                   SELECT 1
                     FROM public.rehearsal_delivery_operation_generation generation_row
                     JOIN LATERAL (
                         SELECT event_row.phase
                           FROM public.rehearsal_delivery_operation_event event_row
                          WHERE event_row.tenant_id=generation_row.tenant_id
                            AND event_row.rehearsal_run_id=generation_row.rehearsal_run_id
                            AND event_row.root_id=generation_row.root_id
                            AND event_row.generation=generation_row.generation
                          ORDER BY event_row.sequence DESC
                          LIMIT 1
                     ) latest ON true
                    WHERE generation_row.tenant_id=root.tenant_id
                      AND generation_row.rehearsal_run_id=root.rehearsal_run_id
                      AND generation_row.root_id=root.root_id
                      AND generation_row.generation=(
                          SELECT max(current_generation.generation)
                            FROM public.rehearsal_delivery_operation_generation current_generation
                           WHERE current_generation.tenant_id=root.tenant_id
                             AND current_generation.rehearsal_run_id=root.rehearsal_run_id
                             AND current_generation.root_id=root.root_id
                      )
                      AND latest.phase IN ('prepared','issueDispatched','completed')
               )
        ) unresolved) > 1 THEN
            RETURN;
        END IF;
        operation_id := open_row.operation_id;
        execution_descriptor := open_row.execution_descriptor;
        IF open_row.phase='completed' AND open_row.screen_projection IS NOT NULL THEN
            result_kind := 'replay'; screen_projection := open_row.screen_projection; screen_digest := open_row.screen_digest;
        ELSE
            result_kind := 'pending';
        END IF;
        RETURN NEXT;
        RETURN;
    END IF;
    SELECT * INTO header FROM public.rehearsal_frozen_material_set
     WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    -- Route verification is optional availability feedback. The atomic claim repeats
    -- the complete inventory proof before it can select even ordinal zero.
    IF header.expected_item_count <= 0 OR header.frozen_item_count <> header.expected_item_count
       OR (SELECT count(*) FROM public.rehearsal_frozen_source_snapshot snapshot_row
            WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=w.rehearsal_run_id)
          <> header.expected_item_count
       OR (SELECT min(snapshot_row.ordinal) FROM public.rehearsal_frozen_source_snapshot snapshot_row
            WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=w.rehearsal_run_id) <> 0
       OR (SELECT max(snapshot_row.ordinal) FROM public.rehearsal_frozen_source_snapshot snapshot_row
            WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=w.rehearsal_run_id)
          <> header.expected_item_count - 1
       OR EXISTS (
            SELECT 1 FROM public.rehearsal_frozen_source_snapshot snapshot_row
             LEFT JOIN public.rehearsal_frozen_item frozen_row
               ON frozen_row.tenant_id=snapshot_row.tenant_id
              AND frozen_row.rehearsal_run_id=snapshot_row.rehearsal_run_id
              AND frozen_row.attempt_id=snapshot_row.attempt_id
             LEFT JOIN public.rehearsal_frozen_private_execution private_row
               ON private_row.tenant_id=snapshot_row.tenant_id
              AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id
              AND private_row.attempt_id=snapshot_row.attempt_id
             WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=w.rehearsal_run_id
               AND (frozen_row.attempt_id IS NULL OR private_row.attempt_id IS NULL
                    OR frozen_row.problem_id<>snapshot_row.problem_id
                    OR frozen_row.version_id<>snapshot_row.version_id
                    OR frozen_row.canonical_content_digest<>snapshot_row.canonical_content_digest
                    OR private_row.issued_snapshot_sha256<>snapshot_row.issued_snapshot_sha256)
       ) THEN RETURN; END IF;
    SELECT * INTO source_row
      FROM public.rehearsal_frozen_source_snapshot snapshot_row
     WHERE snapshot_row.tenant_id=p_tenant
       AND snapshot_row.rehearsal_run_id=w.rehearsal_run_id
       AND NOT EXISTS (
           SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted
            WHERE accepted.tenant_id=snapshot_row.tenant_id
              AND accepted.rehearsal_run_id=snapshot_row.rehearsal_run_id
              AND accepted.attempt_id=snapshot_row.attempt_id
       )
     ORDER BY snapshot_row.ordinal
     LIMIT 1;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM public.rehearsal_frozen_private_execution private_row
         WHERE private_row.tenant_id=source_row.tenant_id
           AND private_row.rehearsal_run_id=source_row.rehearsal_run_id
           AND private_row.attempt_id=source_row.attempt_id
           AND private_row.issued_snapshot_sha256=source_row.issued_snapshot_sha256
    ) THEN RETURN; END IF;
    SELECT count(*) + 1 INTO cycle
      FROM public.rehearsal_delivery_operation_root
     WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id
       AND selected_attempt_id=source_row.attempt_id;
    descriptor := jsonb_build_object(
        'attemptId', source_row.attempt_id,
        'problemId', source_row.problem_id,
        'versionId', source_row.version_id,
        'responseDefinition', source_row.response_definition,
        'canonicalContentDigest', encode(source_row.canonical_content_digest, 'hex'),
        'deterministicSeed', source_row.deterministic_seed,
        'selectionAlgorithmVersion', source_row.selection_algorithm_version
    );
    INSERT INTO public.rehearsal_delivery_operation_root (
        tenant_id,rehearsal_run_id,root_id,idempotency_key,request_fingerprint,
        selected_attempt_id,issue_cycle
    ) VALUES (
        p_tenant,w.rehearsal_run_id,root_id,p_key,p_fingerprint,
        source_row.attempt_id,cycle
    );
    INSERT INTO public.rehearsal_delivery_operation_generation (
        tenant_id, rehearsal_run_id, root_id, generation, operation_id,
        selected_attempt_id, execution_descriptor, descriptor_digest, structural_binding
    ) VALUES (
        p_tenant, w.rehearsal_run_id, root_id, 1, operation, source_row.attempt_id,
        descriptor,
        digest(
            source_row.attempt_id::text::bytea || source_row.problem_id::text::bytea
            || source_row.version_id::text::bytea || source_row.canonical_content_digest
            || int8send(source_row.deterministic_seed)
            || int4send(source_row.selection_algorithm_version),
            'sha256'
        ),
        jsonb_build_object(
            'sourceSetDigest', encode(header.source_set_digest, 'hex'),
            'frozenInventoryDigest', encode(header.frozen_inventory_digest, 'hex'),
            'issuedSnapshotSha256', encode(source_row.issued_snapshot_sha256, 'hex'),
            'issueCycle', cycle
        )
    );
    INSERT INTO public.rehearsal_delivery_generation_material_binding (
        tenant_id,rehearsal_run_id,root_id,generation,operation_id,attempt_id,
        material_set_digest,issued_snapshot_sha256,private_execution_sha256
    )
    SELECT p_tenant,w.rehearsal_run_id,root_id,1,operation,source_row.attempt_id,
           header.frozen_inventory_digest,source_row.issued_snapshot_sha256,
           private_row.private_execution_sha256
      FROM public.rehearsal_frozen_private_execution private_row
    WHERE private_row.tenant_id=source_row.tenant_id
      AND private_row.rehearsal_run_id=source_row.rehearsal_run_id
      AND private_row.attempt_id=source_row.attempt_id;
    IF NOT FOUND THEN RETURN; END IF;
    INSERT INTO public.rehearsal_delivery_operation_event (
        tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase
    ) VALUES (p_tenant,w.rehearsal_run_id,root_id,1,operation,1,'prepared');
    result_kind := 'claimed'; operation_id := operation;
    execution_descriptor := descriptor; RETURN NEXT;
END $$; CREATE FUNCTION public.ple_rehearsal_delivery_material_commitments(
    p_tenant uuid, p_actor uuid, p_course uuid, p_assignment_reference integer,
    p_revision bigint, p_rehearsal_reference bigint, p_attempt uuid
) RETURNS TABLE(
    source_set_digest bytea, frozen_inventory_digest bytea,
    issued_snapshot_sha256 bytea, private_execution_sha256 bytea
) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE w record;
BEGIN
    SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(
        p_tenant, p_actor, p_course, p_assignment_reference, p_revision,
        p_rehearsal_reference
    );
    IF NOT FOUND THEN RETURN; END IF;
    RETURN QUERY
    SELECT material.source_set_digest, material.frozen_inventory_digest,
           snapshot.issued_snapshot_sha256, private_row.private_execution_sha256
      FROM public.rehearsal_frozen_material_set material
      JOIN public.rehearsal_frozen_source_snapshot snapshot
        ON snapshot.tenant_id = material.tenant_id
       AND snapshot.rehearsal_run_id = material.rehearsal_run_id
      JOIN public.rehearsal_frozen_private_execution private_row
        ON private_row.tenant_id = snapshot.tenant_id
       AND private_row.rehearsal_run_id = snapshot.rehearsal_run_id
       AND private_row.attempt_id = snapshot.attempt_id
     WHERE material.tenant_id = p_tenant
       AND material.rehearsal_run_id = w.rehearsal_run_id
       AND snapshot.attempt_id = p_attempt;
END $$;
-- Completion indexes accepted evidence atomically and terminalizes only after every frozen ordinal is accepted.
CREATE FUNCTION public.ple_rehearsal_index_accepted_attempt()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog, public, pg_temp AS $$
DECLARE
    root public.rehearsal_submission_claim_root%ROWTYPE;
    run_row public.rehearsal_run%ROWTYPE;
    completed_count integer;
    expected_count integer;
BEGIN
    IF NEW.phase <> 'completed' THEN
        RETURN NEW;
    END IF;
    SELECT * INTO root
      FROM public.rehearsal_submission_claim_root
     WHERE tenant_id=NEW.tenant_id
       AND rehearsal_run_id=NEW.rehearsal_run_id
       AND claim_id=NEW.claim_id;
    IF NOT FOUND OR NEW.accepted_evidence_sequence IS NULL
       OR NEW.accepted_evidence_digest IS NULL THEN
        RAISE EXCEPTION 'completed rehearsal claim has no accepted evidence'
            USING ERRCODE='23514';
    END IF;
    INSERT INTO public.rehearsal_accepted_attempt_integrity(
        tenant_id,rehearsal_run_id,attempt_id,claim_id,evidence_sequence,evidence_digest
    ) VALUES (
        NEW.tenant_id,NEW.rehearsal_run_id,root.attempt_id,NEW.claim_id,
        NEW.accepted_evidence_sequence,NEW.accepted_evidence_digest
    );
    SELECT * INTO run_row FROM public.rehearsal_run
     WHERE tenant_id=NEW.tenant_id AND rehearsal_run_id=NEW.rehearsal_run_id;
    SELECT count(*) INTO completed_count
      FROM public.rehearsal_accepted_attempt_integrity
     WHERE tenant_id=NEW.tenant_id AND rehearsal_run_id=NEW.rehearsal_run_id;
    SELECT expected_item_count INTO expected_count
      FROM public.rehearsal_frozen_material_set
     WHERE tenant_id=NEW.tenant_id AND rehearsal_run_id=NEW.rehearsal_run_id;
    IF run_row.lifecycle='active' AND completed_count=expected_count THEN
        IF EXISTS (
            SELECT 1
              FROM public.rehearsal_frozen_source_snapshot source_row
             WHERE source_row.tenant_id=NEW.tenant_id
               AND source_row.rehearsal_run_id=NEW.rehearsal_run_id
               AND NOT EXISTS (
                    SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted
                     WHERE accepted.tenant_id=source_row.tenant_id
                       AND accepted.rehearsal_run_id=source_row.rehearsal_run_id
                       AND accepted.attempt_id=source_row.attempt_id
               )
        ) THEN
            RAISE EXCEPTION 'accepted rehearsal index is incomplete' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $$; CREATE TRIGGER rehearsal_claim_completion_indexes_attempt
AFTER INSERT ON public.rehearsal_submission_claim_event
FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_index_accepted_attempt(); CREATE OR REPLACE FUNCTION public.ple_prepare_sealed_rehearsal_delivery_execution(p_tenant uuid,p_operation uuid) RETURNS TABLE(issued_snapshot_bytes bytea,issued_snapshot_sha256 bytea,private_execution_bytes bytea,private_execution_sha256 bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN RETURN QUERY SELECT s.issued_snapshot_bytes,s.issued_snapshot_sha256,x.private_execution_bytes,x.private_execution_sha256 FROM public.rehearsal_delivery_generation_material_binding b JOIN public.rehearsal_frozen_source_snapshot s ON(s.tenant_id=b.tenant_id AND s.rehearsal_run_id=b.rehearsal_run_id AND s.attempt_id=b.attempt_id) JOIN public.rehearsal_frozen_private_execution x ON(x.tenant_id=s.tenant_id AND x.rehearsal_run_id=s.rehearsal_run_id AND x.attempt_id=s.attempt_id) JOIN public.rehearsal_run run_row ON(run_row.tenant_id=b.tenant_id AND run_row.rehearsal_run_id=b.rehearsal_run_id) WHERE b.tenant_id=p_tenant AND b.operation_id=p_operation AND run_row.lifecycle='active' AND (SELECT e.phase FROM public.rehearsal_delivery_operation_event e WHERE e.tenant_id=b.tenant_id AND e.rehearsal_run_id=b.rehearsal_run_id AND e.root_id=b.root_id AND e.generation=b.generation AND e.operation_id=p_operation ORDER BY e.sequence DESC LIMIT 1)='issueDispatched';END $$; ALTER FUNCTION public.ple_rehearsal_material_append_only() OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_copy_rehearsal_generation_material_binding() OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_finalize_rehearsal_start_freeze(uuid,uuid,uuid,bytea,bytea,integer,uuid[],uuid[],uuid[],uuid[],jsonb[],bytea[],bytea[],bigint[],integer[],bytea[],bytea[],bytea[],bytea[],text[],integer[],integer[],integer,bytea,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_verify_rehearsal_frozen_material_set(uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_verify_rehearsal_delivery_material_from_route(uuid,uuid,uuid,integer,bigint,bigint) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_sealed_rehearsal_delivery_execution(uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_claim_prepared_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea,uuid,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_delivery_material_commitments(uuid,uuid,uuid,integer,bigint,bigint,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_rehearsal_start_sources(uuid,uuid,uuid,integer,bigint,uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_rehearsal_flat_grading_material(uuid,uuid,uuid,integer,bigint,uuid,uuid,uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_index_accepted_attempt() OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_verify_rehearsal_frozen_material_set(uuid,uuid),public.ple_finalize_rehearsal_start_freeze(uuid,uuid,uuid,bytea,bytea,integer,uuid[],uuid[],uuid[],uuid[],jsonb[],bytea[],bytea[],bigint[],integer[],bytea[],bytea[],bytea[],bytea[],text[],integer[],integer[],integer,bytea,bytea),public.ple_verify_rehearsal_delivery_material_from_route(uuid,uuid,uuid,integer,bigint,bigint),public.ple_prepare_sealed_rehearsal_delivery_execution(uuid,uuid),public.ple_claim_prepared_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea,uuid,bytea),public.ple_rehearsal_delivery_material_commitments(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_prepare_rehearsal_start_sources(uuid,uuid,uuid,integer,bigint,uuid,uuid),public.ple_prepare_rehearsal_flat_grading_material(uuid,uuid,uuid,integer,bigint,uuid,uuid,uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_verify_rehearsal_frozen_material_set(uuid,uuid) TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_finalize_rehearsal_start_freeze(uuid,uuid,uuid,bytea,bytea,integer,uuid[],uuid[],uuid[],uuid[],jsonb[],bytea[],bytea[],bigint[],integer[],bytea[],bytea[],bytea[],bytea[],text[],integer[],integer[],integer,bytea,bytea),public.ple_verify_rehearsal_delivery_material_from_route(uuid,uuid,uuid,integer,bigint,bigint),public.ple_claim_prepared_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea,uuid,bytea),public.ple_rehearsal_delivery_material_commitments(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_prepare_rehearsal_start_sources(uuid,uuid,uuid,integer,bigint,uuid,uuid),public.ple_prepare_rehearsal_flat_grading_material(uuid,uuid,uuid,integer,bigint,uuid,uuid,uuid,uuid) TO ple_app; GRANT EXECUTE ON FUNCTION public.ple_prepare_sealed_rehearsal_delivery_execution(uuid,uuid) TO ple_grading_reader;
-- Route submission uses the serialized route, immutable journals, append-only claims, and narrow evidence/lifecycle updates.
ALTER TABLE public.rehearsal_submission_claim_root RENAME COLUMN sealed_request TO submission_input; CREATE FUNCTION public.ple_validate_rehearsal_rendered_submission_v1(p_screen jsonb,p_digest bytea,p_response jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE schema jsonb:=p_screen#>'{presentation,response}';kind text;selected jsonb;allowed text[];n integer;reuse boolean;point jsonb;
BEGIN
 IF jsonb_typeof(p_screen)<>'object' OR octet_length(p_digest)<>32 OR jsonb_typeof(schema)<>'object' OR jsonb_typeof(p_response)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_response)>393216 THEN RETURN false; END IF;
 kind:=schema->>'kind';
 IF kind IN ('singleChoice','multipleAnswer') AND p_response->>'kind'='multipleChoice' THEN
  selected:=p_response->'selected'; SELECT array_agg(value) INTO allowed FROM jsonb_array_elements_text(schema->'choices') choice CROSS JOIN LATERAL (SELECT choice#>>'{id}') v(value);
  n:=jsonb_array_length(selected); RETURN jsonb_typeof(selected)='array' AND n BETWEEN CASE WHEN kind='singleChoice' THEN 1 ELSE (schema->>'minimum')::integer END AND CASE WHEN kind='singleChoice' THEN 1 ELSE (schema->>'maximum')::integer END AND (SELECT count(*)=count(DISTINCT value) AND bool_and(value=ANY(allowed)) FROM jsonb_array_elements_text(selected) value);
 ELSIF kind='fillIn' AND p_response->>'kind'='shortText' THEN RETURN jsonb_typeof(p_response->'text')='string' AND length(p_response->>'text')<=(schema->>'maxCharacters')::integer AND p_response->>'text' !~ '[[:cntrl:]]';
 ELSIF kind='numerical' AND p_response->>'kind'='numeric' THEN RETURN jsonb_typeof(p_response->'value')='number' AND isfinite((p_response->>'value')::double precision) AND length(p_response->>'value')<=(schema->>'maxCharacters')::integer;
 ELSIF kind='multiFillIn' AND p_response->>'kind'='multiBlank' THEN RETURN jsonb_typeof(p_response->'answers')='array' AND jsonb_array_length(p_response->'answers')=jsonb_array_length(schema->'blanks') AND (SELECT count(*)=count(DISTINCT answer->>'slot') AND bool_and(answer->>'text' !~ '[[:cntrl:]]' AND length(answer->>'text')<=(blank->>'maxCharacters')::integer) FROM jsonb_array_elements(p_response->'answers') answer JOIN LATERAL jsonb_array_elements(schema->'blanks') blank ON blank->>'id'=answer->>'slot');
 ELSIF kind='matching' AND p_response->>'kind'='matching' THEN reuse:=COALESCE((schema->>'reuseChoices')::boolean,false); RETURN jsonb_typeof(p_response->'matches')='array' AND jsonb_array_length(p_response->'matches')=jsonb_array_length(schema->'prompts') AND (SELECT count(*)=count(DISTINCT pair->>'prompt') AND (reuse OR count(*)=count(DISTINCT pair->>'choice')) AND bool_and(pair->>'prompt' IN (SELECT x->>'id' FROM jsonb_array_elements(schema->'prompts') x) AND pair->>'choice' IN (SELECT x->>'id' FROM jsonb_array_elements(schema->'choices') x)) FROM jsonb_array_elements(p_response->'matches') pair);
 ELSIF kind='ordering' AND p_response->>'kind'='ordering' THEN RETURN jsonb_typeof(p_response->'order')='array' AND jsonb_array_length(p_response->'order')=jsonb_array_length(schema->'items') AND (SELECT count(*)=count(DISTINCT value) AND bool_and(value IN (SELECT x->>'id' FROM jsonb_array_elements(schema->'items') x)) FROM jsonb_array_elements_text(p_response->'order') value);
 ELSIF kind='hotspot' AND p_response->>'kind'='hotspot' THEN RETURN jsonb_typeof(p_response->'points')='array' AND jsonb_array_length(p_response->'points') BETWEEN (schema->>'minimum')::integer AND (schema->>'maximum')::integer AND (SELECT count(*)=count(DISTINCT (point->>'x',point->>'y')) AND bool_and(jsonb_typeof(point->'x')='number' AND jsonb_typeof(point->'y')='number' AND isfinite((point->>'x')::double precision) AND isfinite((point->>'y')::double precision) AND (point->>'x')::double precision BETWEEN 0 AND 10000 AND (point->>'y')::double precision BETWEEN 0 AND 10000 AND EXISTS(SELECT 1 FROM jsonb_array_elements(schema#>'{surface,regions}') region WHERE (point->>'x')::double precision BETWEEN (region->>'x')::double precision AND (region->>'x')::double precision+(region->>'width')::double precision AND (point->>'y')::double precision BETWEEN (region->>'y')::double precision AND (region->>'y')::double precision+(region->>'height')::double precision)) FROM jsonb_array_elements(p_response->'points') point);
 END IF; RETURN false;
END $$; ALTER FUNCTION public.ple_validate_rehearsal_rendered_submission_v1(jsonb,bytea,jsonb) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_validate_rehearsal_rendered_submission_v1(jsonb,bytea,jsonb) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_validate_rehearsal_rendered_submission_v1(jsonb,bytea,jsonb) TO ple_app; CREATE TABLE public.rehearsal_submission_claim_delivery_binding (
    tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,claim_id uuid NOT NULL,delivery_root_id uuid NOT NULL,delivery_generation integer NOT NULL,delivery_operation_id uuid NOT NULL,issued_screen_digest bytea NOT NULL,
    PRIMARY KEY (tenant_id,rehearsal_run_id,claim_id),
    FOREIGN KEY (tenant_id,rehearsal_run_id,claim_id) REFERENCES public.rehearsal_submission_claim_root(tenant_id,rehearsal_run_id,claim_id) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id,rehearsal_run_id,delivery_root_id,delivery_generation) REFERENCES public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,root_id,generation) ON DELETE RESTRICT,
    FOREIGN KEY (tenant_id,rehearsal_run_id,delivery_operation_id) REFERENCES public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,operation_id) ON DELETE RESTRICT,
    CONSTRAINT rehearsal_claim_delivery_digest_check CHECK (octet_length(issued_screen_digest)=32)
); CREATE TRIGGER rehearsal_claim_delivery_binding_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_submission_claim_delivery_binding FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); ALTER TABLE public.rehearsal_submission_claim_delivery_binding ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_submission_claim_delivery_binding FORCE ROW LEVEL SECURITY; CREATE POLICY rehearsal_claim_delivery_binding_source ON public.rehearsal_submission_claim_delivery_binding TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_delivery_binding_broker ON public.rehearsal_submission_claim_delivery_binding FOR SELECT TO ple_rehearsal_broker USING(tenant_id=public.ple_current_tenant()); GRANT SELECT,INSERT ON public.rehearsal_submission_claim_delivery_binding TO ple_rehearsal_source; GRANT SELECT ON public.rehearsal_submission_claim_delivery_binding TO ple_rehearsal_broker; REVOKE ALL ON public.rehearsal_submission_claim_delivery_binding FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; CREATE FUNCTION public.ple_rehearsal_route_create_claim(
    p_tenant uuid,p_actor uuid,p_course uuid,p_assignment uuid,p_revision bigint,p_run uuid,
    p_claim uuid,p_operation uuid,p_key text,p_presentation_digest bytea,p_fingerprint bytea,p_request jsonb
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE issued_count integer; issued_attempt uuid; issued_root uuid; issued_generation bigint; issued_operation uuid; w record;
BEGIN
    SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(
        p_tenant,p_actor,p_course,(SELECT public_id FROM public.assignment
        WHERE tenant_id=p_tenant AND course_id=p_course AND assignment_id=p_assignment),p_revision,
        (SELECT rehearsal_reference FROM public.rehearsal_run
        WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run)
    );
    IF NOT FOUND OR w.rehearsal_run_id IS DISTINCT FROM p_run
       OR p_claim IS NULL OR p_operation IS NULL
       OR octet_length(p_presentation_digest) <> 32 OR octet_length(p_fingerprint) <> 32 OR jsonb_typeof(p_request) <> 'object'
       OR public.ple_rehearsal_jsonb_bytes(p_request) > 393728 THEN RETURN false; END IF;
    IF NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,p_run) THEN RETURN false; END IF;
    SELECT count(*), (array_agg(root.selected_attempt_id))[1],
           (array_agg(root.root_id))[1], (array_agg(generation_row.generation))[1],
           (array_agg(generation_row.operation_id))[1]
      INTO issued_count, issued_attempt, issued_root, issued_generation, issued_operation
      FROM public.rehearsal_delivery_operation_root root
      JOIN LATERAL (
          SELECT * FROM public.rehearsal_delivery_operation_generation generation_row
           WHERE generation_row.tenant_id=root.tenant_id
             AND generation_row.rehearsal_run_id=root.rehearsal_run_id
             AND generation_row.root_id=root.root_id
           ORDER BY generation_row.generation DESC LIMIT 1
      ) generation_row ON true
      JOIN LATERAL (
          SELECT * FROM public.rehearsal_delivery_operation_event event_row
           WHERE event_row.tenant_id=generation_row.tenant_id
             AND event_row.rehearsal_run_id=generation_row.rehearsal_run_id
             AND event_row.root_id=generation_row.root_id
             AND event_row.generation=generation_row.generation
           ORDER BY event_row.sequence DESC LIMIT 1
      ) latest ON true
      JOIN public.rehearsal_delivery_receipt receipt
        ON receipt.tenant_id=generation_row.tenant_id
       AND receipt.rehearsal_run_id=generation_row.rehearsal_run_id
       AND receipt.root_id=generation_row.root_id AND receipt.generation=generation_row.generation
       AND receipt.operation_id=generation_row.operation_id
     WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=p_run
       AND latest.phase='completed' AND latest.completion_kind='issued'
       AND receipt.result_kind='issued' AND receipt.frozen_attempt_id=root.selected_attempt_id
       AND NOT EXISTS (
           SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted
            WHERE accepted.tenant_id=root.tenant_id
              AND accepted.rehearsal_run_id=root.rehearsal_run_id
              AND accepted.attempt_id=root.selected_attempt_id
       );
    IF issued_count <> 1
       OR NOT EXISTS (
           SELECT 1 FROM public.rehearsal_delivery_receipt issued
            JOIN public.rehearsal_delivery_operation_root root
             ON root.tenant_id=issued.tenant_id AND root.rehearsal_run_id=issued.rehearsal_run_id
             AND root.root_id=issued.root_id AND root.selected_attempt_id=issued_attempt
           WHERE issued.tenant_id=p_tenant AND issued.rehearsal_run_id=p_run
             AND issued.result_kind='issued' AND issued.frozen_attempt_id=issued_attempt
             AND issued.screen_digest=p_presentation_digest
       ) THEN RETURN false; END IF;
    INSERT INTO public.rehearsal_submission_claim_root
      (tenant_id,rehearsal_run_id,claim_id,idempotency_key,attempt_id,request_fingerprint,submission_input)
    VALUES (p_tenant,p_run,p_claim,p_key,issued_attempt,p_fingerprint,p_request);
    INSERT INTO public.rehearsal_submission_claim_delivery_binding
      (tenant_id,rehearsal_run_id,claim_id,delivery_root_id,delivery_generation,delivery_operation_id,issued_screen_digest)
    VALUES (p_tenant,p_run,p_claim,issued_root,issued_generation,issued_operation,p_presentation_digest);
    INSERT INTO public.rehearsal_submission_claim_event
      (tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase)
    VALUES (p_tenant,p_run,p_claim,1,p_operation,1,'prepared');
    RETURN true;
EXCEPTION WHEN unique_violation THEN RETURN false;
END $$; CREATE FUNCTION public.ple_rehearsal_route_append_claim_event(
    p_tenant uuid,p_actor uuid,p_course uuid,p_assignment uuid,p_revision bigint,p_run uuid,
    p_claim uuid,p_operation uuid,p_phase text,p_reason text DEFAULT NULL
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog,public,pg_temp AS $$
#variable_conflict use_column
DECLARE latest record; w record; next_generation bigint;
BEGIN
    SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(
        p_tenant,p_actor,p_course,(SELECT public_id FROM public.assignment WHERE tenant_id=p_tenant AND course_id=p_course AND assignment_id=p_assignment),p_revision,
        (SELECT rehearsal_reference FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run));
    IF NOT FOUND OR w.rehearsal_run_id IS DISTINCT FROM p_run THEN RETURN false; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.rehearsal_submission_claim_root claim
         JOIN public.rehearsal_delivery_operation_root root
           ON root.tenant_id=claim.tenant_id AND root.rehearsal_run_id=claim.rehearsal_run_id
          AND root.selected_attempt_id=claim.attempt_id
         JOIN public.rehearsal_submission_claim_delivery_binding binding
           ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id
          AND binding.claim_id=claim.claim_id AND binding.delivery_root_id=root.root_id
         JOIN LATERAL (
             SELECT * FROM public.rehearsal_delivery_operation_generation generation_row
              WHERE generation_row.tenant_id=root.tenant_id
                AND generation_row.rehearsal_run_id=root.rehearsal_run_id
                AND generation_row.root_id=root.root_id
                AND generation_row.generation=binding.delivery_generation
                AND generation_row.operation_id=binding.delivery_operation_id
         ) generation_row ON true
         JOIN LATERAL (
             SELECT * FROM public.rehearsal_delivery_operation_event event_row
              WHERE event_row.tenant_id=generation_row.tenant_id
                AND event_row.rehearsal_run_id=generation_row.rehearsal_run_id
                AND event_row.root_id=generation_row.root_id
                AND event_row.generation=generation_row.generation
              ORDER BY event_row.sequence DESC LIMIT 1
         ) latest ON true
         JOIN public.rehearsal_delivery_receipt receipt
           ON receipt.tenant_id=generation_row.tenant_id
          AND receipt.rehearsal_run_id=generation_row.rehearsal_run_id
          AND receipt.root_id=generation_row.root_id AND receipt.generation=generation_row.generation
          AND receipt.operation_id=generation_row.operation_id
        WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=p_run AND claim.claim_id=p_claim
          AND latest.phase='completed' AND latest.completion_kind='issued'
          AND receipt.result_kind='issued' AND receipt.frozen_attempt_id=claim.attempt_id
          AND receipt.screen_digest=binding.issued_screen_digest
    ) THEN RETURN false; END IF;
    SELECT sequence,operation_id,generation,phase INTO latest
      FROM public.rehearsal_submission_claim_event
     WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND claim_id=p_claim
     ORDER BY sequence DESC LIMIT 1;
    IF NOT FOUND THEN RETURN false; END IF;
    IF p_phase='gradingDispatched' AND latest.phase='prepared' AND p_operation=latest.operation_id AND p_reason IS NULL THEN
      next_generation:=latest.generation;
    ELSIF p_phase='abandonedBeforeDispatch' AND latest.phase='prepared' AND p_operation=latest.operation_id
       AND p_reason IN ('localPreparationFailed','nativeBackendAdmissionRejected','trustedRendererAdmissionRejected') THEN next_generation:=latest.generation;
    ELSIF p_phase='prepared' AND latest.phase='abandonedBeforeDispatch' AND p_reason IS NULL
       AND latest.generation < 4294967295 AND NOT EXISTS (SELECT 1 FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND claim_id=p_claim AND operation_id=p_operation) THEN next_generation:=latest.generation+1;
    ELSE RETURN false; END IF;
    INSERT INTO public.rehearsal_submission_claim_event(tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase,abandonment_reason)
    VALUES(p_tenant,p_run,p_claim,latest.sequence+1,p_operation,next_generation,p_phase,p_reason);
    RETURN true;
END $$; CREATE FUNCTION public.ple_rehearsal_route_complete_claim(
    p_tenant uuid,p_actor uuid,p_course uuid,p_assignment uuid,p_revision bigint,p_run uuid,
    p_claim uuid,p_operation uuid,p_old_digest bytea,p_old_length bigint,p_entry_digest bytea,
    p_payload jsonb,p_payload_digest bytea,p_recorded_at bigint,p_receipt jsonb,p_receipt_digest bytea
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog,public,pg_temp AS $$
#variable_conflict use_column
DECLARE latest record; w record; expected_count integer; completed_count integer;
BEGIN
    SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(
        p_tenant,p_actor,p_course,(SELECT public_id FROM public.assignment WHERE tenant_id=p_tenant AND course_id=p_course AND assignment_id=p_assignment),p_revision,
        (SELECT rehearsal_reference FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run));
    IF NOT FOUND OR w.rehearsal_run_id IS DISTINCT FROM p_run
       OR p_recorded_at<>public.ple_rehearsal_now_millis() OR jsonb_typeof(p_receipt)<>'object'
       OR public.ple_rehearsal_jsonb_bytes(p_receipt)>394240 OR octet_length(p_receipt_digest)<>32
       OR p_old_length NOT BETWEEN 0 AND 4294967295 OR octet_length(p_old_digest)<>32
       OR octet_length(p_entry_digest)<>32 OR octet_length(p_payload_digest)<>32 THEN RETURN false; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.rehearsal_submission_claim_root claim
         JOIN public.rehearsal_delivery_operation_root root
           ON root.tenant_id=claim.tenant_id AND root.rehearsal_run_id=claim.rehearsal_run_id
          AND root.selected_attempt_id=claim.attempt_id
         JOIN public.rehearsal_submission_claim_delivery_binding binding
           ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id
          AND binding.claim_id=claim.claim_id AND binding.delivery_root_id=root.root_id
         JOIN LATERAL (
             SELECT * FROM public.rehearsal_delivery_operation_generation generation_row
              WHERE generation_row.tenant_id=root.tenant_id
                AND generation_row.rehearsal_run_id=root.rehearsal_run_id
                AND generation_row.root_id=root.root_id
                AND generation_row.generation=binding.delivery_generation
                AND generation_row.operation_id=binding.delivery_operation_id
         ) generation_row ON true
         JOIN LATERAL (
             SELECT * FROM public.rehearsal_delivery_operation_event event_row
              WHERE event_row.tenant_id=generation_row.tenant_id
                AND event_row.rehearsal_run_id=generation_row.rehearsal_run_id
                AND event_row.root_id=generation_row.root_id
                AND event_row.generation=generation_row.generation
              ORDER BY event_row.sequence DESC LIMIT 1
         ) latest ON true
         JOIN public.rehearsal_delivery_receipt receipt
           ON receipt.tenant_id=generation_row.tenant_id
          AND receipt.rehearsal_run_id=generation_row.rehearsal_run_id
          AND receipt.root_id=generation_row.root_id AND receipt.generation=generation_row.generation
          AND receipt.operation_id=generation_row.operation_id
        WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=p_run AND claim.claim_id=p_claim
          AND latest.phase='completed' AND latest.completion_kind='issued'
          AND receipt.result_kind='issued' AND receipt.frozen_attempt_id=claim.attempt_id
          AND receipt.screen_digest=binding.issued_screen_digest
    ) THEN RETURN false; END IF;
    SELECT sequence,operation_id,generation,phase INTO latest FROM public.rehearsal_submission_claim_event
     WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND claim_id=p_claim ORDER BY sequence DESC LIMIT 1;
    IF NOT FOUND OR latest.phase<>'gradingDispatched' OR latest.operation_id<>p_operation THEN RETURN false; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run
      AND lifecycle='active' AND evidence_head_digest=p_old_digest AND evidence_length=p_old_length) THEN RETURN false; END IF;
    INSERT INTO public.rehearsal_evidence(tenant_id,rehearsal_run_id,sequence,kind,previous_digest,entry_digest,payload,payload_digest,recorded_at)
      VALUES(p_tenant,p_run,p_old_length+1,'acceptedSubmission',p_old_digest,p_entry_digest,p_payload,p_payload_digest,public.ple_rehearsal_timestamp_from_millis(p_recorded_at));
    UPDATE public.rehearsal_run SET evidence_head_digest=p_entry_digest,evidence_length=p_old_length+1,updated_at=public.ple_rehearsal_now()
      WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND evidence_head_digest=p_old_digest AND evidence_length=p_old_length;
    IF NOT FOUND THEN RAISE EXCEPTION 'rehearsal evidence head compare-and-swap failed' USING ERRCODE = '55000'; END IF;
    INSERT INTO public.rehearsal_submission_receipt(tenant_id,rehearsal_run_id,claim_id,outcome_projection,receipt_digest)
      VALUES(p_tenant,p_run,p_claim,p_receipt,p_receipt_digest);
    INSERT INTO public.rehearsal_submission_claim_event(tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase,accepted_evidence_sequence,accepted_evidence_digest,receipt_digest)
      VALUES(p_tenant,p_run,p_claim,latest.sequence+1,p_operation,latest.generation,'completed',p_old_length+1,p_entry_digest,p_receipt_digest);
    SELECT expected_item_count INTO expected_count FROM public.rehearsal_frozen_material_set WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;
    SELECT count(*) INTO completed_count FROM public.rehearsal_accepted_attempt_integrity WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;
    IF completed_count=expected_count AND NOT EXISTS (SELECT 1 FROM public.rehearsal_frozen_source_snapshot s WHERE s.tenant_id=p_tenant AND s.rehearsal_run_id=p_run AND NOT EXISTS (SELECT 1 FROM public.rehearsal_accepted_attempt_integrity a WHERE a.tenant_id=s.tenant_id AND a.rehearsal_run_id=s.rehearsal_run_id AND a.attempt_id=s.attempt_id)) THEN
      UPDATE public.rehearsal_run SET lifecycle='completed',terminal_at=public.ple_rehearsal_now(),updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active';
    END IF;
    RETURN true;
END $$; ALTER FUNCTION public.ple_rehearsal_route_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,bytea,bytea,jsonb) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_route_append_claim_event(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,text) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_route_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) OWNER TO ple_rehearsal_broker;
-- Route preparation is an in-transaction validation witness, not selection authority: create-claim independently re-derives the same delivery tuple (ASVS 2.2.1, 2.3.1, 2.3.3, 15.3.1, 15.4.2).
CREATE FUNCTION public.ple_prepare_rehearsal_route_submission(
    p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_presentation_digest bytea,p_key text,p_response jsonb
) RETURNS TABLE(decision text,attempt_id uuid,outcome_projection jsonb,receipt_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
DECLARE w record; result uuid; count_issued integer; existing record; latest record; completed_receipt record;
BEGIN
 SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);
 IF NOT FOUND OR octet_length(p_presentation_digest)<>32 OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' OR jsonb_typeof(p_response)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_response)>393216 THEN RETURN; END IF;
 SELECT claim.claim_id,claim.submission_input,binding.issued_screen_digest INTO existing FROM public.rehearsal_submission_claim_root claim LEFT JOIN public.rehearsal_submission_claim_delivery_binding binding ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id AND binding.claim_id=claim.claim_id WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=w.rehearsal_run_id AND claim.idempotency_key=p_key;
 IF FOUND THEN
  IF existing.issued_screen_digest IS DISTINCT FROM p_presentation_digest OR existing.submission_input#>'{kind,response}' IS DISTINCT FROM p_response THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea; RETURN; END IF;
  SELECT * INTO latest FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id AND claim_id=existing.claim_id ORDER BY sequence DESC LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  IF latest.phase='completed' THEN SELECT receipt.outcome_projection,receipt.receipt_digest INTO completed_receipt FROM public.rehearsal_submission_receipt receipt WHERE receipt.tenant_id=p_tenant AND receipt.rehearsal_run_id=w.rehearsal_run_id AND receipt.claim_id=existing.claim_id AND receipt.receipt_digest=latest.receipt_digest; IF NOT FOUND THEN RETURN QUERY SELECT 'invalid'::text,NULL::uuid,NULL::jsonb,NULL::bytea; ELSE RETURN QUERY SELECT 'replay'::text,NULL::uuid,completed_receipt.outcome_projection,completed_receipt.receipt_digest; END IF; RETURN; END IF;
  IF latest.phase IN ('prepared','gradingDispatched') THEN RETURN QUERY SELECT 'pending'::text,NULL::uuid,NULL::jsonb,NULL::bytea; RETURN; END IF;
  RETURN QUERY SELECT 'reclaim'::text,(SELECT claim.attempt_id FROM public.rehearsal_submission_claim_root claim WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=w.rehearsal_run_id AND claim.claim_id=existing.claim_id),NULL::jsonb,NULL::bytea; RETURN;
 END IF;
 SELECT count(*), (array_agg(root.selected_attempt_id))[1] INTO count_issued,result
 FROM public.rehearsal_delivery_operation_root root
 JOIN LATERAL (SELECT * FROM public.rehearsal_delivery_operation_generation g WHERE g.tenant_id=root.tenant_id AND g.rehearsal_run_id=root.rehearsal_run_id AND g.root_id=root.root_id ORDER BY g.generation DESC LIMIT 1) g ON true
 JOIN LATERAL (SELECT * FROM public.rehearsal_delivery_operation_event e WHERE e.tenant_id=g.tenant_id AND e.rehearsal_run_id=g.rehearsal_run_id AND e.root_id=g.root_id AND e.generation=g.generation ORDER BY e.sequence DESC LIMIT 1) e ON true
 JOIN public.rehearsal_delivery_receipt r ON r.tenant_id=g.tenant_id AND r.rehearsal_run_id=g.rehearsal_run_id AND r.root_id=g.root_id AND r.generation=g.generation AND r.operation_id=g.operation_id
 WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=w.rehearsal_run_id AND e.phase='completed' AND e.completion_kind='issued' AND r.result_kind='issued' AND r.frozen_attempt_id=root.selected_attempt_id AND r.screen_digest=p_presentation_digest
 AND NOT EXISTS (SELECT 1 FROM public.rehearsal_accepted_attempt_integrity a WHERE a.tenant_id=root.tenant_id AND a.rehearsal_run_id=root.rehearsal_run_id AND a.attempt_id=root.selected_attempt_id);
 IF count_issued=1 THEN RETURN QUERY SELECT 'new'::text,result,NULL::jsonb,NULL::bytea; END IF;
END $$; ALTER FUNCTION public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,bytea,text,jsonb) OWNER TO ple_rehearsal_source; CREATE FUNCTION public.ple_rehearsal_route_append_frozen_item(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment uuid,p_revision bigint,p_run uuid,p_old_digest bytea,p_old_length bigint,p_entry_digest bytea,p_payload jsonb,p_payload_digest bytea,p_recorded_at bigint,p_attempt uuid,p_problem uuid,p_version uuid,p_response jsonb,p_response_digest bytea,p_content_digest bytea,p_frozen_at bigint,p_start_operation uuid,p_start_nonce uuid,p_ordinal integer) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.rehearsal_start_operation_root root JOIN public.rehearsal_start_freeze_source_binding binding ON binding.tenant_id=root.tenant_id AND binding.operation_id=root.operation_id WHERE root.tenant_id=p_tenant AND root.operation_id=p_start_operation AND root.prepare_nonce=p_start_nonce AND root.prepared_txid=txid_current() AND root.resulting_run_id=p_run AND binding.ordinal=p_ordinal AND binding.problem_id=p_problem AND binding.version_id=p_version) AND public.ple_rehearsal_append_frozen_item(p_tenant,p_actor,p_course,p_assignment,p_revision,p_run,p_old_digest,p_old_length,p_entry_digest,p_payload,p_payload_digest,p_recorded_at,p_attempt,p_problem,p_version,p_response,p_response_digest,p_content_digest,p_frozen_at) $$; ALTER FUNCTION public.ple_rehearsal_route_append_frozen_item(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,uuid,uuid,uuid,jsonb,bytea,bytea,bigint,uuid,uuid,integer) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_rehearsal_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,uuid,bytea,jsonb),public.ple_rehearsal_append_claim_event(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,text),public.ple_rehearsal_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea),public.ple_rehearsal_terminalize(uuid,uuid,uuid,uuid,bigint,uuid,text) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; REVOKE ALL ON FUNCTION public.ple_rehearsal_start(uuid,uuid,uuid,uuid,integer,bigint,jsonb,bytea,bytea,uuid,boolean,uuid),public.ple_rehearsal_append_frozen_item(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,uuid,uuid,uuid,jsonb,bytea,bytea,bigint) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_start(uuid,uuid,uuid,uuid,integer,bigint,jsonb,bytea,bytea,uuid,boolean,uuid) TO ple_rehearsal_broker; GRANT SELECT ON public.rehearsal_run,public.rehearsal_submission_claim_root,public.rehearsal_submission_claim_delivery_binding,public.rehearsal_submission_claim_event,public.rehearsal_submission_receipt,public.rehearsal_delivery_operation_root,public.rehearsal_delivery_operation_generation,public.rehearsal_delivery_operation_event,public.rehearsal_delivery_receipt,public.rehearsal_frozen_material_set,public.rehearsal_frozen_source_snapshot,public.rehearsal_accepted_attempt_integrity TO ple_rehearsal_source; CREATE POLICY rehearsal_evidence_source ON public.rehearsal_evidence TO ple_rehearsal_source WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_root_source_insert ON public.rehearsal_submission_claim_root FOR INSERT TO ple_rehearsal_source WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_event_source_insert ON public.rehearsal_submission_claim_event FOR INSERT TO ple_rehearsal_source WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_receipt_source_insert ON public.rehearsal_submission_receipt FOR INSERT TO ple_rehearsal_source WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_claim_receipt_source_read ON public.rehearsal_submission_receipt FOR SELECT TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()); GRANT INSERT ON public.rehearsal_evidence,public.rehearsal_submission_claim_root,public.rehearsal_submission_claim_delivery_binding,public.rehearsal_submission_claim_event,public.rehearsal_submission_receipt TO ple_rehearsal_source; GRANT UPDATE (evidence_head_digest,evidence_length,updated_at,lifecycle,terminal_at) ON public.rehearsal_run TO ple_rehearsal_source; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_append_evidence(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,text,bytea,jsonb,bytea,bigint),public.ple_rehearsal_append_frozen_item(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,uuid,uuid,uuid,jsonb,bytea,bytea,bigint),public.ple_rehearsal_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,uuid,bytea,jsonb),public.ple_rehearsal_append_claim_event(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,text),public.ple_rehearsal_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea),public.ple_rehearsal_terminalize(uuid,uuid,uuid,uuid,bigint,uuid,text) TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_rehearsal_route_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,bytea,bytea,jsonb),public.ple_rehearsal_route_append_claim_event(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,text),public.ple_rehearsal_route_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_route_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,bytea,bytea,jsonb),public.ple_rehearsal_route_append_claim_event(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,text),public.ple_rehearsal_route_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) TO ple_app; REVOKE ALL ON FUNCTION public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,bytea,text,jsonb) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,bytea,text,jsonb) TO ple_app; REVOKE ALL ON FUNCTION public.ple_rehearsal_route_append_frozen_item(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,uuid,uuid,uuid,jsonb,bytea,bytea,bigint,uuid,uuid,integer) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_route_append_frozen_item(uuid,uuid,uuid,uuid,bigint,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,uuid,uuid,uuid,jsonb,bytea,bytea,bigint,uuid,uuid,integer) TO ple_app; REVOKE ALL ON FUNCTION public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_rehearsal_mark_delivery_dispatched(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_rehearsal_abandon_delivery_before_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid,text),public.ple_rehearsal_complete_delivery(uuid,uuid,uuid,integer,bigint,bigint,uuid,text,uuid,jsonb,bytea) FROM PUBLIC; REVOKE ALL ON FUNCTION public.ple_complete_rehearsal_start_idempotent(
    uuid, uuid, uuid, bytea, jsonb, bytea
) FROM PUBLIC, ple_app, ple_student, ple_grader, ple_grading_reader; DO $$
BEGIN
    IF has_table_privilege(
           'ple_app',
           'public.rehearsal_frozen_private_execution',
           'SELECT')
       OR has_function_privilege(
           'ple_app',
           'public.ple_prepare_sealed_rehearsal_delivery_execution(uuid,uuid)',
           'EXECUTE'
       )
       OR has_function_privilege(
           'ple_app',
           'public.ple_complete_rehearsal_start_idempotent(uuid,uuid,uuid,bytea,jsonb,bytea)',
           'EXECUTE'
       ) THEN
        RAISE EXCEPTION 'application rehearsal private material is over-granted'
            USING ERRCODE = '55000';
    END IF;
    IF has_table_privilege(
           'ple_grading_reader',
           'public.rehearsal_frozen_material_set',
           'SELECT'
       )
       OR has_table_privilege(
           'ple_grading_reader',
           'public.rehearsal_frozen_source_snapshot',
           'SELECT'
       )
       OR has_table_privilege(
           'ple_grading_reader',
           'public.rehearsal_frozen_private_execution',
           'SELECT'
       )
       OR has_table_privilege(
           'ple_grading_reader',
           'public.rehearsal_delivery_generation_material_binding',
           'SELECT'
       )
       OR NOT has_function_privilege(
           'ple_grading_reader',
           'public.ple_prepare_sealed_rehearsal_delivery_execution(uuid,uuid)',
           'EXECUTE'
       ) THEN
        RAISE EXCEPTION 'sealed rehearsal grading authority is inconsistent' USING ERRCODE = '55000'; END IF; END $$; CREATE FUNCTION public.ple_verify_rehearsal_claim_delivery_binding(p_tenant uuid,p_run uuid,p_claim uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.rehearsal_submission_claim_root c JOIN public.rehearsal_submission_claim_delivery_binding b ON b.tenant_id=c.tenant_id AND b.rehearsal_run_id=c.rehearsal_run_id AND b.claim_id=c.claim_id JOIN public.rehearsal_submission_claim_event e ON e.tenant_id=c.tenant_id AND e.rehearsal_run_id=c.rehearsal_run_id AND e.claim_id=c.claim_id AND e.sequence=1 AND e.phase='prepared' JOIN public.rehearsal_delivery_operation_generation g ON g.tenant_id=b.tenant_id AND g.rehearsal_run_id=b.rehearsal_run_id AND g.root_id=b.delivery_root_id AND g.generation=b.delivery_generation AND g.operation_id=b.delivery_operation_id JOIN public.rehearsal_delivery_receipt r ON r.tenant_id=g.tenant_id AND r.rehearsal_run_id=g.rehearsal_run_id AND r.root_id=g.root_id AND r.generation=g.generation AND r.operation_id=g.operation_id JOIN public.rehearsal_delivery_issued_execution_artifact a ON a.tenant_id=g.tenant_id AND a.rehearsal_run_id=g.rehearsal_run_id AND a.root_id=g.root_id AND a.generation=g.generation AND a.operation_id=g.operation_id WHERE c.tenant_id=p_tenant AND c.rehearsal_run_id=p_run AND c.claim_id=p_claim AND b.binding_digest=public.ple_rehearsal_claim_delivery_binding_digest(c.tenant_id,c.rehearsal_run_id,c.claim_id,c.request_fingerprint,c.attempt_id,b.delivery_root_id,b.delivery_generation,b.delivery_operation_id,b.issued_screen_digest) AND e.prepared_delivery_binding_digest=b.binding_digest AND r.result_kind='issued' AND r.frozen_attempt_id=c.attempt_id AND r.screen_digest=b.issued_screen_digest AND a.attempt_id=c.attempt_id AND digest(a.artifact_bytes,'sha256')=a.artifact_sha256) $$; ALTER FUNCTION public.ple_verify_rehearsal_claim_delivery_binding(uuid,uuid,uuid) OWNER TO ple_rehearsal_source; CREATE FUNCTION public.ple_verify_rehearsal_claim_delivery_binding_from_route(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) w JOIN public.rehearsal_submission_claim_root c ON c.tenant_id=p_tenant AND c.rehearsal_run_id=w.rehearsal_run_id AND c.idempotency_key=p_key WHERE public.ple_verify_rehearsal_claim_delivery_binding(p_tenant,w.rehearsal_run_id,c.claim_id)) $$; ALTER FUNCTION public.ple_verify_rehearsal_claim_delivery_binding_from_route(uuid,uuid,uuid,integer,bigint,bigint,text) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_verify_rehearsal_claim_delivery_binding_from_route(uuid,uuid,uuid,integer,bigint,bigint,text) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_verify_rehearsal_claim_delivery_binding_from_route(uuid,uuid,uuid,integer,bigint,bigint,text) TO ple_app; ALTER TABLE public.rehearsal_submission_claim_event ADD COLUMN prepared_delivery_binding_digest bytea; CREATE FUNCTION public.ple_anchor_rehearsal_claim_delivery_binding() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF NEW.phase='prepared' THEN SELECT binding_digest INTO NEW.prepared_delivery_binding_digest FROM public.rehearsal_submission_claim_delivery_binding WHERE tenant_id=NEW.tenant_id AND rehearsal_run_id=NEW.rehearsal_run_id AND claim_id=NEW.claim_id;IF NEW.prepared_delivery_binding_digest IS NULL OR octet_length(NEW.prepared_delivery_binding_digest)<>32 THEN RAISE EXCEPTION 'prepared rehearsal claim lacks immutable delivery binding anchor' USING ERRCODE='23514';END IF;ELSIF NEW.prepared_delivery_binding_digest IS NOT NULL THEN RAISE EXCEPTION 'only prepared rehearsal claim events carry delivery binding anchor' USING ERRCODE='23514';END IF;RETURN NEW;END $$; CREATE TRIGGER rehearsal_claim_event_delivery_binding_anchor BEFORE INSERT ON public.rehearsal_submission_claim_event FOR EACH ROW EXECUTE FUNCTION public.ple_anchor_rehearsal_claim_delivery_binding(); ALTER FUNCTION public.ple_anchor_rehearsal_claim_delivery_binding() OWNER TO ple_rehearsal_source; DO $$ DECLARE constraint_row record; BEGIN ALTER TABLE public.rehearsal_delivery_operation_event ADD COLUMN deadline_at timestamptz;FOR constraint_row IN SELECT constraint_entry.conname FROM pg_constraint AS constraint_entry WHERE constraint_entry.conrelid='public.rehearsal_delivery_operation_event'::regclass AND constraint_entry.contype='c' AND pg_get_constraintdef(constraint_entry.oid) LIKE '%phase%' LOOP EXECUTE format('ALTER TABLE public.rehearsal_delivery_operation_event DROP CONSTRAINT %I',constraint_row.conname);END LOOP; ALTER TABLE public.rehearsal_delivery_operation_event ADD CONSTRAINT rehearsal_delivery_event_phase_check CHECK(phase IN('prepared','issueDispatched','completed','expired','runTimeExhaustedBeforeDispatch','abandonedBeforeDispatch','revokedStaleRevision','revokedTerminalLifecycle','revokedSourceContextRemoved')); ALTER TABLE public.rehearsal_delivery_operation_event ADD CONSTRAINT rehearsal_delivery_event_terminal_check CHECK((phase='completed' AND completion_kind='issued' AND frozen_attempt_id IS NOT NULL AND screen_digest IS NOT NULL AND octet_length(screen_digest)=32 AND abandonment_reason IS NULL AND deadline_at IS NULL) OR (phase='runTimeExhaustedBeforeDispatch' AND completion_kind IS NULL AND frozen_attempt_id IS NULL AND screen_digest IS NULL AND abandonment_reason IS NULL AND deadline_at IS NOT NULL) OR (phase='abandonedBeforeDispatch' AND completion_kind IS NULL AND frozen_attempt_id IS NULL AND screen_digest IS NULL AND abandonment_reason IN('localPreparationFailed','nativeBackendAdmissionRejected','trustedRendererAdmissionRejected') AND deadline_at IS NULL) OR (phase NOT IN('completed','abandonedBeforeDispatch','runTimeExhaustedBeforeDispatch') AND completion_kind IS NULL AND frozen_attempt_id IS NULL AND screen_digest IS NULL AND abandonment_reason IS NULL AND deadline_at IS NULL)); ALTER TABLE public.rehearsal_delivery_receipt ADD CONSTRAINT rehearsal_delivery_receipt_issued_only_check CHECK(result_kind='issued' AND frozen_attempt_id IS NOT NULL);END $$; CREATE TABLE public.rehearsal_delivery_retry_operation(tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,idempotency_key text NOT NULL,request_fingerprint bytea NOT NULL,root_id uuid NOT NULL,generation integer NOT NULL,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),PRIMARY KEY(tenant_id,rehearsal_run_id,idempotency_key),FOREIGN KEY(tenant_id,rehearsal_run_id,root_id,generation) REFERENCES public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,root_id,generation) ON DELETE RESTRICT,CHECK(char_length(idempotency_key) BETWEEN 1 AND 128 AND idempotency_key !~ '[[:cntrl:]]' AND octet_length(request_fingerprint)=32)); CREATE TABLE public.rehearsal_delivery_timing_witness(tenant_id uuid NOT NULL,rehearsal_run_id uuid NOT NULL,root_id uuid NOT NULL,generation integer NOT NULL,operation_id uuid NOT NULL,attempt_id uuid NOT NULL,subject_fingerprint bytea NOT NULL,issued_snapshot_sha256 bytea NOT NULL,run_started_at timestamptz NOT NULL,issued_at timestamptz NOT NULL,deadline_at timestamptz,deadline_source text,grace_millis bigint,expires_at timestamptz,witness_bytes bytea NOT NULL,witness_sha256 bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT public.ple_rehearsal_now(),PRIMARY KEY(tenant_id,rehearsal_run_id,root_id,generation),UNIQUE(tenant_id,rehearsal_run_id,operation_id),FOREIGN KEY(tenant_id,rehearsal_run_id,root_id,generation) REFERENCES public.rehearsal_delivery_generation_material_binding(tenant_id,rehearsal_run_id,root_id,generation) ON DELETE RESTRICT,FOREIGN KEY(tenant_id,rehearsal_run_id,operation_id) REFERENCES public.rehearsal_delivery_generation_material_binding(tenant_id,rehearsal_run_id,operation_id) ON DELETE RESTRICT,CHECK(octet_length(subject_fingerprint)=32 AND octet_length(issued_snapshot_sha256)=32 AND octet_length(witness_bytes)=99 AND octet_length(witness_sha256)=32 AND digest(convert_to('ple:rehearsal:timing-witness:v1','UTF8')||decode('00','hex')||witness_bytes,'sha256')=witness_sha256),CHECK((deadline_at IS NULL AND deadline_source IS NULL AND grace_millis IS NULL AND expires_at IS NULL) OR (deadline_at IS NOT NULL AND deadline_source IN('perQuestion','perAttempt','subjectLimit') AND grace_millis>=0 AND expires_at=deadline_at+grace_millis*interval '1 millisecond'))); CREATE TRIGGER rehearsal_delivery_retry_operation_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_delivery_retry_operation FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_operation_guard(); CREATE TRIGGER rehearsal_delivery_timing_witness_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_delivery_timing_witness FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_operation_guard(); ALTER TABLE public.rehearsal_delivery_retry_operation ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_retry_operation FORCE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_timing_witness ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_timing_witness FORCE ROW LEVEL SECURITY; CREATE POLICY rehearsal_delivery_retry_source ON public.rehearsal_delivery_retry_operation TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); CREATE POLICY rehearsal_delivery_timing_witness_source ON public.rehearsal_delivery_timing_witness TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); REVOKE ALL ON public.rehearsal_delivery_retry_operation,public.rehearsal_delivery_timing_witness FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT SELECT,INSERT,UPDATE ON public.rehearsal_delivery_retry_operation,public.rehearsal_delivery_timing_witness TO ple_rehearsal_source; GRANT UPDATE ON public.rehearsal_delivery_operation_root,public.rehearsal_delivery_operation_generation,public.rehearsal_delivery_operation_event,public.rehearsal_delivery_generation_material_binding TO ple_rehearsal_source; CREATE FUNCTION public.ple_current_rehearsal_delivery(p_tenant uuid,p_run uuid) RETURNS TABLE(selected_attempt_id uuid,selected_ordinal integer,current_root_id uuid,current_generation integer,current_operation_id uuid,current_phase text,current_sequence bigint,current_descriptor jsonb,current_screen jsonb,current_screen_digest bytea,current_deadline_millis bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE selected_row public.rehearsal_frozen_source_snapshot%ROWTYPE;root_row public.rehearsal_delivery_operation_root%ROWTYPE;generation_row public.rehearsal_delivery_operation_generation%ROWTYPE;event_row record;binding_row public.rehearsal_delivery_generation_material_binding%ROWTYPE;receipt_row public.rehearsal_delivery_receipt%ROWTYPE;root_count integer;
BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() THEN RETURN;END IF;SELECT snapshot_row.* INTO selected_row FROM public.rehearsal_frozen_source_snapshot AS snapshot_row WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=p_run AND NOT EXISTS(SELECT 1 FROM public.rehearsal_accepted_attempt_integrity AS accepted_row WHERE accepted_row.tenant_id=snapshot_row.tenant_id AND accepted_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND accepted_row.attempt_id=snapshot_row.attempt_id) ORDER BY snapshot_row.ordinal LIMIT 1;IF NOT FOUND THEN RETURN;END IF;SELECT count(*) INTO root_count FROM public.rehearsal_delivery_operation_root AS candidate_root WHERE candidate_root.tenant_id=p_tenant AND candidate_root.rehearsal_run_id=p_run AND candidate_root.selected_attempt_id=selected_row.attempt_id;IF root_count>1 THEN RAISE EXCEPTION 'multiple roots for current rehearsal item' USING ERRCODE='23514';END IF;IF root_count=0 THEN RETURN QUERY SELECT selected_row.attempt_id,selected_row.ordinal,NULL::uuid,NULL::integer,NULL::uuid,NULL::text,NULL::bigint,NULL::jsonb,NULL::jsonb,NULL::bytea,NULL::bigint;RETURN;END IF;SELECT candidate_root.* INTO root_row FROM public.rehearsal_delivery_operation_root AS candidate_root WHERE candidate_root.tenant_id=p_tenant AND candidate_root.rehearsal_run_id=p_run AND candidate_root.selected_attempt_id=selected_row.attempt_id FOR UPDATE;SELECT candidate_generation.* INTO generation_row FROM public.rehearsal_delivery_operation_generation AS candidate_generation WHERE candidate_generation.tenant_id=p_tenant AND candidate_generation.rehearsal_run_id=p_run AND candidate_generation.root_id=root_row.root_id ORDER BY candidate_generation.generation DESC LIMIT 1 FOR UPDATE;SELECT candidate_event.* INTO event_row FROM public.rehearsal_delivery_operation_event AS candidate_event WHERE candidate_event.tenant_id=p_tenant AND candidate_event.rehearsal_run_id=p_run AND candidate_event.root_id=root_row.root_id AND candidate_event.generation=generation_row.generation ORDER BY candidate_event.sequence DESC LIMIT 1 FOR UPDATE;SELECT candidate_binding.* INTO binding_row FROM public.rehearsal_delivery_generation_material_binding AS candidate_binding WHERE candidate_binding.tenant_id=p_tenant AND candidate_binding.rehearsal_run_id=p_run AND candidate_binding.root_id=root_row.root_id AND candidate_binding.generation=generation_row.generation FOR UPDATE;IF generation_row.operation_id IS NULL OR event_row.sequence IS NULL OR binding_row.operation_id IS NULL OR binding_row.operation_id<>generation_row.operation_id OR binding_row.attempt_id<>selected_row.attempt_id THEN RAISE EXCEPTION 'invalid current rehearsal delivery aggregate' USING ERRCODE='23514';END IF;SELECT candidate_receipt.* INTO receipt_row FROM public.rehearsal_delivery_receipt AS candidate_receipt WHERE candidate_receipt.tenant_id=p_tenant AND candidate_receipt.rehearsal_run_id=p_run AND candidate_receipt.root_id=root_row.root_id AND candidate_receipt.generation=generation_row.generation;RETURN QUERY SELECT selected_row.attempt_id,selected_row.ordinal,root_row.root_id,generation_row.generation,generation_row.operation_id,event_row.phase,event_row.sequence,generation_row.execution_descriptor,receipt_row.screen_projection,receipt_row.screen_digest,CASE WHEN event_row.deadline_at IS NULL THEN NULL ELSE (extract(epoch FROM event_row.deadline_at)*1000)::bigint END;END $$; CREATE FUNCTION public.ple_expected_rehearsal_timing_witness(p_tenant uuid,p_run uuid,p_root uuid,p_generation integer,p_issued_at_millis bigint) RETURNS TABLE(expected_operation_id uuid,expected_attempt_id uuid,expected_subject_fingerprint bytea,expected_snapshot_sha256 bytea,expected_run_started_millis bigint,expected_issued_at_millis bigint,expected_deadline_at_millis bigint,expected_deadline_source text,expected_grace_millis bigint,expected_expires_at_millis bigint,expected_witness_bytes bytea,expected_witness_sha256 bytea,expected_run_time_exhausted boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE material_row record;question_deadline bigint;question_source text;question_grace bigint;subject_deadline bigint;selected_deadline bigint;selected_source text;selected_grace bigint;canonical bytea;source_byte bytea;run_millis bigint;
BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_issued_at_millis IS NULL OR NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,p_run) THEN RETURN;END IF;SELECT generation_row.operation_id,generation_row.selected_attempt_id,run_row.subject_fingerprint,run_row.started_at,header_row.frozen_inventory_digest,header_row.subject_time_limit_seconds,snapshot_row.issued_snapshot_sha256,snapshot_row.timing_kind,snapshot_row.timing_seconds,snapshot_row.timing_grace_seconds,private_row.private_execution_sha256,binding_row.material_set_digest,binding_row.issued_snapshot_sha256 AS bound_snapshot_sha256,binding_row.private_execution_sha256 AS bound_private_sha256,binding_row.operation_id AS bound_operation_id,root_row.selected_attempt_id AS root_attempt_id INTO material_row FROM public.rehearsal_delivery_operation_generation AS generation_row JOIN public.rehearsal_delivery_operation_root AS root_row ON root_row.tenant_id=generation_row.tenant_id AND root_row.rehearsal_run_id=generation_row.rehearsal_run_id AND root_row.root_id=generation_row.root_id JOIN public.rehearsal_run AS run_row ON run_row.tenant_id=generation_row.tenant_id AND run_row.rehearsal_run_id=generation_row.rehearsal_run_id JOIN public.rehearsal_frozen_material_set AS header_row ON header_row.tenant_id=generation_row.tenant_id AND header_row.rehearsal_run_id=generation_row.rehearsal_run_id JOIN public.rehearsal_frozen_source_snapshot AS snapshot_row ON snapshot_row.tenant_id=generation_row.tenant_id AND snapshot_row.rehearsal_run_id=generation_row.rehearsal_run_id AND snapshot_row.attempt_id=generation_row.selected_attempt_id JOIN public.rehearsal_frozen_private_execution AS private_row ON private_row.tenant_id=snapshot_row.tenant_id AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND private_row.attempt_id=snapshot_row.attempt_id JOIN public.rehearsal_delivery_generation_material_binding AS binding_row ON binding_row.tenant_id=generation_row.tenant_id AND binding_row.rehearsal_run_id=generation_row.rehearsal_run_id AND binding_row.root_id=generation_row.root_id AND binding_row.generation=generation_row.generation WHERE generation_row.tenant_id=p_tenant AND generation_row.rehearsal_run_id=p_run AND generation_row.root_id=p_root AND generation_row.generation=p_generation;IF NOT FOUND OR material_row.selected_attempt_id<>material_row.root_attempt_id OR material_row.operation_id<>material_row.bound_operation_id OR material_row.frozen_inventory_digest<>material_row.material_set_digest OR material_row.issued_snapshot_sha256<>material_row.bound_snapshot_sha256 OR material_row.private_execution_sha256<>material_row.bound_private_sha256 THEN RETURN;END IF;run_millis:=(extract(epoch FROM material_row.started_at)*1000)::bigint;IF p_issued_at_millis<run_millis THEN RETURN;END IF;IF material_row.timing_kind='perQuestion' THEN question_deadline:=p_issued_at_millis+material_row.timing_seconds::bigint*1000;question_source:='perQuestion';question_grace:=material_row.timing_grace_seconds::bigint*1000;ELSIF material_row.timing_kind='perAttempt' THEN question_deadline:=run_millis+material_row.timing_seconds::bigint*1000;question_source:='perAttempt';question_grace:=material_row.timing_grace_seconds::bigint*1000;END IF;IF material_row.subject_time_limit_seconds IS NOT NULL THEN subject_deadline:=run_millis+material_row.subject_time_limit_seconds::bigint*1000;END IF;IF subject_deadline IS NOT NULL AND (question_deadline IS NULL OR subject_deadline<=question_deadline) THEN selected_deadline:=subject_deadline;selected_source:='subjectLimit';selected_grace:=0;ELSE selected_deadline:=question_deadline;selected_source:=question_source;selected_grace:=question_grace;END IF;source_byte:=CASE selected_source WHEN 'perQuestion' THEN decode('01','hex') WHEN 'perAttempt' THEN decode('02','hex') WHEN 'subjectLimit' THEN decode('03','hex') ELSE decode('00','hex') END;canonical:=material_row.subject_fingerprint||material_row.issued_snapshot_sha256||int8send(run_millis)||int8send(p_issued_at_millis)||CASE WHEN selected_deadline IS NULL THEN decode('00','hex')||int8send(0) ELSE decode('01','hex')||int8send(selected_deadline) END||source_byte||CASE WHEN selected_grace IS NULL THEN decode('00','hex')||int8send(0) ELSE decode('01','hex')||int8send(selected_grace) END;RETURN QUERY SELECT material_row.operation_id,material_row.selected_attempt_id,material_row.subject_fingerprint,material_row.issued_snapshot_sha256,run_millis,p_issued_at_millis,selected_deadline,selected_source,selected_grace,CASE WHEN selected_deadline IS NULL THEN NULL ELSE selected_deadline+selected_grace END,canonical,digest(convert_to('ple:rehearsal:timing-witness:v1','UTF8')||decode('00','hex')||canonical,'sha256'),COALESCE(selected_deadline<p_issued_at_millis AND selected_source IN('perAttempt','subjectLimit'),false);END $$; CREATE FUNCTION public.ple_verify_persisted_rehearsal_timing_witness(p_tenant uuid,p_run uuid,p_root uuid,p_generation integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE stored_row public.rehearsal_delivery_timing_witness%ROWTYPE;expected_row record;
BEGIN SELECT witness_row.* INTO stored_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=p_run AND witness_row.root_id=p_root AND witness_row.generation=p_generation FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,p_run,p_root,p_generation,(extract(epoch FROM stored_row.issued_at)*1000)::bigint);IF NOT FOUND THEN RETURN false;END IF;RETURN stored_row.operation_id=expected_row.expected_operation_id AND stored_row.attempt_id=expected_row.expected_attempt_id AND stored_row.subject_fingerprint=expected_row.expected_subject_fingerprint AND stored_row.issued_snapshot_sha256=expected_row.expected_snapshot_sha256 AND (extract(epoch FROM stored_row.run_started_at)*1000)::bigint=expected_row.expected_run_started_millis AND (extract(epoch FROM stored_row.issued_at)*1000)::bigint=expected_row.expected_issued_at_millis AND (CASE WHEN stored_row.deadline_at IS NULL THEN NULL ELSE (extract(epoch FROM stored_row.deadline_at)*1000)::bigint END) IS NOT DISTINCT FROM expected_row.expected_deadline_at_millis AND stored_row.deadline_source IS NOT DISTINCT FROM expected_row.expected_deadline_source AND stored_row.grace_millis IS NOT DISTINCT FROM expected_row.expected_grace_millis AND (CASE WHEN stored_row.expires_at IS NULL THEN NULL ELSE (extract(epoch FROM stored_row.expires_at)*1000)::bigint END) IS NOT DISTINCT FROM expected_row.expected_expires_at_millis AND stored_row.witness_bytes=expected_row.expected_witness_bytes AND stored_row.witness_sha256=expected_row.expected_witness_sha256;END $$; CREATE OR REPLACE FUNCTION public.ple_copy_rehearsal_generation_material_binding() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$
BEGIN IF NEW.generation>1 THEN IF NOT public.ple_verify_rehearsal_frozen_material_set(NEW.tenant_id,NEW.rehearsal_run_id) THEN RAISE EXCEPTION 'rehearsal successor has invalid frozen material' USING ERRCODE='23514';END IF;INSERT INTO public.rehearsal_delivery_generation_material_binding(tenant_id,rehearsal_run_id,root_id,generation,operation_id,attempt_id,material_set_digest,issued_snapshot_sha256,private_execution_sha256) SELECT prior_row.tenant_id,prior_row.rehearsal_run_id,prior_row.root_id,NEW.generation,NEW.operation_id,prior_row.attempt_id,prior_row.material_set_digest,prior_row.issued_snapshot_sha256,prior_row.private_execution_sha256 FROM public.rehearsal_delivery_generation_material_binding AS prior_row JOIN public.rehearsal_frozen_material_set AS header_row ON header_row.tenant_id=prior_row.tenant_id AND header_row.rehearsal_run_id=prior_row.rehearsal_run_id JOIN public.rehearsal_frozen_source_snapshot AS snapshot_row ON snapshot_row.tenant_id=prior_row.tenant_id AND snapshot_row.rehearsal_run_id=prior_row.rehearsal_run_id AND snapshot_row.attempt_id=prior_row.attempt_id JOIN public.rehearsal_frozen_private_execution AS private_row ON private_row.tenant_id=snapshot_row.tenant_id AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND private_row.attempt_id=snapshot_row.attempt_id WHERE prior_row.tenant_id=NEW.tenant_id AND prior_row.rehearsal_run_id=NEW.rehearsal_run_id AND prior_row.root_id=NEW.root_id AND prior_row.generation=NEW.generation-1 AND prior_row.attempt_id=NEW.selected_attempt_id AND prior_row.material_set_digest=header_row.frozen_inventory_digest AND prior_row.issued_snapshot_sha256=snapshot_row.issued_snapshot_sha256 AND prior_row.private_execution_sha256=private_row.private_execution_sha256;IF NOT FOUND THEN RAISE EXCEPTION 'rehearsal successor lacks exact material binding' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END $$; CREATE FUNCTION public.ple_prepare_rehearsal_timing_dispatch(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_operation uuid) RETURNS TABLE(subject_fingerprint bytea,run_started_at_millis bigint,issued_at_millis bigint,issued_snapshot_sha256 bytea,timing_kind text,question_seconds integer,question_grace_seconds integer,subject_limit_seconds integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;current_row record;expected_row record;snapshot_row public.rehearsal_frozen_source_snapshot%ROWTYPE;header_row public.rehearsal_frozen_material_set%ROWTYPE;issue_millis bigint;
BEGIN SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR p_operation IS NULL THEN RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND OR current_row.current_operation_id IS DISTINCT FROM p_operation OR current_row.current_phase<>'prepared' THEN RETURN;END IF;issue_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,issue_millis) AS witness_row;IF NOT FOUND THEN RETURN;END IF;SELECT frozen_snapshot.* INTO snapshot_row FROM public.rehearsal_frozen_source_snapshot AS frozen_snapshot WHERE frozen_snapshot.tenant_id=p_tenant AND frozen_snapshot.rehearsal_run_id=route_row.rehearsal_run_id AND frozen_snapshot.attempt_id=expected_row.expected_attempt_id;SELECT frozen_header.* INTO header_row FROM public.rehearsal_frozen_material_set AS frozen_header WHERE frozen_header.tenant_id=p_tenant AND frozen_header.rehearsal_run_id=route_row.rehearsal_run_id;IF snapshot_row.attempt_id IS NULL OR header_row.rehearsal_run_id IS NULL THEN RETURN;END IF;RETURN QUERY SELECT expected_row.expected_subject_fingerprint,expected_row.expected_run_started_millis,expected_row.expected_issued_at_millis,expected_row.expected_snapshot_sha256,snapshot_row.timing_kind,snapshot_row.timing_seconds,snapshot_row.timing_grace_seconds,header_row.subject_time_limit_seconds;END $$; CREATE FUNCTION public.ple_finalize_rehearsal_timing_dispatch(p_tenant uuid,p_operation uuid,p_issued_at_millis bigint,p_deadline_at_millis bigint,p_grace_millis bigint,p_expires_at_millis bigint,p_deadline_source text,p_witness_bytes bytea,p_witness_sha256 bytea) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE located_run uuid;current_row record;expected_row record;now_millis bigint;
BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_operation IS NULL THEN RETURN false;END IF;SELECT generation_row.rehearsal_run_id INTO located_run FROM public.rehearsal_delivery_operation_generation AS generation_row WHERE generation_row.tenant_id=p_tenant AND generation_row.operation_id=p_operation;IF NOT FOUND THEN RETURN false;END IF;PERFORM 1 FROM public.rehearsal_run AS run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=located_run AND run_row.lifecycle='active' FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,located_run) AS delivery_row;IF NOT FOUND OR current_row.current_operation_id IS DISTINCT FROM p_operation OR current_row.current_phase<>'prepared' THEN RETURN false;END IF;now_millis:=public.ple_rehearsal_now_millis();IF p_issued_at_millis IS DISTINCT FROM now_millis THEN RETURN false;END IF;SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,located_run,current_row.current_root_id,current_row.current_generation,now_millis) AS witness_row;IF NOT FOUND OR expected_row.expected_run_time_exhausted OR p_deadline_at_millis IS DISTINCT FROM expected_row.expected_deadline_at_millis OR p_grace_millis IS DISTINCT FROM expected_row.expected_grace_millis OR p_expires_at_millis IS DISTINCT FROM expected_row.expected_expires_at_millis OR p_deadline_source IS DISTINCT FROM expected_row.expected_deadline_source OR p_witness_bytes IS DISTINCT FROM expected_row.expected_witness_bytes OR p_witness_sha256 IS DISTINCT FROM expected_row.expected_witness_sha256 THEN RETURN false;END IF;INSERT INTO public.rehearsal_delivery_timing_witness(tenant_id,rehearsal_run_id,root_id,generation,operation_id,attempt_id,subject_fingerprint,issued_snapshot_sha256,run_started_at,issued_at,deadline_at,deadline_source,grace_millis,expires_at,witness_bytes,witness_sha256) VALUES(p_tenant,located_run,current_row.current_root_id,current_row.current_generation,p_operation,expected_row.expected_attempt_id,expected_row.expected_subject_fingerprint,expected_row.expected_snapshot_sha256,public.ple_rehearsal_timestamp_from_millis(expected_row.expected_run_started_millis),public.ple_rehearsal_timestamp_from_millis(expected_row.expected_issued_at_millis),CASE WHEN expected_row.expected_deadline_at_millis IS NULL THEN NULL ELSE public.ple_rehearsal_timestamp_from_millis(expected_row.expected_deadline_at_millis) END,expected_row.expected_deadline_source,expected_row.expected_grace_millis,CASE WHEN expected_row.expected_expires_at_millis IS NULL THEN NULL ELSE public.ple_rehearsal_timestamp_from_millis(expected_row.expected_expires_at_millis) END,expected_row.expected_witness_bytes,expected_row.expected_witness_sha256);INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase) VALUES(p_tenant,located_run,current_row.current_root_id,current_row.current_generation,p_operation,current_row.current_sequence+1,'issueDispatched');RETURN true;EXCEPTION WHEN unique_violation THEN RETURN false;END $$; CREATE FUNCTION public.ple_finalize_rehearsal_timing_exhausted(p_tenant uuid,p_operation uuid) RETURNS TABLE(deadline_at_millis bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE located_run uuid;current_row record;expected_row record;now_millis bigint;
BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_operation IS NULL THEN RETURN;END IF;SELECT generation_row.rehearsal_run_id INTO located_run FROM public.rehearsal_delivery_operation_generation AS generation_row WHERE generation_row.tenant_id=p_tenant AND generation_row.operation_id=p_operation;IF NOT FOUND THEN RETURN;END IF;PERFORM 1 FROM public.rehearsal_run AS run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=located_run AND run_row.lifecycle='active' FOR UPDATE;IF NOT FOUND THEN RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,located_run) AS delivery_row;IF NOT FOUND OR current_row.current_operation_id IS DISTINCT FROM p_operation OR current_row.current_phase<>'prepared' THEN RETURN;END IF;now_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,located_run,current_row.current_root_id,current_row.current_generation,now_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR expected_row.expected_deadline_at_millis IS NULL THEN RETURN;END IF;INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase,deadline_at) VALUES(p_tenant,located_run,current_row.current_root_id,current_row.current_generation,p_operation,current_row.current_sequence+1,'runTimeExhaustedBeforeDispatch',public.ple_rehearsal_timestamp_from_millis(expected_row.expected_deadline_at_millis));RETURN QUERY SELECT expected_row.expected_deadline_at_millis;END $$; CREATE FUNCTION public.ple_reconcile_current_rehearsal_delivery(p_tenant uuid,p_run uuid) RETURNS TABLE(verdict text,deadline_at_millis bigint,expires_at_millis bigint,retry_disposition text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE current_row record;timing_row public.rehearsal_delivery_timing_witness%ROWTYPE;expected_row record;observed_millis bigint;
BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() THEN RETURN;END IF;PERFORM 1 FROM public.rehearsal_run AS run_row WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=p_run AND run_row.lifecycle='active' FOR UPDATE;IF NOT FOUND THEN RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,p_run) AS delivery_row;IF NOT FOUND OR current_row.current_root_id IS NULL THEN RETURN;END IF;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=p_run AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation ORDER BY retry_row.idempotency_key FOR UPDATE;observed_millis:=public.ple_rehearsal_now_millis();IF current_row.current_phase='runTimeExhaustedBeforeDispatch' THEN SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,p_run,current_row.current_root_id,current_row.current_generation,observed_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR current_row.current_deadline_millis IS DISTINCT FROM expected_row.expected_deadline_at_millis THEN RAISE EXCEPTION 'invalid rehearsal hard timing terminal' USING ERRCODE='23514';END IF;RETURN QUERY SELECT 'expired'::text,expected_row.expected_deadline_at_millis,expected_row.expected_deadline_at_millis,'runTimeExhausted'::text;RETURN;END IF;IF current_row.current_phase NOT IN('issueDispatched','completed','expired') THEN RETURN;END IF;IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,p_run,current_row.current_root_id,current_row.current_generation) THEN RAISE EXCEPTION 'invalid persisted rehearsal timing witness' USING ERRCODE='23514';END IF;SELECT witness_row.* INTO timing_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=p_run AND witness_row.root_id=current_row.current_root_id AND witness_row.generation=current_row.current_generation;deadline_at_millis:=CASE WHEN timing_row.deadline_at IS NULL THEN NULL ELSE (extract(epoch FROM timing_row.deadline_at)*1000)::bigint END;expires_at_millis:=CASE WHEN timing_row.expires_at IS NULL THEN NULL ELSE (extract(epoch FROM timing_row.expires_at)*1000)::bigint END;IF observed_millis<(extract(epoch FROM timing_row.issued_at)*1000)::bigint THEN RAISE EXCEPTION 'rehearsal timing observation precedes issue' USING ERRCODE='23514';END IF;IF current_row.current_phase='expired' THEN verdict:='expired';retry_disposition:=CASE WHEN timing_row.deadline_source='perQuestion' THEN 'available' ELSE 'runTimeExhausted' END;RETURN NEXT;RETURN;END IF;retry_disposition:='notApplicable';IF timing_row.deadline_at IS NULL THEN verdict:='untimed';ELSIF observed_millis<=deadline_at_millis THEN verdict:='open';ELSIF observed_millis<=expires_at_millis THEN verdict:='gracePeriod';ELSE verdict:='expired';retry_disposition:=CASE WHEN timing_row.deadline_source='perQuestion' THEN 'available' ELSE 'runTimeExhausted' END;INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase) VALUES(p_tenant,p_run,current_row.current_root_id,current_row.current_generation,current_row.current_operation_id,current_row.current_sequence+1,'expired');END IF;RETURN NEXT;END $$; CREATE FUNCTION public.ple_reconcile_rehearsal_delivery_expiry(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint) RETURNS TABLE(verdict text,deadline_at_millis bigint,expires_at_millis bigint,retry_disposition text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;
BEGIN SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND THEN RETURN;END IF;RETURN QUERY SELECT timing_result.verdict,timing_result.deadline_at_millis,timing_result.expires_at_millis,timing_result.retry_disposition FROM public.ple_reconcile_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS timing_result;END $$; CREATE FUNCTION public.ple_prepare_rehearsal_delivery_retry(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text,p_fingerprint bytea) RETURNS TABLE(result_kind text,operation_id uuid,execution_descriptor jsonb,deadline_at_millis bigint,screen_projection jsonb,screen_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;map_row public.rehearsal_delivery_retry_operation%ROWTYPE;root_row public.rehearsal_delivery_operation_root%ROWTYPE;generation_row public.rehearsal_delivery_operation_generation%ROWTYPE;event_row public.rehearsal_delivery_operation_event%ROWTYPE;binding_row public.rehearsal_delivery_generation_material_binding%ROWTYPE;timing_row public.rehearsal_delivery_timing_witness%ROWTYPE;receipt_row public.rehearsal_delivery_receipt%ROWTYPE;current_row record;expected_row record;successor uuid:=gen_random_uuid();observed_millis bigint;
BEGIN IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' OR octet_length(p_fingerprint)<>32 THEN RETURN;END IF;SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,route_row.rehearsal_run_id) THEN RETURN;END IF;IF EXISTS(SELECT 1 FROM public.rehearsal_delivery_operation_root AS collision_root WHERE collision_root.tenant_id=p_tenant AND collision_root.rehearsal_run_id=route_row.rehearsal_run_id AND collision_root.idempotency_key=p_key) THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT retry_row.* INTO map_row FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.idempotency_key=p_key;IF FOUND THEN IF map_row.request_fingerprint<>p_fingerprint THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT delivery_root.* INTO root_row FROM public.rehearsal_delivery_operation_root AS delivery_root WHERE delivery_root.tenant_id=p_tenant AND delivery_root.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_root.root_id=map_row.root_id FOR UPDATE;SELECT delivery_generation.* INTO generation_row FROM public.rehearsal_delivery_operation_generation AS delivery_generation WHERE delivery_generation.tenant_id=p_tenant AND delivery_generation.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_generation.root_id=map_row.root_id AND delivery_generation.generation=map_row.generation FOR UPDATE;SELECT delivery_event.* INTO event_row FROM public.rehearsal_delivery_operation_event AS delivery_event WHERE delivery_event.tenant_id=p_tenant AND delivery_event.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_event.root_id=map_row.root_id AND delivery_event.generation=map_row.generation ORDER BY delivery_event.sequence DESC LIMIT 1 FOR UPDATE;SELECT material_binding.* INTO binding_row FROM public.rehearsal_delivery_generation_material_binding AS material_binding WHERE material_binding.tenant_id=p_tenant AND material_binding.rehearsal_run_id=route_row.rehearsal_run_id AND material_binding.root_id=map_row.root_id AND material_binding.generation=map_row.generation FOR UPDATE;SELECT retry_row.* INTO map_row FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.idempotency_key=p_key FOR UPDATE;IF root_row.root_id IS NULL OR generation_row.operation_id IS NULL OR event_row.sequence IS NULL OR binding_row.operation_id IS DISTINCT FROM generation_row.operation_id OR binding_row.attempt_id IS DISTINCT FROM generation_row.selected_attempt_id OR map_row.root_id IS DISTINCT FROM generation_row.root_id OR map_row.generation IS DISTINCT FROM generation_row.generation THEN RAISE EXCEPTION 'invalid rehearsal retry mapping' USING ERRCODE='23514';END IF;IF event_row.phase='prepared' THEN result_kind:='prepared';operation_id:=generation_row.operation_id;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;RETURN;ELSIF event_row.phase='issueDispatched' THEN IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,generation_row.root_id,generation_row.generation) THEN RAISE EXCEPTION 'invalid mapped rehearsal timing witness' USING ERRCODE='23514';END IF;result_kind:='pending';operation_id:=generation_row.operation_id;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;RETURN;ELSIF event_row.phase='completed' THEN IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,generation_row.root_id,generation_row.generation) THEN RAISE EXCEPTION 'invalid mapped rehearsal timing witness' USING ERRCODE='23514';END IF;SELECT receipt.* INTO receipt_row FROM public.rehearsal_delivery_receipt AS receipt WHERE receipt.tenant_id=p_tenant AND receipt.rehearsal_run_id=route_row.rehearsal_run_id AND receipt.root_id=generation_row.root_id AND receipt.generation=generation_row.generation;IF receipt_row.operation_id IS DISTINCT FROM generation_row.operation_id OR receipt_row.screen_digest IS DISTINCT FROM event_row.screen_digest THEN RAISE EXCEPTION 'invalid mapped rehearsal receipt' USING ERRCODE='23514';END IF;result_kind:='replay';screen_projection:=receipt_row.screen_projection;screen_digest:=receipt_row.screen_digest;RETURN NEXT;RETURN;ELSIF event_row.phase='runTimeExhaustedBeforeDispatch' THEN observed_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,generation_row.root_id,generation_row.generation,observed_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR (extract(epoch FROM event_row.deadline_at)*1000)::bigint IS DISTINCT FROM expected_row.expected_deadline_at_millis THEN RAISE EXCEPTION 'invalid mapped rehearsal hard terminal' USING ERRCODE='23514';END IF;result_kind:='runTimeExhausted';deadline_at_millis:=expected_row.expected_deadline_at_millis;RETURN NEXT;RETURN;ELSIF event_row.phase='expired' THEN IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,generation_row.root_id,generation_row.generation) THEN RAISE EXCEPTION 'invalid mapped rehearsal timing witness' USING ERRCODE='23514';END IF;SELECT witness_row.* INTO timing_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=route_row.rehearsal_run_id AND witness_row.root_id=generation_row.root_id AND witness_row.generation=generation_row.generation;IF timing_row.deadline_source<>'perQuestion' THEN result_kind:='runTimeExhausted';deadline_at_millis:=(extract(epoch FROM timing_row.deadline_at)*1000)::bigint;ELSE result_kind:='conflict';END IF;RETURN NEXT;RETURN;ELSE result_kind:='conflict';RETURN NEXT;RETURN;END IF;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND OR current_row.current_root_id IS NULL THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation ORDER BY retry_row.idempotency_key FOR UPDATE;IF current_row.current_phase='runTimeExhaustedBeforeDispatch' THEN observed_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,observed_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR current_row.current_deadline_millis IS DISTINCT FROM expected_row.expected_deadline_at_millis THEN RAISE EXCEPTION 'invalid rehearsal hard terminal' USING ERRCODE='23514';END IF;INSERT INTO public.rehearsal_delivery_retry_operation(tenant_id,rehearsal_run_id,idempotency_key,request_fingerprint,root_id,generation) VALUES(p_tenant,route_row.rehearsal_run_id,p_key,p_fingerprint,current_row.current_root_id,current_row.current_generation);result_kind:='runTimeExhausted';deadline_at_millis:=expected_row.expected_deadline_at_millis;RETURN NEXT;RETURN;END IF;IF current_row.current_phase<>'expired' OR NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation) THEN IF current_row.current_phase='expired' THEN RAISE EXCEPTION 'invalid rehearsal retry timing witness' USING ERRCODE='23514';END IF;result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT witness_row.* INTO timing_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=route_row.rehearsal_run_id AND witness_row.root_id=current_row.current_root_id AND witness_row.generation=current_row.current_generation;IF timing_row.deadline_source<>'perQuestion' THEN INSERT INTO public.rehearsal_delivery_retry_operation(tenant_id,rehearsal_run_id,idempotency_key,request_fingerprint,root_id,generation) VALUES(p_tenant,route_row.rehearsal_run_id,p_key,p_fingerprint,current_row.current_root_id,current_row.current_generation);result_kind:='runTimeExhausted';deadline_at_millis:=(extract(epoch FROM timing_row.deadline_at)*1000)::bigint;RETURN NEXT;RETURN;END IF;IF current_row.current_generation>=2147483647 THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT delivery_generation.* INTO generation_row FROM public.rehearsal_delivery_operation_generation AS delivery_generation WHERE delivery_generation.tenant_id=p_tenant AND delivery_generation.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_generation.root_id=current_row.current_root_id AND delivery_generation.generation=current_row.current_generation;INSERT INTO public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,root_id,generation,operation_id,selected_attempt_id,execution_descriptor,descriptor_digest,structural_binding) VALUES(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation+1,successor,generation_row.selected_attempt_id,generation_row.execution_descriptor,generation_row.descriptor_digest,generation_row.structural_binding);INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase) VALUES(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation+1,successor,1,'prepared');INSERT INTO public.rehearsal_delivery_retry_operation(tenant_id,rehearsal_run_id,idempotency_key,request_fingerprint,root_id,generation) VALUES(p_tenant,route_row.rehearsal_run_id,p_key,p_fingerprint,current_row.current_root_id,current_row.current_generation+1);result_kind:='prepared';operation_id:=successor;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;END $$;
DROP FUNCTION public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea); CREATE FUNCTION public.ple_prepare_rehearsal_delivery(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text,p_fingerprint bytea) RETURNS TABLE(result_kind text,operation_id uuid,prepare_nonce uuid,admission_witness jsonb,admission_digest bytea,screen_projection jsonb,screen_digest bytea,phase text,execution_descriptor jsonb,deadline_at_millis bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;root_row public.rehearsal_delivery_operation_root%ROWTYPE;generation_row public.rehearsal_delivery_operation_generation%ROWTYPE;event_row public.rehearsal_delivery_operation_event%ROWTYPE;binding_row public.rehearsal_delivery_generation_material_binding%ROWTYPE;receipt_row public.rehearsal_delivery_receipt%ROWTYPE;timing_row public.rehearsal_delivery_timing_witness%ROWTYPE;current_row record;expected_row record;witness jsonb;witness_digest bytea;nonce uuid:=gen_random_uuid();successor uuid;retry_count integer;observed_millis bigint;
BEGIN IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' OR octet_length(p_fingerprint)<>32 THEN RETURN;END IF;SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,route_row.rehearsal_run_id) THEN RETURN;END IF;SELECT delivery_root.* INTO root_row FROM public.rehearsal_delivery_operation_root AS delivery_root WHERE delivery_root.tenant_id=p_tenant AND delivery_root.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_root.idempotency_key=p_key FOR UPDATE;IF FOUND THEN IF root_row.request_fingerprint<>p_fingerprint OR EXISTS(SELECT 1 FROM public.rehearsal_delivery_retry_operation AS collision_map WHERE collision_map.tenant_id=p_tenant AND collision_map.rehearsal_run_id=route_row.rehearsal_run_id AND collision_map.idempotency_key=p_key) THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT delivery_generation.* INTO generation_row FROM public.rehearsal_delivery_operation_generation AS delivery_generation WHERE delivery_generation.tenant_id=p_tenant AND delivery_generation.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_generation.root_id=root_row.root_id ORDER BY delivery_generation.generation DESC LIMIT 1 FOR UPDATE;SELECT delivery_event.* INTO event_row FROM public.rehearsal_delivery_operation_event AS delivery_event WHERE delivery_event.tenant_id=p_tenant AND delivery_event.rehearsal_run_id=route_row.rehearsal_run_id AND delivery_event.root_id=root_row.root_id AND delivery_event.generation=generation_row.generation ORDER BY delivery_event.sequence DESC LIMIT 1 FOR UPDATE;SELECT material_binding.* INTO binding_row FROM public.rehearsal_delivery_generation_material_binding AS material_binding WHERE material_binding.tenant_id=p_tenant AND material_binding.rehearsal_run_id=route_row.rehearsal_run_id AND material_binding.root_id=root_row.root_id AND material_binding.generation=generation_row.generation FOR UPDATE;SELECT count(*) INTO retry_count FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=root_row.root_id AND retry_row.generation=generation_row.generation;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=root_row.root_id AND retry_row.generation=generation_row.generation ORDER BY retry_row.idempotency_key FOR UPDATE;IF generation_row.operation_id IS NULL OR event_row.sequence IS NULL OR binding_row.operation_id IS DISTINCT FROM generation_row.operation_id OR binding_row.attempt_id IS DISTINCT FROM generation_row.selected_attempt_id THEN RAISE EXCEPTION 'invalid rehearsal delivery aggregate' USING ERRCODE='23514';END IF;IF event_row.phase='runTimeExhaustedBeforeDispatch' THEN observed_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,root_row.root_id,generation_row.generation,observed_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR (extract(epoch FROM event_row.deadline_at)*1000)::bigint IS DISTINCT FROM expected_row.expected_deadline_at_millis THEN RAISE EXCEPTION 'invalid rehearsal hard terminal' USING ERRCODE='23514';END IF;result_kind:='runTimeExhausted';deadline_at_millis:=expected_row.expected_deadline_at_millis;RETURN NEXT;RETURN;ELSIF event_row.phase='expired' THEN IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,root_row.root_id,generation_row.generation) THEN RAISE EXCEPTION 'invalid rehearsal expiry witness' USING ERRCODE='23514';END IF;SELECT witness_row.* INTO timing_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=route_row.rehearsal_run_id AND witness_row.root_id=root_row.root_id AND witness_row.generation=generation_row.generation;deadline_at_millis:=(extract(epoch FROM timing_row.deadline_at)*1000)::bigint;result_kind:=CASE WHEN timing_row.deadline_source='perQuestion' THEN 'expired' ELSE 'runTimeExhausted' END;RETURN NEXT;RETURN;END IF;IF retry_count>0 THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;IF event_row.phase IN('issueDispatched','completed') AND NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,root_row.root_id,generation_row.generation) THEN RAISE EXCEPTION 'invalid rehearsal timing witness' USING ERRCODE='23514';END IF;IF event_row.phase='completed' THEN SELECT receipt.* INTO receipt_row FROM public.rehearsal_delivery_receipt AS receipt WHERE receipt.tenant_id=p_tenant AND receipt.rehearsal_run_id=route_row.rehearsal_run_id AND receipt.root_id=root_row.root_id AND receipt.generation=generation_row.generation;IF receipt_row.operation_id IS DISTINCT FROM generation_row.operation_id OR receipt_row.screen_digest IS DISTINCT FROM event_row.screen_digest THEN RAISE EXCEPTION 'invalid rehearsal delivery receipt' USING ERRCODE='23514';END IF;result_kind:='replay';screen_projection:=receipt_row.screen_projection;screen_digest:=receipt_row.screen_digest;RETURN NEXT;RETURN;ELSIF event_row.phase='issueDispatched' THEN result_kind:='pending';operation_id:=generation_row.operation_id;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;RETURN;ELSIF event_row.phase='prepared' THEN result_kind:='claimed';operation_id:=generation_row.operation_id;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;RETURN;ELSIF event_row.phase='abandonedBeforeDispatch' AND generation_row.generation<2147483647 THEN successor:=gen_random_uuid();INSERT INTO public.rehearsal_delivery_operation_generation(tenant_id,rehearsal_run_id,root_id,generation,operation_id,selected_attempt_id,execution_descriptor,descriptor_digest,structural_binding) VALUES(p_tenant,route_row.rehearsal_run_id,root_row.root_id,generation_row.generation+1,successor,generation_row.selected_attempt_id,generation_row.execution_descriptor,generation_row.descriptor_digest,generation_row.structural_binding);INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase) VALUES(p_tenant,route_row.rehearsal_run_id,root_row.root_id,generation_row.generation+1,successor,1,'prepared');result_kind:='claimed';operation_id:=successor;execution_descriptor:=generation_row.execution_descriptor;RETURN NEXT;RETURN;ELSE result_kind:='conflict';RETURN NEXT;RETURN;END IF;END IF;IF EXISTS(SELECT 1 FROM public.rehearsal_delivery_retry_operation AS collision_map WHERE collision_map.tenant_id=p_tenant AND collision_map.rehearsal_run_id=route_row.rehearsal_run_id AND collision_map.idempotency_key=p_key) OR NOT EXISTS(SELECT 1 FROM public.rehearsal_run AS active_run WHERE active_run.tenant_id=p_tenant AND active_run.rehearsal_run_id=route_row.rehearsal_run_id AND active_run.lifecycle='active') THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;IF current_row.current_root_id IS NULL THEN witness:=jsonb_build_object('rehearsalRunId',route_row.rehearsal_run_id,'rehearsalReference',p_rehearsal_reference,'assignmentReference',p_assignment_reference,'revision',p_revision);witness_digest:=digest(convert_to(witness::text,'UTF8'),'sha256');INSERT INTO public.rehearsal_delivery_admission(tenant_id,rehearsal_run_id,idempotency_key,request_fingerprint,prepare_nonce,admission_witness,admission_digest,prepared_txid) VALUES(p_tenant,route_row.rehearsal_run_id,p_key,p_fingerprint,nonce,witness,witness_digest,txid_current());result_kind:='admit';prepare_nonce:=nonce;admission_witness:=witness;admission_digest:=witness_digest;RETURN NEXT;RETURN;END IF;SELECT count(*) INTO retry_count FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation ORDER BY retry_row.idempotency_key FOR UPDATE;IF current_row.current_phase='runTimeExhaustedBeforeDispatch' THEN observed_millis:=public.ple_rehearsal_now_millis();SELECT witness_row.* INTO expected_row FROM public.ple_expected_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,observed_millis) AS witness_row;IF NOT FOUND OR NOT expected_row.expected_run_time_exhausted OR current_row.current_deadline_millis IS DISTINCT FROM expected_row.expected_deadline_at_millis THEN RAISE EXCEPTION 'invalid rehearsal hard terminal' USING ERRCODE='23514';END IF;result_kind:='runTimeExhausted';deadline_at_millis:=expected_row.expected_deadline_at_millis;RETURN NEXT;RETURN;ELSIF current_row.current_phase='expired' THEN IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation) THEN RAISE EXCEPTION 'invalid rehearsal expiry witness' USING ERRCODE='23514';END IF;SELECT witness_row.* INTO timing_row FROM public.rehearsal_delivery_timing_witness AS witness_row WHERE witness_row.tenant_id=p_tenant AND witness_row.rehearsal_run_id=route_row.rehearsal_run_id AND witness_row.root_id=current_row.current_root_id AND witness_row.generation=current_row.current_generation;deadline_at_millis:=(extract(epoch FROM timing_row.deadline_at)*1000)::bigint;result_kind:=CASE WHEN timing_row.deadline_source='perQuestion' THEN 'expired' ELSE 'runTimeExhausted' END;RETURN NEXT;RETURN;END IF;IF retry_count>0 THEN result_kind:='conflict';RETURN NEXT;RETURN;END IF;IF current_row.current_phase IN('issueDispatched','completed') AND NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation) THEN RAISE EXCEPTION 'invalid rehearsal timing witness' USING ERRCODE='23514';END IF;IF current_row.current_phase='completed' THEN result_kind:='replay';screen_projection:=current_row.current_screen;screen_digest:=current_row.current_screen_digest;ELSIF current_row.current_phase='issueDispatched' THEN result_kind:='pending';operation_id:=current_row.current_operation_id;execution_descriptor:=current_row.current_descriptor;ELSIF current_row.current_phase='prepared' THEN result_kind:='claimed';operation_id:=current_row.current_operation_id;execution_descriptor:=current_row.current_descriptor;ELSE result_kind:='conflict';END IF;RETURN NEXT;END $$;
DROP FUNCTION public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,bytea,text,jsonb); CREATE FUNCTION public.ple_prepare_rehearsal_route_submission(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_public_token text,p_key text,p_response jsonb) RETURNS TABLE(decision text,attempt_id uuid,outcome_projection jsonb,receipt_digest bytea,screen_projection jsonb,screen_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;existing_row record;claim_event public.rehearsal_submission_claim_event%ROWTYPE;completed_receipt public.rehearsal_submission_receipt%ROWTYPE;timing_row record;current_row record;delivery_receipt public.rehearsal_delivery_receipt%ROWTYPE;
BEGIN SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR p_public_token IS NULL OR char_length(p_public_token) NOT BETWEEN 1 AND 64 OR p_public_token~'[[:cntrl:]]' OR p_key IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' OR jsonb_typeof(p_response)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_response)>393216 THEN RETURN;END IF;SELECT claim_root.claim_id,claim_root.attempt_id,claim_root.submission_input,delivery_binding.issued_screen_digest INTO existing_row FROM public.rehearsal_submission_claim_root AS claim_root LEFT JOIN public.rehearsal_submission_claim_delivery_binding AS delivery_binding ON delivery_binding.tenant_id=claim_root.tenant_id AND delivery_binding.rehearsal_run_id=claim_root.rehearsal_run_id AND delivery_binding.claim_id=claim_root.claim_id WHERE claim_root.tenant_id=p_tenant AND claim_root.rehearsal_run_id=route_row.rehearsal_run_id AND claim_root.idempotency_key=p_key;IF FOUND THEN IF existing_row.submission_input#>'{kind,response}' IS DISTINCT FROM p_response THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;RETURN;END IF;SELECT receipt_row.* INTO delivery_receipt FROM public.rehearsal_delivery_operation_generation AS generation_row JOIN public.rehearsal_delivery_receipt AS receipt_row ON receipt_row.tenant_id=generation_row.tenant_id AND receipt_row.rehearsal_run_id=generation_row.rehearsal_run_id AND receipt_row.root_id=generation_row.root_id AND receipt_row.generation=generation_row.generation AND receipt_row.operation_id=generation_row.operation_id WHERE generation_row.tenant_id=p_tenant AND generation_row.rehearsal_run_id=route_row.rehearsal_run_id AND generation_row.selected_attempt_id=existing_row.attempt_id AND receipt_row.result_kind='issued' AND receipt_row.frozen_attempt_id=existing_row.attempt_id AND receipt_row.screen_digest=existing_row.issued_screen_digest ORDER BY generation_row.generation DESC LIMIT 1;IF NOT FOUND OR delivery_receipt.screen_projection->>'presentationDigest' IS DISTINCT FROM p_public_token THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;RETURN;END IF;SELECT claim_event_row.* INTO claim_event FROM public.rehearsal_submission_claim_event AS claim_event_row WHERE claim_event_row.tenant_id=p_tenant AND claim_event_row.rehearsal_run_id=route_row.rehearsal_run_id AND claim_event_row.claim_id=existing_row.claim_id ORDER BY claim_event_row.sequence DESC LIMIT 1;IF NOT FOUND THEN RETURN;ELSIF claim_event.phase='completed' THEN SELECT receipt_row.* INTO completed_receipt FROM public.rehearsal_submission_receipt AS receipt_row WHERE receipt_row.tenant_id=p_tenant AND receipt_row.rehearsal_run_id=route_row.rehearsal_run_id AND receipt_row.claim_id=existing_row.claim_id AND receipt_row.receipt_digest=claim_event.receipt_digest;IF NOT FOUND THEN RETURN QUERY SELECT 'invalid'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;ELSE RETURN QUERY SELECT 'replay'::text,NULL::uuid,completed_receipt.outcome_projection,completed_receipt.receipt_digest,delivery_receipt.screen_projection,delivery_receipt.screen_digest;END IF;RETURN;ELSIF claim_event.phase IN('prepared','gradingDispatched') THEN RETURN QUERY SELECT 'pending'::text,NULL::uuid,NULL::jsonb,NULL::bytea,delivery_receipt.screen_projection,delivery_receipt.screen_digest;RETURN;ELSE RETURN QUERY SELECT 'reclaim'::text,existing_row.attempt_id,NULL::jsonb,NULL::bytea,delivery_receipt.screen_projection,delivery_receipt.screen_digest;RETURN;END IF;END IF;SELECT timing_result.* INTO timing_row FROM public.ple_reconcile_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS timing_result;IF NOT FOUND OR timing_row.verdict='expired' THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND OR current_row.current_phase<>'completed' THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;RETURN;END IF;SELECT receipt_row.* INTO delivery_receipt FROM public.rehearsal_delivery_receipt AS receipt_row WHERE receipt_row.tenant_id=p_tenant AND receipt_row.rehearsal_run_id=route_row.rehearsal_run_id AND receipt_row.root_id=current_row.current_root_id AND receipt_row.generation=current_row.current_generation;IF NOT FOUND OR delivery_receipt.operation_id IS DISTINCT FROM current_row.current_operation_id OR delivery_receipt.result_kind<>'issued' OR delivery_receipt.frozen_attempt_id IS DISTINCT FROM current_row.selected_attempt_id OR delivery_receipt.screen_digest IS DISTINCT FROM current_row.current_screen_digest OR delivery_receipt.screen_projection->>'presentationDigest' IS DISTINCT FROM p_public_token THEN RETURN QUERY SELECT 'conflict'::text,NULL::uuid,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea;RETURN;END IF;RETURN QUERY SELECT 'new'::text,current_row.selected_attempt_id,NULL::jsonb,NULL::bytea,delivery_receipt.screen_projection,delivery_receipt.screen_digest;END $$;
DROP FUNCTION public.ple_rehearsal_complete_delivery(uuid,uuid,uuid,integer,bigint,bigint,uuid,text,uuid,jsonb,bytea); CREATE FUNCTION public.ple_rehearsal_complete_delivery(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_operation uuid,p_screen jsonb,p_screen_digest bytea) RETURNS TABLE(screen_projection jsonb,screen_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;current_row record;BEGIN SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR p_operation IS NULL OR jsonb_typeof(p_screen)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_screen)>262144 OR octet_length(p_screen_digest)<>32 THEN RETURN;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND OR current_row.current_operation_id IS DISTINCT FROM p_operation OR current_row.current_phase<>'issueDispatched' THEN RETURN;END IF;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation ORDER BY retry_row.idempotency_key FOR UPDATE;IF NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation) THEN RAISE EXCEPTION 'invalid rehearsal timing witness at screen completion' USING ERRCODE='23514';END IF;INSERT INTO public.rehearsal_delivery_receipt(tenant_id,rehearsal_run_id,root_id,generation,operation_id,result_kind,frozen_attempt_id,screen_projection,screen_digest) VALUES(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,p_operation,'issued',current_row.selected_attempt_id,p_screen,p_screen_digest);INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase,completion_kind,frozen_attempt_id,screen_digest) VALUES(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,p_operation,current_row.current_sequence+1,'completed','issued',current_row.selected_attempt_id,p_screen_digest);RETURN QUERY SELECT p_screen,p_screen_digest;EXCEPTION WHEN unique_violation THEN RETURN;END $$;
CREATE FUNCTION public.ple_broker_cas_rehearsal_evidence_head(p_tenant uuid,p_run uuid,p_old_digest bytea,p_old_length bigint,p_new_digest bytea) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR octet_length(p_old_digest)<>32 OR p_old_length NOT BETWEEN 0 AND 4294967295 OR octet_length(p_new_digest)<>32 THEN RETURN false;END IF;UPDATE public.rehearsal_run SET evidence_head_digest=p_new_digest,evidence_length=p_old_length+1,updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active' AND evidence_head_digest=p_old_digest AND evidence_length=p_old_length;RETURN FOUND;END $$; CREATE FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(p_tenant uuid,p_run uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE expected_count integer;completed_count integer;BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() THEN RETURN false;END IF;SELECT expected_item_count INTO expected_count FROM public.rehearsal_frozen_material_set WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;SELECT count(*) INTO completed_count FROM public.rehearsal_accepted_attempt_integrity WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;IF expected_count IS NULL OR completed_count<>expected_count OR EXISTS(SELECT 1 FROM public.rehearsal_frozen_source_snapshot snapshot_row WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=p_run AND NOT EXISTS(SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted_row WHERE accepted_row.tenant_id=snapshot_row.tenant_id AND accepted_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND accepted_row.attempt_id=snapshot_row.attempt_id)) THEN RETURN false;END IF;UPDATE public.rehearsal_run SET lifecycle='completed',terminal_at=public.ple_rehearsal_now(),updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active';RETURN FOUND;END $$; ALTER FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea) OWNER TO ple_rehearsal_broker; ALTER FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) OWNER TO ple_rehearsal_broker; REVOKE ALL ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) TO ple_rehearsal_source; DROP FUNCTION public.ple_rehearsal_mark_delivery_dispatched(uuid,uuid,uuid,integer,bigint,bigint,uuid); CREATE OR REPLACE FUNCTION public.ple_rehearsal_abandon_delivery_before_dispatch(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_operation uuid,p_reason text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;current_row record;BEGIN SELECT prepared_route.* INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference) AS prepared_route;IF NOT FOUND OR p_operation IS NULL OR p_reason NOT IN('localPreparationFailed','nativeBackendAdmissionRejected','trustedRendererAdmissionRejected') THEN RETURN false;END IF;SELECT delivery_row.* INTO current_row FROM public.ple_current_rehearsal_delivery(p_tenant,route_row.rehearsal_run_id) AS delivery_row;IF NOT FOUND OR current_row.current_operation_id IS DISTINCT FROM p_operation OR current_row.current_phase<>'prepared' THEN RETURN false;END IF;PERFORM retry_row.idempotency_key FROM public.rehearsal_delivery_retry_operation AS retry_row WHERE retry_row.tenant_id=p_tenant AND retry_row.rehearsal_run_id=route_row.rehearsal_run_id AND retry_row.root_id=current_row.current_root_id AND retry_row.generation=current_row.current_generation ORDER BY retry_row.idempotency_key FOR UPDATE;INSERT INTO public.rehearsal_delivery_operation_event(tenant_id,rehearsal_run_id,root_id,generation,operation_id,sequence,phase,abandonment_reason) VALUES(p_tenant,route_row.rehearsal_run_id,current_row.current_root_id,current_row.current_generation,p_operation,current_row.current_sequence+1,'abandonedBeforeDispatch',p_reason);RETURN true;EXCEPTION WHEN unique_violation THEN RETURN false;END $$;
CREATE TRIGGER rehearsal_issued_execution_artifact_append_only BEFORE UPDATE OR DELETE ON public.rehearsal_delivery_issued_execution_artifact FOR EACH ROW EXECUTE FUNCTION public.ple_rehearsal_material_append_only(); ALTER TABLE public.rehearsal_delivery_issued_execution_artifact ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rehearsal_delivery_issued_execution_artifact FORCE ROW LEVEL SECURITY; CREATE POLICY rehearsal_issued_execution_artifact_source ON public.rehearsal_delivery_issued_execution_artifact TO ple_rehearsal_source USING(tenant_id=public.ple_current_tenant()) WITH CHECK(tenant_id=public.ple_current_tenant()); REVOKE ALL ON public.rehearsal_delivery_issued_execution_artifact FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT SELECT,INSERT ON public.rehearsal_delivery_issued_execution_artifact TO ple_rehearsal_source; CREATE FUNCTION public.ple_verify_rehearsal_issued_execution_artifact(p_tenant uuid,p_run uuid,p_root uuid,p_generation integer,p_operation uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.rehearsal_delivery_issued_execution_artifact artifact JOIN public.rehearsal_delivery_generation_material_binding binding ON binding.tenant_id=artifact.tenant_id AND binding.rehearsal_run_id=artifact.rehearsal_run_id AND binding.root_id=artifact.root_id AND binding.generation=artifact.generation AND binding.operation_id=artifact.operation_id JOIN public.rehearsal_delivery_operation_generation generation_row ON generation_row.tenant_id=artifact.tenant_id AND generation_row.rehearsal_run_id=artifact.rehearsal_run_id AND generation_row.root_id=artifact.root_id AND generation_row.generation=artifact.generation AND generation_row.operation_id=artifact.operation_id WHERE artifact.tenant_id=p_tenant AND artifact.rehearsal_run_id=p_run AND artifact.root_id=p_root AND artifact.generation=p_generation AND artifact.operation_id=p_operation AND artifact.attempt_id=binding.attempt_id AND artifact.attempt_id=generation_row.selected_attempt_id AND artifact.material_set_digest=binding.material_set_digest AND artifact.issued_snapshot_sha256=binding.issued_snapshot_sha256 AND artifact.private_execution_sha256=binding.private_execution_sha256 AND digest(artifact.artifact_bytes,'sha256')=artifact.artifact_sha256) $$; CREATE FUNCTION public.ple_prepare_or_resume_rehearsal_issued_execution(p_tenant uuid,p_operation uuid) RETURNS TABLE(result_kind text,issued_operation_id uuid,issued_snapshot_bytes bytea,issued_snapshot_sha256 bytea,private_execution_bytes bytea,private_execution_sha256 bytea,artifact_bytes bytea,artifact_sha256 bytea,material_set_digest bytea,execution_descriptor jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE binding_row public.rehearsal_delivery_generation_material_binding%ROWTYPE;generation_row public.rehearsal_delivery_operation_generation%ROWTYPE;event_row public.rehearsal_delivery_operation_event%ROWTYPE;artifact_row public.rehearsal_delivery_issued_execution_artifact%ROWTYPE;BEGIN SELECT * INTO binding_row FROM public.rehearsal_delivery_generation_material_binding WHERE tenant_id=p_tenant AND operation_id=p_operation FOR UPDATE;IF NOT FOUND THEN RETURN;END IF;SELECT * INTO generation_row FROM public.rehearsal_delivery_operation_generation WHERE tenant_id=binding_row.tenant_id AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation AND operation_id=p_operation FOR UPDATE;SELECT * INTO event_row FROM public.rehearsal_delivery_operation_event WHERE tenant_id=binding_row.tenant_id AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation ORDER BY sequence DESC LIMIT 1 FOR UPDATE;IF generation_row.operation_id IS NULL OR event_row.phase NOT IN('issueDispatched','completed') OR NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,binding_row.rehearsal_run_id,binding_row.root_id,binding_row.generation) THEN RETURN;END IF;SELECT * INTO artifact_row FROM public.rehearsal_delivery_issued_execution_artifact WHERE tenant_id=binding_row.tenant_id AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation;IF FOUND THEN IF NOT public.ple_verify_rehearsal_issued_execution_artifact(p_tenant,binding_row.rehearsal_run_id,binding_row.root_id,binding_row.generation,p_operation) THEN RAISE EXCEPTION 'invalid rehearsal issued execution artifact' USING ERRCODE='23514';END IF;RETURN QUERY SELECT 'existing'::text,binding_row.operation_id,snapshot_row.issued_snapshot_bytes,snapshot_row.issued_snapshot_sha256,private_row.private_execution_bytes,private_row.private_execution_sha256,artifact_row.artifact_bytes,artifact_row.artifact_sha256,artifact_row.material_set_digest,generation_row.execution_descriptor FROM public.rehearsal_frozen_source_snapshot snapshot_row JOIN public.rehearsal_frozen_private_execution private_row ON private_row.tenant_id=snapshot_row.tenant_id AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND private_row.attempt_id=snapshot_row.attempt_id WHERE snapshot_row.tenant_id=binding_row.tenant_id AND snapshot_row.rehearsal_run_id=binding_row.rehearsal_run_id AND snapshot_row.attempt_id=binding_row.attempt_id AND snapshot_row.issued_snapshot_sha256=binding_row.issued_snapshot_sha256 AND private_row.private_execution_sha256=binding_row.private_execution_sha256;RETURN;END IF;RETURN QUERY SELECT 'work'::text,binding_row.operation_id,snapshot_row.issued_snapshot_bytes,snapshot_row.issued_snapshot_sha256,private_row.private_execution_bytes,private_row.private_execution_sha256,NULL::bytea,NULL::bytea,binding_row.material_set_digest,generation_row.execution_descriptor FROM public.rehearsal_frozen_source_snapshot snapshot_row JOIN public.rehearsal_frozen_private_execution private_row ON private_row.tenant_id=snapshot_row.tenant_id AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND private_row.attempt_id=snapshot_row.attempt_id WHERE snapshot_row.tenant_id=binding_row.tenant_id AND snapshot_row.rehearsal_run_id=binding_row.rehearsal_run_id AND snapshot_row.attempt_id=binding_row.attempt_id AND snapshot_row.issued_snapshot_sha256=binding_row.issued_snapshot_sha256 AND private_row.private_execution_sha256=binding_row.private_execution_sha256;END $$; ALTER FUNCTION public.ple_expected_rehearsal_timing_witness(uuid,uuid,uuid,integer,bigint) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_verify_persisted_rehearsal_timing_witness(uuid,uuid,uuid,integer) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_complete_delivery(uuid,uuid,uuid,integer,bigint,bigint,uuid,jsonb,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_verify_rehearsal_issued_execution_artifact(uuid,uuid,uuid,integer,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_current_rehearsal_delivery(uuid,uuid),public.ple_expected_rehearsal_timing_witness(uuid,uuid,uuid,integer,bigint),public.ple_verify_persisted_rehearsal_timing_witness(uuid,uuid,uuid,integer),public.ple_reconcile_current_rehearsal_delivery(uuid,uuid),public.ple_copy_rehearsal_generation_material_binding(),public.ple_verify_rehearsal_issued_execution_artifact(uuid,uuid,uuid,integer,uuid),public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; REVOKE ALL ON FUNCTION public.ple_prepare_rehearsal_timing_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_finalize_rehearsal_timing_dispatch(uuid,uuid,bigint,bigint,bigint,bigint,text,bytea,bytea),public.ple_finalize_rehearsal_timing_exhausted(uuid,uuid),public.ple_reconcile_rehearsal_delivery_expiry(uuid,uuid,uuid,integer,bigint,bigint),public.ple_prepare_rehearsal_delivery_retry(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,text,text,jsonb),public.ple_rehearsal_abandon_delivery_before_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid,text) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_prepare_rehearsal_timing_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_finalize_rehearsal_timing_dispatch(uuid,uuid,bigint,bigint,bigint,bigint,text,bytea,bytea),public.ple_finalize_rehearsal_timing_exhausted(uuid,uuid),public.ple_reconcile_rehearsal_delivery_expiry(uuid,uuid,uuid,integer,bigint,bigint),public.ple_prepare_rehearsal_delivery_retry(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,text,text,jsonb),public.ple_rehearsal_abandon_delivery_before_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid,text) TO ple_app; GRANT EXECUTE ON FUNCTION public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) TO ple_grading_reader; ALTER FUNCTION public.ple_current_rehearsal_delivery(uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_reconcile_current_rehearsal_delivery(uuid,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_copy_rehearsal_generation_material_binding() OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_complete_delivery(uuid,uuid,uuid,integer,bigint,bigint,uuid,jsonb,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_verify_rehearsal_issued_execution_artifact(uuid,uuid,uuid,integer,uuid) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_current_rehearsal_delivery(uuid,uuid),public.ple_expected_rehearsal_timing_witness(uuid,uuid,uuid,integer,bigint),public.ple_verify_persisted_rehearsal_timing_witness(uuid,uuid,uuid,integer),public.ple_reconcile_current_rehearsal_delivery(uuid,uuid),public.ple_copy_rehearsal_generation_material_binding(),public.ple_verify_rehearsal_issued_execution_artifact(uuid,uuid,uuid,integer,uuid),public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; REVOKE ALL ON FUNCTION public.ple_prepare_rehearsal_timing_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_finalize_rehearsal_timing_dispatch(uuid,uuid,bigint,bigint,bigint,bigint,text,bytea,bytea),public.ple_finalize_rehearsal_timing_exhausted(uuid,uuid),public.ple_reconcile_rehearsal_delivery_expiry(uuid,uuid,uuid,integer,bigint,bigint),public.ple_prepare_rehearsal_delivery_retry(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,text,text,jsonb),public.ple_rehearsal_abandon_delivery_before_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid,text) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_prepare_rehearsal_timing_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid),public.ple_finalize_rehearsal_timing_dispatch(uuid,uuid,bigint,bigint,bigint,bigint,text,bytea,bytea),public.ple_finalize_rehearsal_timing_exhausted(uuid,uuid),public.ple_reconcile_rehearsal_delivery_expiry(uuid,uuid,uuid,integer,bigint,bigint),public.ple_prepare_rehearsal_delivery_retry(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_delivery(uuid,uuid,uuid,integer,bigint,bigint,text,bytea),public.ple_prepare_rehearsal_route_submission(uuid,uuid,uuid,integer,bigint,bigint,text,text,jsonb),public.ple_rehearsal_abandon_delivery_before_dispatch(uuid,uuid,uuid,integer,bigint,bigint,uuid,text) TO ple_app; GRANT EXECUTE ON FUNCTION public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid) TO ple_grading_reader; CREATE FUNCTION public.ple_commit_sealed_rehearsal_issued_execution(p_tenant uuid,p_operation uuid,p_artifact bytea,p_artifact_sha256 bytea) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE binding_row public.rehearsal_delivery_generation_material_binding%ROWTYPE;generation_row public.rehearsal_delivery_operation_generation%ROWTYPE;event_row public.rehearsal_delivery_operation_event%ROWTYPE;artifact_row public.rehearsal_delivery_issued_execution_artifact%ROWTYPE;BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_operation IS NULL OR octet_length(p_artifact) NOT BETWEEN 2 AND 524288 OR octet_length(p_artifact_sha256)<>32 OR digest(p_artifact,'sha256')<>p_artifact_sha256 THEN RETURN 'conflict';END IF;SELECT * INTO binding_row FROM public.rehearsal_delivery_generation_material_binding WHERE tenant_id=p_tenant AND operation_id=p_operation FOR UPDATE;IF NOT FOUND THEN RETURN 'conflict';END IF;SELECT * INTO generation_row FROM public.rehearsal_delivery_operation_generation WHERE tenant_id=binding_row.tenant_id AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation AND operation_id=p_operation FOR UPDATE;SELECT * INTO event_row FROM public.rehearsal_delivery_operation_event WHERE tenant_id=binding_row.tenant_id AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation ORDER BY sequence DESC LIMIT 1 FOR UPDATE;IF generation_row.operation_id IS NULL OR generation_row.selected_attempt_id IS DISTINCT FROM binding_row.attempt_id OR event_row.phase NOT IN('issueDispatched','completed') OR NOT public.ple_verify_persisted_rehearsal_timing_witness(p_tenant,binding_row.rehearsal_run_id,binding_row.root_id,binding_row.generation) THEN RETURN 'conflict';END IF;SELECT * INTO artifact_row FROM public.rehearsal_delivery_issued_execution_artifact WHERE tenant_id=p_tenant AND rehearsal_run_id=binding_row.rehearsal_run_id AND root_id=binding_row.root_id AND generation=binding_row.generation;IF FOUND THEN RETURN CASE WHEN public.ple_verify_rehearsal_issued_execution_artifact(p_tenant,binding_row.rehearsal_run_id,binding_row.root_id,binding_row.generation,p_operation) AND artifact_row.artifact_bytes=p_artifact AND artifact_row.artifact_sha256=p_artifact_sha256 THEN 'replay' ELSE 'conflict' END;END IF;INSERT INTO public.rehearsal_delivery_issued_execution_artifact(tenant_id,rehearsal_run_id,root_id,generation,operation_id,attempt_id,material_set_digest,issued_snapshot_sha256,private_execution_sha256,artifact_bytes,artifact_sha256) VALUES(p_tenant,binding_row.rehearsal_run_id,binding_row.root_id,binding_row.generation,p_operation,binding_row.attempt_id,binding_row.material_set_digest,binding_row.issued_snapshot_sha256,binding_row.private_execution_sha256,p_artifact,p_artifact_sha256);RETURN 'committed';END $$; ALTER FUNCTION public.ple_commit_sealed_rehearsal_issued_execution(uuid,uuid,bytea,bytea) OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_commit_sealed_rehearsal_issued_execution(uuid,uuid,bytea,bytea) FROM PUBLIC,ple_app,ple_student,ple_grader; GRANT EXECUTE ON FUNCTION public.ple_commit_sealed_rehearsal_issued_execution(uuid,uuid,bytea,bytea) TO ple_grading_reader; ALTER TABLE public.rehearsal_submission_claim_delivery_binding ADD COLUMN binding_digest bytea; CREATE FUNCTION public.ple_rehearsal_claim_delivery_binding_digest(p_tenant uuid,p_run uuid,p_claim uuid,p_fingerprint bytea,p_attempt uuid,p_root uuid,p_generation integer,p_operation uuid,p_screen bytea) RETURNS bytea LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path TO pg_catalog,public,pg_temp AS $$ SELECT digest(convert_to('ple.rehearsal.claim-delivery-binding.v1'||chr(0),'UTF8')||uuid_send(p_tenant)||uuid_send(p_run)||uuid_send(p_claim)||p_fingerprint||uuid_send(p_attempt)||uuid_send(p_root)||int4send(p_generation)||uuid_send(p_operation)||p_screen,'sha256') $$; CREATE OR REPLACE FUNCTION public.ple_rehearsal_route_create_claim(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment uuid,p_revision bigint,p_run uuid,p_claim uuid,p_operation uuid,p_key text,p_presentation_digest bytea,p_fingerprint bytea,p_request jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE w record;d record;n integer;BEGIN SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,(SELECT public_id FROM public.assignment WHERE tenant_id=p_tenant AND course_id=p_course AND assignment_id=p_assignment),p_revision,(SELECT rehearsal_reference FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run));IF NOT FOUND OR w.rehearsal_run_id IS DISTINCT FROM p_run OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_claim IS NULL OR p_operation IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' OR octet_length(p_presentation_digest)<>32 OR octet_length(p_fingerprint)<>32 OR jsonb_typeof(p_request)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_request)>393728 OR NOT public.ple_verify_rehearsal_frozen_material_set(p_tenant,p_run) THEN RETURN false;END IF;SELECT count(*),min(root.selected_attempt_id) INTO n,d FROM public.rehearsal_delivery_operation_root root JOIN LATERAL(SELECT * FROM public.rehearsal_delivery_operation_generation g WHERE g.tenant_id=root.tenant_id AND g.rehearsal_run_id=root.rehearsal_run_id AND g.root_id=root.root_id ORDER BY g.generation DESC LIMIT 1) g ON true JOIN LATERAL(SELECT * FROM public.rehearsal_delivery_operation_event e WHERE e.tenant_id=g.tenant_id AND e.rehearsal_run_id=g.rehearsal_run_id AND e.root_id=g.root_id AND e.generation=g.generation ORDER BY e.sequence DESC LIMIT 1) e ON true JOIN public.rehearsal_delivery_receipt r ON r.tenant_id=g.tenant_id AND r.rehearsal_run_id=g.rehearsal_run_id AND r.root_id=g.root_id AND r.generation=g.generation AND r.operation_id=g.operation_id JOIN public.rehearsal_delivery_issued_execution_artifact a ON a.tenant_id=g.tenant_id AND a.rehearsal_run_id=g.rehearsal_run_id AND a.root_id=g.root_id AND a.generation=g.generation AND a.operation_id=g.operation_id WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=p_run AND e.phase='completed' AND e.completion_kind='issued' AND r.result_kind='issued' AND r.frozen_attempt_id=root.selected_attempt_id AND r.screen_digest=p_presentation_digest AND NOT EXISTS(SELECT 1 FROM public.rehearsal_accepted_attempt_integrity x WHERE x.tenant_id=root.tenant_id AND x.rehearsal_run_id=root.rehearsal_run_id AND x.attempt_id=root.selected_attempt_id);IF n<>1 THEN RETURN false;END IF;SELECT root.selected_attempt_id,g.root_id,g.generation,g.operation_id,r.screen_digest INTO d FROM public.rehearsal_delivery_operation_root root JOIN LATERAL(SELECT * FROM public.rehearsal_delivery_operation_generation g WHERE g.tenant_id=root.tenant_id AND g.rehearsal_run_id=root.rehearsal_run_id AND g.root_id=root.root_id ORDER BY g.generation DESC LIMIT 1) g ON true JOIN public.rehearsal_delivery_receipt r ON r.tenant_id=g.tenant_id AND r.rehearsal_run_id=g.rehearsal_run_id AND r.root_id=g.root_id AND r.generation=g.generation AND r.operation_id=g.operation_id WHERE root.tenant_id=p_tenant AND root.rehearsal_run_id=p_run AND root.selected_attempt_id=d.min AND r.screen_digest=p_presentation_digest;INSERT INTO public.rehearsal_submission_claim_root(tenant_id,rehearsal_run_id,claim_id,idempotency_key,attempt_id,request_fingerprint,submission_input) VALUES(p_tenant,p_run,p_claim,p_key,d.selected_attempt_id,p_fingerprint,p_request);INSERT INTO public.rehearsal_submission_claim_delivery_binding(tenant_id,rehearsal_run_id,claim_id,delivery_root_id,delivery_generation,delivery_operation_id,issued_screen_digest,binding_digest) VALUES(p_tenant,p_run,p_claim,d.root_id,d.generation,d.operation_id,d.screen_digest,public.ple_rehearsal_claim_delivery_binding_digest(p_tenant,p_run,p_claim,p_fingerprint,d.selected_attempt_id,d.root_id,d.generation,d.operation_id,d.screen_digest));INSERT INTO public.rehearsal_submission_claim_event(tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase) VALUES(p_tenant,p_run,p_claim,1,p_operation,1,'prepared');RETURN true;EXCEPTION WHEN unique_violation THEN RETURN false;END $$; ALTER TABLE public.rehearsal_submission_claim_delivery_binding ALTER COLUMN binding_digest SET NOT NULL; ALTER TABLE public.rehearsal_submission_claim_delivery_binding ADD CONSTRAINT rehearsal_claim_delivery_binding_checksum CHECK(octet_length(binding_digest)=32); CREATE FUNCTION public.ple_rehearsal_route_dispatch_claim(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE w record;c record;e record;BEGIN SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);IF NOT FOUND OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' THEN RETURN 'notFound';END IF;SELECT claim.*,binding.delivery_root_id,binding.delivery_generation,binding.delivery_operation_id,binding.issued_screen_digest,binding.binding_digest INTO c FROM public.rehearsal_submission_claim_root claim JOIN public.rehearsal_submission_claim_delivery_binding binding ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id AND binding.claim_id=claim.claim_id WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=w.rehearsal_run_id AND claim.idempotency_key=p_key FOR UPDATE;IF NOT FOUND OR c.binding_digest<>public.ple_rehearsal_claim_delivery_binding_digest(p_tenant,w.rehearsal_run_id,c.claim_id,c.request_fingerprint,c.attempt_id,c.delivery_root_id,c.delivery_generation,c.delivery_operation_id,c.issued_screen_digest) OR NOT EXISTS(SELECT 1 FROM public.rehearsal_delivery_receipt r JOIN public.rehearsal_delivery_issued_execution_artifact a ON a.tenant_id=r.tenant_id AND a.rehearsal_run_id=r.rehearsal_run_id AND a.root_id=r.root_id AND a.generation=r.generation AND a.operation_id=r.operation_id WHERE r.tenant_id=p_tenant AND r.rehearsal_run_id=w.rehearsal_run_id AND r.root_id=c.delivery_root_id AND r.generation=c.delivery_generation AND r.operation_id=c.delivery_operation_id AND r.result_kind='issued' AND r.frozen_attempt_id=c.attempt_id AND r.screen_digest=c.issued_screen_digest) THEN RETURN 'conflict';END IF;SELECT * INTO e FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id AND claim_id=c.claim_id ORDER BY sequence DESC LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RETURN 'conflict';ELSIF e.phase='gradingDispatched' THEN RETURN 'dispatched';ELSIF e.phase<>'prepared' OR e.operation_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id AND lifecycle='active') THEN RETURN 'terminal';END IF;INSERT INTO public.rehearsal_submission_claim_event(tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase) VALUES(p_tenant,w.rehearsal_run_id,c.claim_id,e.sequence+1,e.operation_id,e.generation,'gradingDispatched');RETURN 'dispatched';END $$; CREATE FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text) RETURNS TABLE(result_kind text,claim_id uuid,operation_id uuid,generation integer,submission_input jsonb,issued_snapshot_bytes bytea,issued_snapshot_sha256 bytea,private_execution_bytes bytea,private_execution_sha256 bytea,artifact_bytes bytea,artifact_sha256 bytea,execution_descriptor jsonb,outcome_projection jsonb,receipt_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE w record;c record;e record;BEGIN SELECT * INTO w FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);IF NOT FOUND OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' THEN RETURN;END IF;SELECT claim.*,binding.delivery_root_id,binding.delivery_generation,binding.delivery_operation_id,binding.issued_screen_digest,binding.binding_digest INTO c FROM public.rehearsal_submission_claim_root claim JOIN public.rehearsal_submission_claim_delivery_binding binding ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id AND binding.claim_id=claim.claim_id WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=w.rehearsal_run_id AND claim.idempotency_key=p_key;IF NOT FOUND OR c.binding_digest<>public.ple_rehearsal_claim_delivery_binding_digest(p_tenant,w.rehearsal_run_id,c.claim_id,c.request_fingerprint,c.attempt_id,c.delivery_root_id,c.delivery_generation,c.delivery_operation_id,c.issued_screen_digest) THEN RETURN;END IF;SELECT * INTO e FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=w.rehearsal_run_id AND claim_id=c.claim_id ORDER BY sequence DESC LIMIT 1;IF NOT FOUND THEN RETURN;ELSIF e.phase='prepared' THEN RETURN QUERY SELECT 'pending',c.claim_id,NULL::uuid,NULL::integer,NULL::jsonb,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::jsonb,NULL::jsonb,NULL::bytea;RETURN;ELSIF e.phase='completed' THEN RETURN QUERY SELECT 'receipt',c.claim_id,NULL::uuid,NULL::integer,NULL::jsonb,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::jsonb,r.outcome_projection,r.receipt_digest FROM public.rehearsal_submission_receipt r WHERE r.tenant_id=p_tenant AND r.rehearsal_run_id=w.rehearsal_run_id AND r.claim_id=c.claim_id AND r.receipt_digest=e.receipt_digest;RETURN;ELSIF e.phase<>'gradingDispatched' THEN RETURN;END IF;RETURN QUERY SELECT 'work',c.claim_id,e.operation_id,e.generation,c.submission_input,s.issued_snapshot_bytes,s.issued_snapshot_sha256,x.private_execution_bytes,x.private_execution_sha256,a.artifact_bytes,a.artifact_sha256,g.execution_descriptor,NULL::jsonb,NULL::bytea FROM public.rehearsal_delivery_operation_generation g JOIN public.rehearsal_frozen_source_snapshot s ON s.tenant_id=g.tenant_id AND s.rehearsal_run_id=g.rehearsal_run_id AND s.attempt_id=c.attempt_id JOIN public.rehearsal_frozen_private_execution x ON x.tenant_id=s.tenant_id AND x.rehearsal_run_id=s.rehearsal_run_id AND x.attempt_id=s.attempt_id AND x.issued_snapshot_sha256=s.issued_snapshot_sha256 JOIN public.rehearsal_delivery_issued_execution_artifact a ON a.tenant_id=g.tenant_id AND a.rehearsal_run_id=g.rehearsal_run_id AND a.root_id=g.root_id AND a.generation=g.generation AND a.operation_id=g.operation_id JOIN public.rehearsal_delivery_receipt r ON r.tenant_id=g.tenant_id AND r.rehearsal_run_id=g.rehearsal_run_id AND r.root_id=g.root_id AND r.generation=g.generation AND r.operation_id=g.operation_id WHERE g.tenant_id=p_tenant AND g.rehearsal_run_id=w.rehearsal_run_id AND g.root_id=c.delivery_root_id AND g.generation=c.delivery_generation AND g.operation_id=c.delivery_operation_id AND r.result_kind='issued' AND r.frozen_attempt_id=c.attempt_id AND r.screen_digest=c.issued_screen_digest AND a.attempt_id=c.attempt_id AND a.issued_snapshot_sha256=s.issued_snapshot_sha256 AND a.private_execution_sha256=x.private_execution_sha256 AND digest(a.artifact_bytes,'sha256')=a.artifact_sha256;END $$; ALTER FUNCTION public.ple_rehearsal_claim_delivery_binding_digest(uuid,uuid,uuid,bytea,uuid,uuid,integer,uuid,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_route_create_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,text,bytea,bytea,jsonb) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_rehearsal_route_dispatch_claim(uuid,uuid,uuid,integer,bigint,bigint,text) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea) OWNER TO ple_rehearsal_broker; ALTER FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) OWNER TO ple_rehearsal_broker; REVOKE ALL ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_rehearsal_claim_delivery_binding_digest(uuid,uuid,uuid,bytea,uuid,uuid,integer,uuid,bytea),public.ple_rehearsal_route_dispatch_claim(uuid,uuid,uuid,integer,bigint,bigint,text),public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text) FROM PUBLIC,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_rehearsal_route_dispatch_claim(uuid,uuid,uuid,integer,bigint,bigint,text) TO ple_app; GRANT EXECUTE ON FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text) TO ple_grading_reader; CREATE FUNCTION public.ple_require_rehearsal_issued_execution_artifact() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF TG_TABLE_NAME='rehearsal_delivery_receipt' THEN IF NOT public.ple_verify_rehearsal_issued_execution_artifact(NEW.tenant_id,NEW.rehearsal_run_id,NEW.root_id,NEW.generation,NEW.operation_id) THEN RAISE EXCEPTION 'rehearsal screen completion lacks a valid issued execution artifact' USING ERRCODE='23514';END IF;ELSIF TG_TABLE_NAME='rehearsal_submission_claim_delivery_binding' AND (NOT public.ple_verify_rehearsal_issued_execution_artifact(NEW.tenant_id,NEW.rehearsal_run_id,NEW.delivery_root_id,NEW.delivery_generation,NEW.delivery_operation_id) OR NEW.binding_digest<>public.ple_rehearsal_claim_delivery_binding_digest(NEW.tenant_id,NEW.rehearsal_run_id,NEW.claim_id,(SELECT request_fingerprint FROM public.rehearsal_submission_claim_root c WHERE c.tenant_id=NEW.tenant_id AND c.rehearsal_run_id=NEW.rehearsal_run_id AND c.claim_id=NEW.claim_id), (SELECT attempt_id FROM public.rehearsal_submission_claim_root c WHERE c.tenant_id=NEW.tenant_id AND c.rehearsal_run_id=NEW.rehearsal_run_id AND c.claim_id=NEW.claim_id),NEW.delivery_root_id,NEW.delivery_generation,NEW.delivery_operation_id,NEW.issued_screen_digest)) THEN RAISE EXCEPTION 'rehearsal submission binding is invalid' USING ERRCODE='23514';END IF;RETURN NEW;END $$; CREATE TRIGGER rehearsal_delivery_receipt_requires_issued_execution BEFORE INSERT ON public.rehearsal_delivery_receipt FOR EACH ROW EXECUTE FUNCTION public.ple_require_rehearsal_issued_execution_artifact(); CREATE TRIGGER rehearsal_submission_binding_requires_issued_execution BEFORE INSERT ON public.rehearsal_submission_claim_delivery_binding FOR EACH ROW EXECUTE FUNCTION public.ple_require_rehearsal_issued_execution_artifact(); ALTER FUNCTION public.ple_require_rehearsal_issued_execution_artifact() OWNER TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_rehearsal_route_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader;
DROP FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text); CREATE FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_key text) RETURNS TABLE(result_kind text,tenant_id uuid,course_id uuid,assignment_reference integer,assignment_revision bigint,direct_instructor_membership_id uuid,subject_fingerprint bytea,rehearsal_run_id uuid,claim_id uuid,request_fingerprint bytea,attempt_id uuid,delivery_operation_id uuid,claim_operation_id uuid,claim_generation integer,submission_input jsonb,issued_snapshot_bytes bytea,issued_snapshot_sha256 bytea,canonical_content_digest bytea,private_execution_bytes bytea,private_execution_sha256 bytea,artifact_bytes bytea,artifact_sha256 bytea,execution_descriptor jsonb,screen_projection jsonb,issued_screen_digest bytea,outcome_projection jsonb,receipt_digest bytea,evidence_head_digest bytea,evidence_length bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;claim_row record;event_row record;BEGIN SELECT * INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);IF NOT FOUND OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_key IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR p_key~'[[:cntrl:]]' THEN RETURN;END IF;SELECT claim.*,binding.delivery_root_id,binding.delivery_generation,binding.delivery_operation_id,binding.issued_screen_digest INTO claim_row FROM public.rehearsal_submission_claim_root claim JOIN public.rehearsal_submission_claim_delivery_binding binding ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id AND binding.claim_id=claim.claim_id WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=route_row.rehearsal_run_id AND claim.idempotency_key=p_key FOR UPDATE;IF NOT FOUND OR claim_row.submission_input->'kind'->>'kind' IS DISTINCT FROM 'rendered' OR NOT public.ple_verify_rehearsal_claim_delivery_binding(p_tenant,route_row.rehearsal_run_id,claim_row.claim_id) THEN RETURN;END IF;SELECT * INTO event_row FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=route_row.rehearsal_run_id AND claim_id=claim_row.claim_id ORDER BY sequence DESC LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RETURN;ELSIF event_row.phase='prepared' THEN RETURN QUERY SELECT 'pending',p_tenant,NULL::uuid,NULL::integer,NULL::bigint,NULL::uuid,NULL::bytea,route_row.rehearsal_run_id,claim_row.claim_id,NULL::bytea,NULL::uuid,NULL::uuid,NULL::uuid,NULL::integer,NULL::jsonb,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::jsonb,NULL::jsonb,NULL::bytea,NULL::jsonb,NULL::bytea,NULL::bytea,NULL::bigint;RETURN;ELSIF event_row.phase='completed' THEN RETURN QUERY SELECT 'receipt',p_tenant,NULL::uuid,NULL::integer,NULL::bigint,NULL::uuid,NULL::bytea,route_row.rehearsal_run_id,claim_row.claim_id,NULL::bytea,NULL::uuid,NULL::uuid,NULL::uuid,NULL::integer,NULL::jsonb,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::bytea,NULL::jsonb,NULL::jsonb,NULL::bytea,receipt.outcome_projection,receipt.receipt_digest,NULL::bytea,NULL::bigint FROM public.rehearsal_submission_receipt receipt WHERE receipt.tenant_id=p_tenant AND receipt.rehearsal_run_id=route_row.rehearsal_run_id AND receipt.claim_id=claim_row.claim_id AND receipt.receipt_digest=event_row.receipt_digest;RETURN;ELSIF event_row.phase<>'gradingDispatched' OR event_row.operation_id IS NULL OR event_row.generation NOT BETWEEN 1 AND 4294967295 THEN RETURN;END IF;RETURN QUERY SELECT 'work',run_row.tenant_id,run_row.course_id,run_row.assignment_reference,run_row.assignment_revision,run_row.direct_instructor_membership_id,run_row.subject_fingerprint,run_row.rehearsal_run_id,claim_row.claim_id,claim_row.request_fingerprint,claim_row.attempt_id,claim_row.delivery_operation_id,event_row.operation_id,event_row.generation,claim_row.submission_input,snapshot_row.issued_snapshot_bytes,snapshot_row.issued_snapshot_sha256,frozen_item.canonical_content_digest,private_row.private_execution_bytes,private_row.private_execution_sha256,artifact_row.artifact_bytes,artifact_row.artifact_sha256,generation_row.execution_descriptor,receipt_row.screen_projection,receipt_row.screen_digest,NULL::jsonb,NULL::bytea,run_row.evidence_head_digest,run_row.evidence_length FROM public.rehearsal_run run_row JOIN public.rehearsal_delivery_operation_generation generation_row ON generation_row.tenant_id=run_row.tenant_id AND generation_row.rehearsal_run_id=run_row.rehearsal_run_id AND generation_row.root_id=claim_row.delivery_root_id AND generation_row.generation=claim_row.delivery_generation AND generation_row.operation_id=claim_row.delivery_operation_id JOIN public.rehearsal_delivery_receipt receipt_row ON receipt_row.tenant_id=generation_row.tenant_id AND receipt_row.rehearsal_run_id=generation_row.rehearsal_run_id AND receipt_row.root_id=generation_row.root_id AND receipt_row.generation=generation_row.generation AND receipt_row.operation_id=generation_row.operation_id JOIN public.rehearsal_delivery_issued_execution_artifact artifact_row ON artifact_row.tenant_id=generation_row.tenant_id AND artifact_row.rehearsal_run_id=generation_row.rehearsal_run_id AND artifact_row.root_id=generation_row.root_id AND artifact_row.generation=generation_row.generation AND artifact_row.operation_id=generation_row.operation_id JOIN public.rehearsal_frozen_source_snapshot snapshot_row ON snapshot_row.tenant_id=run_row.tenant_id AND snapshot_row.rehearsal_run_id=run_row.rehearsal_run_id AND snapshot_row.attempt_id=claim_row.attempt_id JOIN public.rehearsal_frozen_private_execution private_row ON private_row.tenant_id=snapshot_row.tenant_id AND private_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND private_row.attempt_id=snapshot_row.attempt_id AND private_row.issued_snapshot_sha256=snapshot_row.issued_snapshot_sha256 JOIN public.rehearsal_frozen_item frozen_item ON frozen_item.tenant_id=snapshot_row.tenant_id AND frozen_item.rehearsal_run_id=snapshot_row.rehearsal_run_id AND frozen_item.attempt_id=snapshot_row.attempt_id WHERE run_row.tenant_id=p_tenant AND run_row.rehearsal_run_id=route_row.rehearsal_run_id AND run_row.lifecycle='active' AND receipt_row.result_kind='issued' AND receipt_row.frozen_attempt_id=claim_row.attempt_id AND receipt_row.screen_digest=claim_row.issued_screen_digest AND artifact_row.attempt_id=claim_row.attempt_id AND artifact_row.issued_snapshot_sha256=snapshot_row.issued_snapshot_sha256 AND artifact_row.private_execution_sha256=private_row.private_execution_sha256 AND digest(artifact_row.artifact_bytes,'sha256')=artifact_row.artifact_sha256;END $$; CREATE OR REPLACE FUNCTION public.ple_broker_cas_rehearsal_evidence_head(p_tenant uuid,p_run uuid,p_old_digest bytea,p_old_length bigint,p_new_digest bytea) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR octet_length(p_old_digest)<>32 OR p_old_length NOT BETWEEN 0 AND 4294967295 OR octet_length(p_new_digest)<>32 THEN RETURN false;END IF;UPDATE public.rehearsal_run SET evidence_head_digest=p_new_digest,evidence_length=p_old_length+1,updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active' AND evidence_head_digest=p_old_digest AND evidence_length=p_old_length;RETURN FOUND;END $$; CREATE OR REPLACE FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(p_tenant uuid,p_run uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE expected_count integer;completed_count integer;BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() THEN RETURN false;END IF;SELECT expected_item_count INTO expected_count FROM public.rehearsal_frozen_material_set WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;SELECT count(*) INTO completed_count FROM public.rehearsal_accepted_attempt_integrity WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;IF expected_count IS NULL OR completed_count<>expected_count OR EXISTS(SELECT 1 FROM public.rehearsal_frozen_source_snapshot snapshot_row WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=p_run AND NOT EXISTS(SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted_row WHERE accepted_row.tenant_id=snapshot_row.tenant_id AND accepted_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND accepted_row.attempt_id=snapshot_row.attempt_id)) THEN RETURN false;END IF;UPDATE public.rehearsal_run SET lifecycle='completed',terminal_at=public.ple_rehearsal_now(),updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active';RETURN FOUND;END $$; ALTER FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea) OWNER TO ple_rehearsal_broker; ALTER FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) OWNER TO ple_rehearsal_broker; REVOKE ALL ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) TO ple_rehearsal_source; CREATE FUNCTION public.ple_complete_sealed_rehearsal_submission(p_tenant uuid,p_actor uuid,p_course uuid,p_assignment_reference integer,p_revision bigint,p_rehearsal_reference bigint,p_claim uuid,p_claim_operation uuid,p_claim_generation integer,p_request_fingerprint bytea,p_screen_digest bytea,p_prior_head_digest bytea,p_prior_head_length bigint,p_entry_digest bytea,p_payload jsonb,p_payload_digest bytea,p_accepted_millis bigint,p_outcome jsonb,p_receipt_digest bytea) RETURNS TABLE(result_kind text,outcome_projection jsonb,receipt_digest bytea) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE route_row record;claim_row record;event_row record;run_row public.rehearsal_run%ROWTYPE;BEGIN SELECT * INTO route_row FROM public.ple_prepare_rehearsal_operation(p_tenant,p_actor,p_course,p_assignment_reference,p_revision,p_rehearsal_reference);IF NOT FOUND OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR p_claim IS NULL OR p_claim_operation IS NULL OR p_claim_generation NOT BETWEEN 1 AND 4294967295 OR octet_length(p_request_fingerprint)<>32 OR octet_length(p_screen_digest)<>32 OR octet_length(p_prior_head_digest)<>32 OR p_prior_head_length NOT BETWEEN 0 AND 4294967295 OR octet_length(p_entry_digest)<>32 OR jsonb_typeof(p_payload)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_payload)>395264 OR octet_length(p_payload_digest)<>32 OR p_accepted_millis IS NULL OR jsonb_typeof(p_outcome)<>'object' OR public.ple_rehearsal_jsonb_bytes(p_outcome)>394240 OR octet_length(p_receipt_digest)<>32 THEN RETURN;END IF;SELECT * INTO run_row FROM public.rehearsal_run WHERE tenant_id=p_tenant AND rehearsal_run_id=route_row.rehearsal_run_id FOR UPDATE;IF NOT FOUND OR run_row.lifecycle<>'active' THEN RETURN;END IF;SELECT claim.*,binding.delivery_root_id,binding.delivery_generation,binding.delivery_operation_id,binding.issued_screen_digest INTO claim_row FROM public.rehearsal_submission_claim_root claim JOIN public.rehearsal_submission_claim_delivery_binding binding ON binding.tenant_id=claim.tenant_id AND binding.rehearsal_run_id=claim.rehearsal_run_id AND binding.claim_id=claim.claim_id WHERE claim.tenant_id=p_tenant AND claim.rehearsal_run_id=route_row.rehearsal_run_id AND claim.claim_id=p_claim FOR UPDATE;IF NOT FOUND OR claim_row.request_fingerprint<>p_request_fingerprint OR claim_row.issued_screen_digest<>p_screen_digest OR claim_row.submission_input->'kind'->>'kind' IS DISTINCT FROM 'rendered' OR NOT public.ple_verify_rehearsal_claim_delivery_binding(p_tenant,route_row.rehearsal_run_id,p_claim) THEN RETURN;END IF;SELECT * INTO event_row FROM public.rehearsal_submission_claim_event WHERE tenant_id=p_tenant AND rehearsal_run_id=route_row.rehearsal_run_id AND claim_id=p_claim ORDER BY sequence DESC LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RETURN;ELSIF event_row.phase='completed' AND event_row.operation_id=p_claim_operation AND event_row.generation=p_claim_generation THEN RETURN QUERY SELECT 'receipt',receipt.outcome_projection,receipt.receipt_digest FROM public.rehearsal_submission_receipt receipt WHERE receipt.tenant_id=p_tenant AND receipt.rehearsal_run_id=route_row.rehearsal_run_id AND receipt.claim_id=p_claim AND receipt.receipt_digest=event_row.receipt_digest;RETURN;ELSIF event_row.phase<>'gradingDispatched' OR event_row.operation_id<>p_claim_operation OR event_row.generation<>p_claim_generation OR run_row.evidence_head_digest<>p_prior_head_digest OR run_row.evidence_length<>p_prior_head_length THEN RETURN;END IF;INSERT INTO public.rehearsal_evidence(tenant_id,rehearsal_run_id,sequence,kind,previous_digest,entry_digest,payload,payload_digest,recorded_at) VALUES(p_tenant,route_row.rehearsal_run_id,p_prior_head_length+1,'acceptedSubmission',p_prior_head_digest,p_entry_digest,p_payload,p_payload_digest,public.ple_rehearsal_timestamp_from_millis(p_accepted_millis));IF NOT public.ple_broker_cas_rehearsal_evidence_head(p_tenant,route_row.rehearsal_run_id,p_prior_head_digest,p_prior_head_length,p_entry_digest) THEN RAISE EXCEPTION 'rehearsal evidence head compare-and-swap failed' USING ERRCODE = '55000';END IF;INSERT INTO public.rehearsal_submission_receipt(tenant_id,rehearsal_run_id,claim_id,outcome_projection,receipt_digest) VALUES(p_tenant,route_row.rehearsal_run_id,p_claim,p_outcome,p_receipt_digest);INSERT INTO public.rehearsal_submission_claim_event(tenant_id,rehearsal_run_id,claim_id,sequence,operation_id,generation,phase,accepted_evidence_sequence,accepted_evidence_digest,receipt_digest) VALUES(p_tenant,route_row.rehearsal_run_id,p_claim,event_row.sequence+1,p_claim_operation,p_claim_generation,'completed',p_prior_head_length+1,p_entry_digest,p_receipt_digest);PERFORM public.ple_broker_terminalize_rehearsal_if_complete(p_tenant,route_row.rehearsal_run_id);RETURN QUERY SELECT 'completed',p_outcome,p_receipt_digest;END $$; CREATE OR REPLACE FUNCTION public.ple_broker_cas_rehearsal_evidence_head(p_tenant uuid,p_run uuid,p_old_digest bytea,p_old_length bigint,p_new_digest bytea) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() OR octet_length(p_old_digest)<>32 OR p_old_length NOT BETWEEN 0 AND 4294967295 OR octet_length(p_new_digest)<>32 THEN RETURN false;END IF;UPDATE public.rehearsal_run SET evidence_head_digest=p_new_digest,evidence_length=p_old_length+1,updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active' AND evidence_head_digest=p_old_digest AND evidence_length=p_old_length;RETURN FOUND;END $$; CREATE OR REPLACE FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(p_tenant uuid,p_run uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO pg_catalog,public,pg_temp AS $$ DECLARE expected_count integer;completed_count integer;BEGIN IF p_tenant IS NULL OR p_tenant IS DISTINCT FROM public.ple_current_tenant() THEN RETURN false;END IF;SELECT expected_item_count INTO expected_count FROM public.rehearsal_frozen_material_set WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;SELECT count(*) INTO completed_count FROM public.rehearsal_accepted_attempt_integrity WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run;IF expected_count IS NULL OR completed_count<>expected_count OR EXISTS(SELECT 1 FROM public.rehearsal_frozen_source_snapshot snapshot_row WHERE snapshot_row.tenant_id=p_tenant AND snapshot_row.rehearsal_run_id=p_run AND NOT EXISTS(SELECT 1 FROM public.rehearsal_accepted_attempt_integrity accepted_row WHERE accepted_row.tenant_id=snapshot_row.tenant_id AND accepted_row.rehearsal_run_id=snapshot_row.rehearsal_run_id AND accepted_row.attempt_id=snapshot_row.attempt_id)) THEN RETURN false;END IF;UPDATE public.rehearsal_run SET lifecycle='completed',terminal_at=public.ple_rehearsal_now(),updated_at=public.ple_rehearsal_now() WHERE tenant_id=p_tenant AND rehearsal_run_id=p_run AND lifecycle='active';RETURN FOUND;END $$; ALTER FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_complete_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,uuid,uuid,integer,bytea,bytea,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) OWNER TO ple_rehearsal_source; ALTER FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea) OWNER TO ple_rehearsal_broker; ALTER FUNCTION public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) OWNER TO ple_rehearsal_broker; REVOKE ALL ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) FROM PUBLIC,ple_app,ple_student,ple_grader,ple_grading_reader; GRANT EXECUTE ON FUNCTION public.ple_broker_cas_rehearsal_evidence_head(uuid,uuid,bytea,bigint,bytea),public.ple_broker_terminalize_rehearsal_if_complete(uuid,uuid) TO ple_rehearsal_source; REVOKE ALL ON FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text),public.ple_complete_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,uuid,uuid,integer,bytea,bytea,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) FROM PUBLIC,ple_app,ple_student,ple_grader; GRANT EXECUTE ON FUNCTION public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text),public.ple_complete_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,uuid,uuid,integer,bytea,bytea,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea) TO ple_grading_reader; DO $$ BEGIN IF has_table_privilege('ple_app','public.rehearsal_delivery_timing_witness','SELECT') OR has_table_privilege('ple_app','public.rehearsal_delivery_retry_operation','SELECT') OR has_table_privilege('ple_app','public.rehearsal_delivery_issued_execution_artifact','SELECT') OR has_table_privilege('ple_grading_reader','public.rehearsal_delivery_issued_execution_artifact','SELECT') OR has_function_privilege('ple_app','public.ple_current_rehearsal_delivery(uuid,uuid)','EXECUTE') OR has_function_privilege('ple_app','public.ple_prepare_or_resume_rehearsal_issued_execution(uuid,uuid)','EXECUTE') OR has_function_privilege('ple_app','public.ple_commit_sealed_rehearsal_issued_execution(uuid,uuid,bytea,bytea)','EXECUTE') OR has_function_privilege('ple_app','public.ple_rehearsal_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea)', 'EXECUTE') OR has_function_privilege('ple_app','public.ple_rehearsal_route_complete_claim(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea)','EXECUTE') OR NOT has_function_privilege('ple_grading_reader','public.ple_prepare_or_resume_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,text)','EXECUTE') OR NOT has_function_privilege('ple_grading_reader','public.ple_complete_sealed_rehearsal_submission(uuid,uuid,uuid,integer,bigint,bigint,uuid,uuid,integer,bytea,bytea,bytea,bigint,bytea,jsonb,bytea,bigint,jsonb,bytea)','EXECUTE') THEN RAISE EXCEPTION 'sealed rehearsal authority is inconsistent' USING ERRCODE='55000';END IF;END $$;-- Freshness registry completion follows all sealed-table RLS setup above.
-- ASVS 8.2.1, 8.4.1: every new sealed relation is visible only to the
-- dedicated witness, which is the sole all-tenant observer for this domain.
INSERT INTO public.ple_base_course_freshness_relation(relation_oid,domain)
SELECT table_row.oid,'sealed_rehearsal'
  FROM pg_catalog.pg_class table_row
  JOIN pg_catalog.pg_namespace namespace ON namespace.oid=table_row.relnamespace
 WHERE namespace.nspname='public' AND table_row.relkind IN('r','p')
   AND table_row.relname IN(
    'rehearsal_frozen_material_set','rehearsal_frozen_source_snapshot',
    'rehearsal_frozen_private_execution','rehearsal_delivery_generation_material_binding',
    'rehearsal_accepted_attempt_integrity','rehearsal_start_freeze_source_binding',
    'rehearsal_submission_claim_delivery_binding','rehearsal_delivery_retry_operation',
    'rehearsal_delivery_timing_witness','rehearsal_delivery_issued_execution_artifact'
   )
ON CONFLICT(relation_oid) DO NOTHING;

DO $$
DECLARE relation_row record;
BEGIN
 FOR relation_row IN
  SELECT table_row.oid,namespace.nspname,table_row.relname,table_row.relrowsecurity
    FROM public.ple_base_course_freshness_relation registry
    JOIN pg_catalog.pg_class table_row ON table_row.oid=registry.relation_oid
    JOIN pg_catalog.pg_namespace namespace ON namespace.oid=table_row.relnamespace
   WHERE registry.domain='sealed_rehearsal'
     AND table_row.relname IN(
      'rehearsal_frozen_material_set','rehearsal_frozen_source_snapshot',
      'rehearsal_frozen_private_execution','rehearsal_delivery_generation_material_binding',
      'rehearsal_accepted_attempt_integrity','rehearsal_start_freeze_source_binding',
      'rehearsal_submission_claim_delivery_binding','rehearsal_delivery_retry_operation',
      'rehearsal_delivery_timing_witness','rehearsal_delivery_issued_execution_artifact'
     )
 LOOP
  EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM ple_base_course_freshness_broker',relation_row.nspname,relation_row.relname);
  EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM ple_rehearsal_freshness_witness',relation_row.nspname,relation_row.relname);
  EXECUTE format('GRANT SELECT,MAINTAIN ON TABLE %I.%I TO ple_rehearsal_freshness_witness',relation_row.nspname,relation_row.relname);
  IF relation_row.relrowsecurity THEN
   EXECUTE format('DROP POLICY IF EXISTS ple_base_course_freshness_select ON %I.%I',relation_row.nspname,relation_row.relname);
   EXECUTE format('CREATE POLICY ple_rehearsal_freshness_witness_select ON %I.%I FOR SELECT TO ple_rehearsal_freshness_witness USING(true)',relation_row.nspname,relation_row.relname);
  END IF;
 END LOOP;
END $$;

-- Migration-time exact coverage assertion: a future public table is a hard
-- configuration failure until its owner registers its intended domain.
DO $$
BEGIN
 IF EXISTS(
  WITH expected(relation_oid) AS (
   SELECT table_row.oid
     FROM pg_catalog.pg_class table_row
     JOIN pg_catalog.pg_namespace namespace ON namespace.oid=table_row.relnamespace
    WHERE namespace.nspname='public' AND table_row.relkind IN('r','p')
      AND table_row.relname NOT IN('_sqlx_migrations','question_id_namespace','ple_base_course_freshness_relation','ple_base_course_freshness_domain')
  ), actual AS (
   SELECT relation_oid FROM public.ple_base_course_freshness_relation
  ) SELECT 1 FROM ((SELECT * FROM expected EXCEPT SELECT * FROM actual)
                   UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) difference
 ) OR (SELECT count(*) FROM public.ple_base_course_freshness_relation registry JOIN pg_catalog.pg_class table_row ON table_row.oid=registry.relation_oid WHERE registry.domain='sealed_rehearsal' AND table_row.relname IN('rehearsal_frozen_material_set','rehearsal_frozen_source_snapshot','rehearsal_frozen_private_execution','rehearsal_delivery_generation_material_binding','rehearsal_accepted_attempt_integrity','rehearsal_start_freeze_source_binding','rehearsal_submission_claim_delivery_binding','rehearsal_delivery_retry_operation','rehearsal_delivery_timing_witness','rehearsal_delivery_issued_execution_artifact'))<>10 THEN RAISE EXCEPTION 'Base Course freshness registry is inconsistent' USING ERRCODE='55000'; END IF;
END $$;
COMMIT;
